// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/atippatY/col.qmz — சரம் (string) helpers__
// சரத்தைக் கையாளும் துணைச் செயல்கள்
//
// __Written in eTamil, not Rust. The only primitives borrowed from the host__
// __are நீளம், சொல்லாக்கு and indexing; everything here is built from those.__

// __எழுத்து(சரம், எழுத்திடம்) — the letter at a position, or "" past either end.__
// எழுத்து(சரம், எழுத்திடம்) — அவ்விடத்தில் உள்ள எழுத்து; எல்லையைத் தாண்டினால் வெற்றுச் சரம்
//
// __This was once necessary: மற்றும் evaluated both sides, so a guard like__
// __`(இ < நீளம்(சரம்) மற்றும் சரம்[இ] == " ")` indexed out of bounds on the very__
// __step that failed the first test. மற்றும் short-circuits now, so that guard__
// __is safe to write directly. This stays because "the letter there, or nothing"__
// __is worth saying in one word, not because indexing needs guarding.__
//
// __The parameter is எழுத்திடம் rather than the plainer இடம் because that word__
// __is the SQL LEFT keyword and is hard reserved — it cannot be a name at all.__
// எழுத்து(சரம், எழுத்திடம்) — அவ்விடத்தில் உள்ள எழுத்து; இல்லையேல் வெற்றுச் சரம்
செயல் எழுத்து(சரம், எழுத்திடம்) {
    (எழுத்திடம் < 0) எனில் { திரும்பு ""; }
    (எழுத்திடம் >= நீளம்(சரம்)) எனில் { திரும்பு ""; }
    திரும்பு சரம்[எழுத்திடம்];
}

// __துண்டு(சரம், தொடக்கம், அளவு) — substring__
// துண்டு(சரம், தொடக்கம், அளவு) — சரத்தின் ஒரு பகுதியைத் தரும்
செயல் துண்டு(சரம், தொடக்கம், அளவு) {
    விடை = "";
    எண்ணி = தொடக்கம்;
    முடிவு = தொடக்கம் + அளவு;
    மொத்தம் = நீளம்(சரம்);
    (எண்ணி < முடிவு மற்றும் எண்ணி < மொத்தம்) சுற்று {
        விடை = விடை & சரம்[எண்ணி];
        எண்ணி = எண்ணி + 1;
    }
    திரும்பு விடை;
}

// __தேடு(சரம், தேடல்) — position of the first match, or -1__
// தேடு(சரம், தேடல்) — முதன்முதலில் பொருந்தும் இடம்; இல்லையெனில் ஒன்று குறை
செயல் தேடு(சரம், தேடல்) {
    மொத்தம் = நீளம்(சரம்);
    அளவு = நீளம்(தேடல்);
    (அளவு == 0) எனில் { திரும்பு 0; }
    எண்ணி = 0;
    (எண்ணி + அளவு <= மொத்தம்) சுற்று {
        (துண்டு(சரம், எண்ணி, அளவு) == தேடல்) எனில் {
            திரும்பு எண்ணி;
        }
        எண்ணி = எண்ணி + 1;
    }
    திரும்பு 0 - 1;
}

// __கொண்டுள்ளதா(சரம், தேடல்) — does it contain?__
// கொண்டுள்ளதா(சரம், தேடல்) — இது சரத்தில் இருக்கிறதா
செயல் கொண்டுள்ளதா(சரம், தேடல்) {
    திரும்பு தேடு(சரம், தேடல்) >= 0;
}

// தொடங்குகிறதா(சரம், முன்னொட்டு)
// __தொடங்குகிறதா(சரம், முன்னொட்டு) — does the string start with this prefix?__
// தொடங்குகிறதா(சரம், முன்னொட்டு) — இந்த முன்னொட்டுடன் சரம் தொடங்குகிறதா
//
// __Checks the length first, so a prefix longer than the string answers பொய் rather than slicing past the end. Counts in characters, not bytes, which is what makes it correct for Tamil text where one letter is several bytes.__
செயல் தொடங்குகிறதா(சரம், முன்னொட்டு) {
    அளவு = நீளம்(முன்னொட்டு);
    (அளவு > நீளம்(சரம்)) எனில் { திரும்பு பொய்; }
    திரும்பு துண்டு(சரம், 0, அளவு) == முன்னொட்டு;
}

// முடிகிறதா(சரம், பின்னொட்டு)
// __முடிகிறதா(சரம், பின்னொட்டு) — does the string end with this suffix?__
// முடிகிறதா(சரம், பின்னொட்டு) — இந்தப் பின்னொட்டுடன் சரம் முடிகிறதா
//
// __The mirror of தொடங்குகிறதா, offsetting from the end. Same length guard and the same character-based counting.__
செயல் முடிகிறதா(சரம், பின்னொட்டு) {
    அளவு = நீளம்(பின்னொட்டு);
    மொத்தம் = நீளம்(சரம்);
    (அளவு > மொத்தம்) எனில் { திரும்பு பொய்; }
    திரும்பு துண்டு(சரம், மொத்தம் - அளவு, அளவு) == பின்னொட்டு;
}

// __ஒழுங்கு(சரம்) — trim spaces from both ends__
// ஒழுங்கு(சரம்) — இரு முனைகளிலும் உள்ள இடைவெளிகளை நீக்கும்
//
// __Both scans read through எழுத்து. Written as a direct index this crashed on__
// __"" and on a string of nothing but spaces: the loop guard was correct, but__
// __மற்றும் evaluates its right side anyway, so the index ran off the end.__
செயல் ஒழுங்கு(சரம்) {
    தொடக்கம் = 0;
    (எழுத்து(சரம், தொடக்கம்) == " ") சுற்று {
        தொடக்கம் = தொடக்கம் + 1;
    }
    முடிவு = நீளம்(சரம்);
    (முடிவு > தொடக்கம் மற்றும் எழுத்து(சரம், முடிவு - 1) == " ") சுற்று {
        முடிவு = முடிவு - 1;
    }
    திரும்பு துண்டு(சரம், தொடக்கம், முடிவு - தொடக்கம்);
}

// __பிரி(சரம், பிரிப்பான்) and ஒன்றிணை(அணி, இணைப்பான்) are host builtins now.__
//
// __They were written here, in eTamil, like everything else in this file. Both__
// __walked the string a letter at a time, and each read re-segmented the whole__
// __string into letters, so splitting a document cost O(n²) segmentations —__
// __14 seconds over 8 KB, and 400 KB never finished. The host does one__
// __segmentation pass and then a byte search. The letter-boundary rule is__
// __unchanged, so the pieces are the same pieces; only the cost differs.__
//
// __A function defined here would shadow the builtin, so they are gone rather__
// __than delegating. See மாற்று too, which is new and has no version here.__

// __திரும்பச்செய்(சரம், எண்ணிக்கை) — repeat__
// திரும்பச்செய்(சரம், எண்ணிக்கை) — சரத்தைச் சொன்ன முறை திரும்பத் தரும்
செயல் திரும்பச்செய்(சரம், எண்ணிக்கை) {
    விடை = "";
    எண்ணி = 0;
    (எண்ணி < எண்ணிக்கை) சுற்று {
        விடை = விடை & சரம்;
        எண்ணி = எண்ணி + 1;
    }
    திரும்பு விடை;
}

// __இடமிருந்து_நிரப்பு(சரம், அகலம், நிரப்பி) — left pad__
// இடமிருந்து_நிரப்பு(சரம், அகலம், நிரப்பி) — இடப்பக்கம் நிரப்பி சொன்ன அகலத்தை நிறைக்கும்
செயல் இடமிருந்து_நிரப்பு(சரம், அகலம், நிரப்பி) {
    விடை = சொல்லாக்கு(சரம்);
    (நீளம்(விடை) < அகலம்) சுற்று {
        விடை = நிரப்பி & விடை;
    }
    திரும்பு விடை;
}

nUlakam/atippatY/eNkaL.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/atippatY/eNkaL.qmz — எண்கள் (numbers): the operations on one or two of them__
// எண்கள்: ஒன்று அல்லது இரண்டு எண்களின்மேல் செய்வன
//
// __Nothing here looks at a collection, and nothing here knows about money.__
// __That is what makes them safe to import everywhere: சிறியது clamps a pin__
// __number as readily as it clamps an allowance.__

// __முழுமதிப்பு(எண்) — absolute value__
// முழுமதிப்பு(எண்) — குறியின்றி எண்ணின் அளவு
செயல் முழுமதிப்பு(மதிப்பு) {
    (மதிப்பு < 0) எனில் { திரும்பு 0 - மதிப்பு; }
    திரும்பு மதிப்பு;
}

// சிறியது(அ, ஆ) / பெரியது(அ, ஆ)
// சிறியது(அ, ஆ) — இரண்டில் சிறிய எண்
// __சிறியது(அ, ஆ) — the smaller of two numbers__
//
// __A tie returns ஆ, which matters only in that the values are equal. Present so callers do not write the comparison inline, where reversing it is easy and the mistake reads as correct.__
செயல் சிறியது(அ, ஆ) {
    (அ < ஆ) எனில் { திரும்பு அ; }
    திரும்பு ஆ;
}

// __பெரியது(அ, ஆ) — the larger of two numbers__
// பெரியது(அ, ஆ) — இரண்டில் பெரிய எண்
//
// __The pair to சிறியது. Between them they cover the clamping that shows up all over the accounting modules: an allowance that cannot go below zero, a claim capped at the sum insured.__
செயல் பெரியது(அ, ஆ) {
    (அ > ஆ) எனில் { திரும்பு அ; }
    திரும்பு ஆ;
}

// __முழு_எண்ணா(மதிப்பு) — is this a whole number?__
// முழு_எண்ணா(மதிப்பு) — இது முழு எண்ணா
செயல் முழு_எண்ணா(மதிப்பு) {
    திரும்பு தரை(மதிப்பு) == மதிப்பு;
}

// __மீதி(எண், வகுப்பான்) — the remainder, since there is no % operator__
// மீதி(எண், வகுப்பான்) — வகுத்தபின் மிஞ்சுவது; மீதிக்கெனச் செயற்குறி இல்லை
//
// __Written here rather than added to the host: it follows from தரை and the__
// __arithmetic the language already has, so Layer 0 gains nothing by owning it.__
செயல் மீதி(எண்_மதிப்பு, வகுப்பான்) {
    (வகுப்பான் == 0) எனில் { திரும்பு 0; }
    திரும்பு எண்_மதிப்பு - தரை(எண்_மதிப்பு / வகுப்பான்) * வகுப்பான்;
}

nUlakam/atippatY/kaNiqam.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/atippatY/kaNiqam.qmz — கணிதம் (math) helpers__
// கணிதத்திற்கான துணைச் செயல்கள்
//
// __Rounding, floor and ceiling come from the host because they need the__
// __decimal representation itself. What was built from those is split__
// __across the three files imported below.__

// __Split into the files below. This one keeps the name so that every__
// __`இறக்கு` of it still reaches every function it used to.__

இறக்கு "eNkaL.qmz";
இறக்கு "qokuppu.qmz";
இறக்கு "vikiqam.qmz";

// __வர்க்கமூலம்(மதிப்பு) is a host builtin now.__
//
// __It was Newton's method here, written in eTamil because the host had no__
// __square root and the arithmetic to build one was all the language gave.__
// __Forty iterations per call, and it was never quite exact: √25 came back__
// __as 5.000000000000000000000288615.__
//
// __The host computes it on the Decimal itself, not through f64, so it is__
// __both faster and exact — √25 is 5. A negative input is still a தவறு for__
// __the reason it always was: the root of a negative variance is a sign__
// __error upstream, and answering zero hides it inside a confidence figure__
// __that looks perfectly reasonable.__
//
// __A function defined here would shadow the builtin, so it is gone rather__
// __than delegating.__

nUlakam/atippatY/poruL.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/atippatY/poruL.qmz — பொருள் (record) helpers__
// பதிவேட்டைக் கையாளும் துணைச் செயல்கள்
//
// __Indexing a record by a field it does not have is an error, which is right__
// __for a field a program expects and wrong for one it merely allows. A query__
// __string with no `status` in it is an ordinary request, not a fault, and an__
// __HTTP handler that crashes on the absence of an optional parameter is__
// __unusable — so reading one needs a way to say "or this instead".__
//
// __ஒவ்வொரு over a record yields its field names, so the rest of this file__
// __is ordinary eTamil.__
//
// __The parameter is named பதிவேடு rather than the plainer பொருள் because that__
// __word is the record type keyword and is hard reserved — it cannot be a name.__

// __புலம்_உள்ளதா(பதிவேடு, பெயர்) and புலம்_அல்லது(பதிவேடு, பெயர், மாற்று) are__
// __host builtins now.__
//
// __Both were written here, in eTamil, like everything else in this file.__
// __Neither could be: asking whether a record has a field meant walking its__
// __field names, because that is the only thing the language offers from the__
// __inside, and reading one meant walking them twice. That made a record__
// __unusable as a map — n lookups over n keys cost 0.12 seconds at a hundred__
// __keys and 61.6 seconds at eight hundred, and building a word-frequency__
// __map over a corpus never finished at all.__
//
// __The host does one hash lookup. A function defined here would shadow the__
// __builtin, so they are gone rather than delegating — see col.qmz, where__
// __பிரி and ஒன்றிணை left for the same reason.__

// __புலங்கள்(பதிவேடு) — the field names, as an array__
// புலங்கள்(பதிவேடு) — புலப் பெயர்கள் அணியாக
செயல் புலங்கள்(பதிவேடு) {
    விடை = [];
    ஒவ்வொரு புலப்_பெயர் இல் பதிவேடு {
        விடை = இணை(விடை, புலப்_பெயர்);
    }
    திரும்பு விடை;
}

// __மதிப்பீடுகள்(பதிவேடு) — the values, in the same order as புலங்கள்__
// மதிப்பீடுகள்(பதிவேடு) — மதிப்புகள், புலங்கள் வரிசையிலேயே
//
// __Not மதிப்புகள்: மதிப்பு is the builtin that opens a result, and a name__
// __that close to it reads as though this were the plural of that.__
செயல் மதிப்பீடுகள்(பதிவேடு) {
    விடை = [];
    ஒவ்வொரு புலப்_பெயர் இல் பதிவேடு {
        விடை = இணை(விடை, பதிவேடு[புலப்_பெயர்]);
    }
    திரும்பு விடை;
}

// __காலியா_பதிவேடு(பதிவேடு) — no fields at all?__
// காலியா_பதிவேடு(பதிவேடு) — புலமே இல்லையா
செயல் காலியா_பதிவேடு(பதிவேடு) {
    திரும்பு நீளம்(பதிவேடு) == 0;
}

nUlakam/atippatY/qokuppu.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/atippatY/qokuppu.qmz — தொகுப்பு (aggregates): reading one number out of many__
// தொகுப்பு: பல எண்களிலிருந்து ஒரு எண்
//
// __சராசரி, மிகச்சிறியது and மிகப்பெரியது answer தவறு for an empty array__
// __rather than zero. The least of nothing is not nothing, and a zero that__
// __means "there was nothing" survives into a report looking like a figure.__

// __கூட்டு(அணி) — sum of an array__
// கூட்டு(அணி) — அணியில் உள்ள எண்களின் கூட்டுத்தொகை
செயல் கூட்டு(பட்டியல்) {
    மொத்தம் = 0;
    ஒவ்வொரு உறுப்பு இல் பட்டியல் {
        மொத்தம் = மொத்தம் + உறுப்பு;
    }
    திரும்பு மொத்தம்;
}

// __சராசரி(அணி) — mean; an empty array is an error, not a division by zero__
// சராசரி(அணி) — சராசரி; காலி அணி தவறு, பூஜ்ஜியத்தால் வகுத்தல் அல்ல
செயல் சராசரி(பட்டியல்) {
    எண்ணிக்கை = நீளம்(பட்டியல்);
    (எண்ணிக்கை == 0) எனில் {
        திரும்பு தவறு("காலி அணியின் சராசரி இல்லை  (no average of an empty array)");
    }
    திரும்பு சரி(கூட்டு(பட்டியல்) / எண்ணிக்கை);
}

// மிகச்சிறியது(அணி) / மிகப்பெரியது(அணி)
// மிகச்சிறியது(பட்டியல்) — அணியின் மிகச் சிறிய உறுப்பு
// __மிகச்சிறியது(பட்டியல்) — the smallest element of an array__
//
// __சரி with the value, or தவறு for an empty array. Empty has no minimum, and answering zero would be a lie that survives into a report — the least of nothing is not nothing.__
செயல் மிகச்சிறியது(பட்டியல்) {
    (நீளம்(பட்டியல்) == 0) எனில் {
        திரும்பு தவறு("காலி அணி  (empty array)");
    }
    விடை = பட்டியல்[0];
    ஒவ்வொரு உறுப்பு இல் பட்டியல் {
        (உறுப்பு < விடை) எனில் { விடை = உறுப்பு; }
    }
    திரும்பு சரி(விடை);
}

// __மிகப்பெரியது(பட்டியல்) — the largest element of an array__
// மிகப்பெரியது(பட்டியல்) — அணியின் மிகப் பெரிய உறுப்பு
//
// __The pair to மிகச்சிறியது, and தவறு on empty for the same reason. Walks the array once rather than sorting it, so the cost is linear and the original order is untouched.__
செயல் மிகப்பெரியது(பட்டியல்) {
    (நீளம்(பட்டியல்) == 0) எனில் {
