// __nUlakam/nErativari/mUlavari.qmz — மூலவரி, tax deducted at source__
// மூலவரி: மூலத்திலேயே பிடிக்கப்படும் வரி
//
// __Tax deducted at source is not a tax. It is a collection mechanism, and the__
// __person it falls on is not the person who owes anything: the payer deducts,__
// __deposits, and is personally liable for the whole amount plus interest if the__
// __deduction was short — while the payee's actual liability may well be nil.__
//
// __That asymmetry is why the arithmetic here is worth getting right. An__
// __under-deduction costs the deductor money that cannot be recovered from__
// __anybody, and an over-deduction costs the payee a year's use of the money and__
// __a refund claim.__
//
// __Three rules do most of the damage.__
//
// __**The threshold is not an exemption.** Once the year's aggregate crosses the__
// __limit, tax is deducted on the **whole aggregate** — including the earlier__
// __payments that were individually below it. Deducting only on the excess is__
// __the commonest error in this whole area, and it is always an under-deduction.__
//
// __**There are two thresholds, and either one triggers.** A single payment__
// __limit and an annual aggregate limit, and a payment can breach the first__
// __while the year is nowhere near the second.__
//
// __**Part of a month is a month.** Interest for late deduction or late payment__
// __is charged by the month, and a single day's delay into a new month costs a__
// __full month's interest. It is charged from the date the tax was deductible,__
// __not from the date it was due to be deposited.__
//
// __Rates, thresholds and the no-PAN floor are all parameters. They are stated__
// __per section and amended constantly; vari_vikiqam.qmz is where they live.__

இறக்கு "../atippatY/kaNiqam.qmz";
இறக்கு "../atippatY/poruL.qmz";

// =========================================================================
// __ஒரு பிரிவு — a section__
// =========================================================================
//
// பிரிவு_ஆக்கு(பிரிவுக்_குறி, விவரம், பிடித்த_வீதம், ஒரு_முறை_எல்லை,
//               ஆண்டு_எல்லை)
//
// __Pass 0 for a threshold that does not exist. A section with neither — tax__
// __deducted on the first rupee — is written with both as 0 and behaves__
// __correctly: பிடிக்க_வேண்டுமா then says yes to any positive payment.__
// பிரிவு_ஆக்கு(பிரிவுக்_குறி, விவரம், பிடித்த_வீதம், ஒரு_முறை_எல்லை, ஆண்டு_எல்லை) — ஒரு மூலவரிப் பிரிவை வரையறுக்கும்
செயல் பிரிவு_ஆக்கு(பிரிவுக்_குறி, விவரம், பிடித்த_வீதம், ஒரு_முறை_எல்லை,
                     ஆண்டு_எல்லை) {
    திரும்பு {"பிரிவு": பிரிவுக்_குறி,
              "விவரம்": விவரம்,
              "வீதம்": பிடித்த_வீதம்,
              "ஒரு_முறை_எல்லை": ஒரு_முறை_எல்லை,
              "ஆண்டு_எல்லை": ஆண்டு_எல்லை};
}

// =========================================================================
// __எப்போது பிடிக்க வேண்டும் — when to deduct__
// =========================================================================
//
// பிடிக்க_வேண்டுமா(ஒரு_பிரிவு, இந்தத்_தொகை, முன்பு_செலுத்தியது)
//
// __முன்பு_செலுத்தியது is what has already been paid to this payee under this__
// __section this year, before the payment being considered.__
//
// __Either threshold triggers, and the aggregate one is tested **including** the__
// __current payment. A year of eight payments of twenty thousand under a section__
// __with a single-payment limit of thirty thousand and an annual limit of a lakh__
// __crosses on the sixth, not on any single one of them.__
// பிடிக்க_வேண்டுமா(ஒரு_பிரிவு, இந்தத்_தொகை, முன்பு_செலுத்தியது) — இச்செலுத்தலுக்கு மூலவரி பிடிக்க வேண்டுமா
செயல் பிடிக்க_வேண்டுமா(ஒரு_பிரிவு, இந்தத்_தொகை, முன்பு_செலுத்தியது) {
    (இந்தத்_தொகை <= 0) எனில் { திரும்பு பொய்; }

    ஒரு_முறை = ஒரு_பிரிவு["ஒரு_முறை_எல்லை"];
    ஆண்டு = ஒரு_பிரிவு["ஆண்டு_எல்லை"];

    // __No thresholds at all: deduct on everything.__
    (ஒரு_முறை <= 0 மற்றும் ஆண்டு <= 0) எனில் { திரும்பு மெய்; }

    (ஒரு_முறை > 0 மற்றும் இந்தத்_தொகை > ஒரு_முறை) எனில் { திரும்பு மெய்; }
    (ஆண்டு > 0 மற்றும் முன்பு_செலுத்தியது + இந்தத்_தொகை > ஆண்டு) எனில் {
        திரும்பு மெய்;
    }
    திரும்பு பொய்;
}

// பிடித்த_அடிப்படை(ஒரு_பிரிவு, இந்தத்_தொகை, முன்பு_செலுத்தியது,
//                    முன்பு_பிடித்தது)
//
// __What this payment's deduction is computed on — and it is not always this__
// __payment.__
//
// __When the annual aggregate is what has just been crossed, the base is the__
// __**whole aggregate to date**, and credit is given for whatever was already__
// __deducted. So the payment that crosses the line carries the deduction for__
// __every payment before it, and a twenty-thousand rupee invoice can attract tax__
// __on a lakh and twenty thousand. Deductors who bill monthly meet this once a__
// __year, in the month it happens, and it is never a welcome surprise.__
//
// __முன்பு_பிடித்தது is what has already been deducted this year under this__
// __section, so that a year which crossed the single-payment limit earlier does__
// __not pay twice on the same money.__
// பிடித்த_அடிப்படை(விலைப்பட்டியல்_மொத்தம், வணிகவரித்_தொகை, நீக்கவா) — மூலவரி கணக்கிடப்படும் அடிப்படைத் தொகை
செயல் பிடித்த_அடிப்படை(ஒரு_பிரிவு, இந்தத்_தொகை, முன்பு_செலுத்தியது,
                         முன்பு_பிடித்தது) {
    (இல்லை பிடிக்க_வேண்டுமா(ஒரு_பிரிவு, இந்தத்_தொகை, முன்பு_செலுத்தியது)) எனில் {
        திரும்பு {"அடிப்படை": 0, "முழு_ஆண்டா": பொய்};
    }

    ஆண்டு = ஒரு_பிரிவு["ஆண்டு_எல்லை"];
    ஒரு_முறை = ஒரு_பிரிவு["ஒரு_முறை_எல்லை"];

    // __The aggregate limit is breached, so the whole year is in charge. This__
    // __also covers the case where it was breached in an earlier payment: the__
    // __credit for முன்பு_பிடித்தது is what keeps that from double counting.__
    (ஆண்டு > 0 மற்றும் முன்பு_செலுத்தியது + இந்தத்_தொகை > ஆண்டு) எனில் {
        திரும்பு {"அடிப்படை": வட்டமிடு(முன்பு_செலுத்தியது + இந்தத்_தொகை, 2),
                  "முழு_ஆண்டா": மெய்,
                  "முன்பு_பிடித்தது": முன்பு_பிடித்தது};
    }

    // __Only the single-payment limit is breached: this payment alone.__
    (ஒரு_முறை > 0 மற்றும் இந்தத்_தொகை > ஒரு_முறை) எனில் {
        திரும்பு {"அடிப்படை": வட்டமிடு(இந்தத்_தொகை, 2), "முழு_ஆண்டா": பொய்};
    }

    திரும்பு {"அடிப்படை": வட்டமிடு(இந்தத்_தொகை, 2), "முழு_ஆண்டா": பொய்};
}

// =========================================================================
// __வீதம் — the rate that applies__
// =========================================================================
//
// பயன்படும்_வீதம்(பிரிவு_வீதம், பான்_உள்ளதா, பான்_இல்லா_தளம்,
//                  சான்று_உள்ளதா, சான்று_வீதம்)
//
// __Three things can change a section's rate, and they do not compose the way__
// __you would guess.__
//
// __**No PAN** (section 206AA) means the higher of the section rate and a__
// __statutory floor. Higher, not the floor — a section whose rate already__
// __exceeds the floor is unaffected, and replacing its rate with the floor would__
// __be an under-deduction.__
//
// __**A certificate** under section 197 for lower or nil deduction replaces the__
// __rate entirely, including with zero.__
//
// __A certificate does not survive a missing PAN. The floor applies regardless,__
// __which is the one interaction between the two, and the reason the order here__
// __is certificate first and floor second rather than the other way round.__
// பயன்படும்_வீதம்(ஒரு_பிரிவு, நிரந்தரக்_கணக்கெண்_உண்டா) — பொருந்தும் பிடித்த வீதம்
செயல் பயன்படும்_வீதம்(பிரிவு_வீதம், பான்_உள்ளதா, பான்_இல்லா_தளம்,
                        சான்று_உள்ளதா, சான்று_வீதம்) {
    பயன்_வீதம் = பிரிவு_வீதம்;
    (சான்று_உள்ளதா) எனில் { பயன்_வீதம் = சான்று_வீதம்; }

    (இல்லை பான்_உள்ளதா) எனில் {
        (பான்_இல்லா_தளம் > பயன்_வீதம்) எனில் { பயன்_வீதம் = பான்_இல்லா_தளம்; }
    }
    திரும்பு பயன்_வீதம்;
}

// வரி_நீக்கிய_அடிப்படை(விலைப்பட்டியல்_மொத்தம், வணிகவரித்_தொகை, நீக்கவா)
//
// __Whether tax is deducted on the invoice including GST or excluding it depends__
// __on the section, and where the GST is shown separately the department's own__
// __circular says to exclude it. Where it is not shown separately there is__
// __nothing to exclude and the whole invoice is the base.__
//
// __A flag rather than an inference, because "shown separately" is a fact about__
// __the document and not about the numbers.__
// வரி_நீக்கிய_அடிப்படை(விலைப்பட்டியல்_மொத்தம், வணிகவரித்_தொகை, நீக்கவா) — வணிக வரியை நீக்கிய அடிப்படை
செயல் வரி_நீக்கிய_அடிப்படை(விலைப்பட்டியல்_மொத்தம், வணிகவரித்_தொகை, நீக்கவா) {
    (இல்லை நீக்கவா) எனில் { திரும்பு வட்டமிடு(விலைப்பட்டியல்_மொத்தம், 2); }
    விடை = விலைப்பட்டியல்_மொத்தம் - வணிகவரித்_தொகை;
    (விடை < 0) எனில் { திரும்பு 0; }
    திரும்பு வட்டமிடு(விடை, 2);
}

// =========================================================================
// __பிடித்தம் — the deduction__
// =========================================================================
//
// பிடித்தத்_தொகை(ஒரு_பிரிவு, இந்தத்_தொகை, முன்பு_செலுத்தியது,
//                  முன்பு_பிடித்தது, பயன்_வீதம்)
//
// __The whole thing for one payment. Answers {"அடிப்படை", "வீதம்", "பிடித்தம்",__
// "முழு_ஆண்டா"}.
//
// __The credit for earlier deductions is taken **after** the rate is applied to__
// __the aggregate, not before — so the answer is the tax on the year to date__
// __less the tax already taken, and never negative. A year in which the rate__
// __fell mid-year can produce a computed liability lower than what has already__
// __been deducted, and the answer to that is to deduct nothing further, not to__
// __refund from the payer's own pocket.__
// பிடித்தத்_தொகை(ஒரு_பிரிவு, இந்தத்_தொகை, முன்பு_செலுத்தியது, நிரந்தரக்_கணக்கெண்_உண்டா) — பிடிக்க வேண்டிய தொகை
செயல் பிடித்தத்_தொகை(ஒரு_பிரிவு, இந்தத்_தொகை, முன்பு_செலுத்தியது,
                       முன்பு_பிடித்தது, பயன்_வீதம்) {
    விவரங்கள் = பிடித்த_அடிப்படை(ஒரு_பிரிவு, இந்தத்_தொகை,
                                  முன்பு_செலுத்தியது, முன்பு_பிடித்தது);
    அடிப்படை_மதிப்பு = விவரங்கள்["அடிப்படை"];
    (அடிப்படை_மதிப்பு <= 0) எனில் {
        திரும்பு {"அடிப்படை": 0, "வீதம்": பயன்_வீதம், "பிடித்தம்": 0,
                  "முழு_ஆண்டா": பொய்};
    }

    கணக்கிட்டது = சதவீதம்(அடிப்படை_மதிப்பு, பயன்_வீதம்);
    (விவரங்கள்["முழு_ஆண்டா"]) எனில் {
        கணக்கிட்டது = கணக்கிட்டது - முன்பு_பிடித்தது;
    }
    (கணக்கிட்டது < 0) எனில் { கணக்கிட்டது = 0; }

    திரும்பு {"அடிப்படை": அடிப்படை_மதிப்பு,
              "வீதம்": பயன்_வீதம்,
              "பிடித்தம்": வட்டமிடு(கணக்கிட்டது, 2),
              "முழு_ஆண்டா": விவரங்கள்["முழு_ஆண்டா"]};
}

// ஆண்டுப்_பிடித்தம்(ஒரு_பிரிவு, செலுத்தல்கள், பயன்_வீதம்)
//
// __A whole year of payments to one payee, run in order, so that the payment__
// __which crosses the aggregate carries the catch-up. Answers each payment's__
// __deduction and the year's totals.__
//
// __Running the year is the only way to get this right. Applying the rate to the__
// __year's total at the end gives the same grand total and the wrong month for__
// __every deduction, and the month is what the quarterly return and the interest__
// __computation are about.__
// ஆண்டுப்_பிடித்தம்(ஒரு_பிரிவு, செலுத்தல்கள், பயன்_வீதம்) — ஆண்டு முழுவதற்கும் பிடித்தம்
செயல் ஆண்டுப்_பிடித்தம்(ஒரு_பிரிவு, செலுத்தல்கள், பயன்_வீதம்) {
    ஓடும்_செலுத்தல் = 0;
    ஓடும்_பிடித்தம் = 0;
    வரிசைகள் = [];

    ஒவ்வொரு ஒரு_தொகை இல் செலுத்தல்கள் {
        விளைவு = பிடித்தத்_தொகை(ஒரு_பிரிவு, ஒரு_தொகை, ஓடும்_செலுத்தல்,
                                 ஓடும்_பிடித்தம், பயன்_வீதம்);
        வரிசைகள் = இணை(வரிசைகள், {"செலுத்திய_தொகை": ஒரு_தொகை,
                                    "அடிப்படை": விளைவு["அடிப்படை"],
                                    "பிடித்தம்": விளைவு["பிடித்தம்"],
                                    "முழு_ஆண்டா": விளைவு["முழு_ஆண்டா"]});
        ஓடும்_செலுத்தல் = வட்டமிடு(ஓடும்_செலுத்தல் + ஒரு_தொகை, 2);
        ஓடும்_பிடித்தம் = வட்டமிடு(ஓடும்_பிடித்தம் + விளைவு["பிடித்தம்"], 2);
    }

    திரும்பு {"வரிசைகள்": வரிசைகள்,
              "மொத்தச்_செலுத்தல்": ஓடும்_செலுத்தல்,
              "மொத்தப்_பிடித்தம்": ஓடும்_பிடித்தம்};
}

// =========================================================================
// __தாமதம் — interest for default__
// =========================================================================
//
// முழு_மாதங்கள்(நாட்களின்_எண்ணிக்கை)
//
// __Part of a month counts as a whole month, so twenty-eight days is one month__
// __and thirty-two is two. This is the rule that makes a one-day delay cost a__
// __month's interest.__
//
// __It divides by thirty and rounds up, which is right whenever the delay is__
// __counted in days. Where real dates are available the statute counts__
// __**calendar** months, and February will disagree with this by a day — so a__
// __caller holding dates should count the calendar months itself and pass the__
// __interest functions that number instead.__
// முழு_மாதங்கள்(நாட்களின்_எண்ணிக்கை) — நாட்களை முழு மாதங்களாக; பகுதி மாதமும் ஒன்றாகக் கணக்கு
செயல் முழு_மாதங்கள்(நாட்களின்_எண்ணிக்கை) {
    திரும்பு வட்ட_மாதங்கள்(நாட்களின்_எண்ணிக்கை);
}

// பிடிக்காத_வட்டி(பிடிக்க_வேண்டியது, மாத_வீதம், மாதங்கள்)
//
// __Interest for failing to deduct, at the lower monthly rate, running from the__
// __date the tax was **deductible** — not from the date it would have been due__
// __for deposit. The clock starts at the invoice, and a deductor who discovers__
// __the default a year later owes twelve months.__
// பிடிக்காத_வட்டி(பிடிக்க_வேண்டியது, மாத_வீதம், மாதங்கள்) — பிடிக்கத் தவறியதற்கான வட்டி
செயல் பிடிக்காத_வட்டி(பிடிக்க_வேண்டியது, மாத_வீதம், மாதங்கள்) {
    திரும்பு வட்டித்_தொகை(பிடிக்க_வேண்டியது, மாத_வீதம், மாதங்கள்);
}

// செலுத்தாத_வட்டி(பிடித்த_தொகை, மாத_வீதம், மாதங்கள்)
//
// __Interest for deducting and not depositing, at the higher monthly rate. The__
// __rate is higher because the money is the government's and is being held: this__
// __is not a late payment of the deductor's own liability but a failure to hand__
// __over somebody else's tax.__
// செலுத்தாத_வட்டி(பிடித்த_தொகை, மாத_வீதம், மாதங்கள்) — பிடித்தும் செலுத்தாததற்கான வட்டி
செயல் செலுத்தாத_வட்டி(பிடித்த_தொகை, மாத_வீதம், மாதங்கள்) {
    திரும்பு வட்டித்_தொகை(பிடித்த_தொகை, மாத_வீதம், மாதங்கள்);
}

// =========================================================================
// __சம்பளப் பிடித்தம் — TDS on salary__
// =========================================================================
//
// சம்பள_பிடித்தம்(ஆண்டு_வரி, மீதி_மாதங்கள், ஏற்கனவே_பிடித்தது)
//
// __Salary is the one section where the deduction is not a percentage of the__
// __payment. The employer estimates the employee's tax for the whole year and__
// __spreads what is left of it over the months remaining, so the rate is__
// __whatever that division produces and changes whenever the estimate does.__
//
// __Which is why a mid-year change — a declared investment, a bonus, a switch of__
// __regime — changes every remaining month rather than being settled in one.__
// __The last month absorbs the rounding, the same way the last instalment of a__
// __loan does; that is the caller's business, and re-running this each month__
// __with the current estimate produces it naturally.__
// சம்பள_பிடித்தம்(ஆண்டு_வரி, மீதி_மாதங்கள், ஏற்கனவே_பிடித்தது) — மீதி மாதங்களுக்குச் சம்பளத்தில் பிடிக்க வேண்டியது
செயல் சம்பள_பிடித்தம்(ஆண்டு_வரி, மீதி_மாதங்கள், ஏற்கனவே_பிடித்தது) {
    (மீதி_மாதங்கள் <= 0) எனில் { திரும்பு 0; }
    மீதி_வரி = ஆண்டு_வரி - ஏற்கனவே_பிடித்தது;
    (மீதி_வரி <= 0) எனில் { திரும்பு 0; }
    திரும்பு வட்டமிடு(மீதி_வரி / மீதி_மாதங்கள், 2);
}

// __வட்டித்_தொகை(அடிப்படை, மாத_வீதம், மாதங்கள்) — simple interest, by the month__
// வட்டித்_தொகை(அடிப்படை, மாத_வீதம், மாதங்கள்) — மாதவாரியான எளிய வட்டி
//
// __Both s.201(1A) interests are this; what differs between them is the rate the__
// __caller passes and the date the months are counted from, which is the__
// __caller's business and not the arithmetic's.__
செயல் வட்டித்_தொகை(அடிப்படை, மாத_வீதம், மாதங்கள்) {
    (அடிப்படை <= 0 அல்லது மாதங்கள் <= 0) எனில் { திரும்பு 0; }
    திரும்பு வட்டமிடு(சதவீதம்(அடிப்படை, மாத_வீதம்) * மாதங்கள், 2);
}

nUlakam/nErativari/muZvari.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/nErativari/muZvari.qmz — முன்வரி, advance tax and the interest for__
// முன்வரியும், குறைபாட்டுக்கான வட்டியும்
// __getting it wrong__
//
// __Tax is due before the year it is charged on has finished. Four instalments,__
// __each a cumulative percentage of the year's liability, estimated in advance —__
// __which means estimated wrongly, because June does not know what March will__
// __bring. The interest sections are the price of that, and they are designed so__
// __that a reasonable estimate revised honestly costs very little and a__
// __deliberate deferral costs a lot.__
//
// __Three sections charge interest and they are constantly confused:__
//
//   __**234A** — the return was filed late. On the tax still unpaid, from the__
//     __due date of filing to the date of filing.__
//   __**234B** — not enough advance tax was paid at all: less than ninety per__
//     __cent of the year's liability. From the 1st of April after the year ends__
//     __to the date of assessment.__
//   __**234C** — enough was paid in total, but not on time. Instalment by__
//     __instalment, three months' interest on each of the first three__
//     __shortfalls and one month on the last.__
//
// __234B and 234C are not alternatives and both can apply to the same year. One__
// __asks whether enough arrived; the other asks whether it arrived when it was__
// __supposed to.__
//
// __Two arithmetic rules apply to all three and both are easy to miss:__
//
//   __Interest runs for a month "or part of a month", so one day into a new__
//     __month is a whole month's interest.__
//   __Rule 119A rounds the amount interest is computed on **down** to the__
//     __nearest hundred rupees. Not to the nearest — down.__

இறக்கு "../atippatY/kaNiqam.qmz";
இறக்கு "../atippatY/poruL.qmz";

// =========================================================================
// __கடமை — who has to pay, and on what__
// =========================================================================
//
// மதிப்பிட்ட_வரி(மொத்த_வரி, மூலப்_பிடித்தம், நிவாரணங்கள்)
//
// __"Assessed tax" — the year's tax less tax already deducted at source and less__
// __any relief. It is the base for every computation in this module, and using__
// __the gross tax instead overstates all of them.__
//
// __Tax deducted at source is credited even if the deductor has not deposited__
// __it. The payee's liability is reduced by what was deducted, and recovering an__
// __undeposited deduction is the department's problem with the deductor, not the__
// __payee's with the department.__
// மதிப்பிட்ட_வரி(மொத்த_வரி, மூலப்_பிடித்தம், நிவாரணங்கள்) — முன்வரிக்கு அடிப்படையான மதிப்பிட்ட வரி
செயல் மதிப்பிட்ட_வரி(மொத்த_வரி, மூலப்_பிடித்தம், நிவாரணங்கள்) {
    விடை = மொத்த_வரி - மூலப்_பிடித்தம் - நிவாரணங்கள்;
    (விடை < 0) எனில் { திரும்பு 0; }
    திரும்பு வட்டமிடு(விடை, 2);
}

// கடமை_உள்ளதா(மதிப்பிட்ட_வரித்_தொகை, குறைந்த_எல்லை)
//
// __Advance tax is payable only where the assessed tax reaches a threshold.__
// __Below it there is no liability and therefore no interest under 234B or 234C__
// __— which makes this the first question to ask, not the last.__
// கடமை_உள்ளதா(மதிப்பிட்ட_வரித்_தொகை, குறைந்த_எல்லை) — முன்வரி செலுத்தும் கடமை உண்டா
செயல் கடமை_உள்ளதா(மதிப்பிட்ட_வரித்_தொகை, குறைந்த_எல்லை) {
    திரும்பு மதிப்பிட்ட_வரித்_தொகை >= குறைந்த_எல்லை;
}

// மூத்தவர்_விலக்கு(வயது, வயது_எல்லை, தொழில்_வருமானம்_உள்ளதா, குடியிருப்பாளரா)
//
// __A resident senior citizen with no business or professional income is not__
// __liable to advance tax at all — section 207(2). Three conditions, and the__
// __middle one is the one that gets dropped: a retired person with consultancy__
// __receipts has business income and the exemption is gone entirely.__
//
// __The exemption is from advance tax, which means from 234B and 234C. It is not__
// __an exemption from the tax itself, and it is not an exemption from 234A.__
// மூத்தவர்_விலக்கு(வயது, வயது_எல்லை, தொழில்_வருமானம்_உள்ளதா, குடியிருப்பாளரா) — மூத்த குடிமகனுக்கு முன்வரி விலக்கு உண்டா
செயல் மூத்தவர்_விலக்கு(வயது, வயது_எல்லை, தொழில்_வருமானம்_உள்ளதா,
                         குடியிருப்பாளரா) {
    (இல்லை குடியிருப்பாளரா) எனில் { திரும்பு பொய்; }
    (தொழில்_வருமானம்_உள்ளதா) எனில் { திரும்பு பொய்; }
    திரும்பு வயது >= வயது_எல்லை;
}

// =========================================================================
// __தவணைகள் — the instalments__
// =========================================================================
//
// __முன்வரித்_தவணைகள்() — the schedule for a non-corporate assessee__
// முன்வரித்_தவணைகள்() — வழக்கமான நான்கு தவணை அட்டவணை
//
// __Each record holds:__
//   __"தவணை_எண்"        which instalment__
//   __"விகிதம்"          the cumulative percentage due by that date__
//   __"நிவாரண_விகிதம்"   the percentage below which 234C bites, where the__
//                       __statute is lenient about the first two dates__
//   __"மாதங்கள்"         months of 234C interest on a shortfall at that date__
//
// __Two things about it are worth stating.__
//
// __The percentages are **cumulative**: fifteen, forty-five, seventy-five, a__
// __hundred. The amount payable on the second date is thirty per cent, and__
// __reading the table as four separate instalments of 15/30/30/25 gets the__
// __payments right and the shortfall computations wrong, because a shortfall is__
// __always measured against the cumulative figure.__
//
// __The **relief band** applies only to the first two dates: pay at least twelve__
// __per cent by the first and thirty-six by the second and no interest is__
// __charged, even though fifteen and forty-five were due. The third and fourth__
// __dates have no such latitude, which is why their relief percentage equals__
// __their required percentage here rather than being absent.__
//
// __This is a default, not a constant. An assessee taxed on presumptive income__
// __pays the whole liability in one instalment on the last date, and the dates__
// __and percentages have been amended before. Every function below takes the__
// __schedule as an argument so another one can be passed.__
// முன்வரித்_தவணைகள்() — முன்கூட்டிய வரியின் தவணை நாட்களும், அவ்வப்போது செலுத்த வேண்டிய விழுக்காடுகளும்
செயல் முன்வரித்_தவணைகள்() {
    திரும்பு [
        {"தவணை_எண்": 1, "விகிதம்": 15,  "நிவாரண_விகிதம்": 12, "மாதங்கள்": 3},
        {"தவணை_எண்": 2, "விகிதம்": 45,  "நிவாரண_விகிதம்": 36, "மாதங்கள்": 3},
        {"தவணை_எண்": 3, "விகிதம்": 75,  "நிவாரண_விகிதம்": 75, "மாதங்கள்": 3},
        {"தவணை_எண்": 4, "விகிதம்": 100, "நிவாரண_விகிதம்": 100, "மாதங்கள்": 1}
    ];
}

// __ஒற்றைத்_தவணை_அட்டவணை() — the presumptive-income schedule__
// ஒற்றைத்_தவணை_அட்டவணை() — கருதுகோள் வருமானத்துக்கான ஒற்றைத் தவணை அட்டவணை
//
// __The whole liability on the last date, and nothing before it. Kept here__
// __because it is the other schedule that actually exists, and because writing__
// __it out makes clear that the instalment machinery is a table and not a__
// __hard-coded four.__
செயல் ஒற்றைத்_தவணை_அட்டவணை() {
    திரும்பு [
        {"தவணை_எண்": 4, "விகிதம்": 100, "நிவாரண_விகிதம்": 100, "மாதங்கள்": 1}
    ];
}

// தவணை_வரை_தேவை(மதிப்பிட்ட_வரித்_தொகை, அட்டவணை, தவணை_எண்)
//
// __The cumulative amount that should have been paid by one instalment date.__
// தவணை_வரை_தேவை(மதிப்பிட்ட_வரித்_தொகை, அட்டவணை, தவணை_எண்) — அத்தவணை வரை செலுத்தியிருக்க வேண்டியது
செயல் தவணை_வரை_தேவை(மதிப்பிட்ட_வரித்_தொகை, அட்டவணை, தவணை_எண்) {
    ஒவ்வொரு ஒரு_தவணை இல் அட்டவணை {
        (ஒரு_தவணை["தவணை_எண்"] == தவணை_எண்) எனில் {
            திரும்பு சரி(வட்டமிடு(சதவீதம்(மதிப்பிட்ட_வரித்_தொகை,
                                             ஒரு_தவணை["விகிதம்"]), 2));
        }
    }
    திரும்பு தவறு("அட்டவணையில் இந்தத் தவணை இல்லை  "
                   & "(no such instalment in the schedule): " & தவணை_எண்);
}

// தவணை_அட்டவணையை_ஆக்கு(மதிப்பிட்ட_வரித்_தொகை, அட்டவணை)
//
// __The full plan: what is cumulatively due by each date, and what that means__
// __paying on the date itself.__
//
// __The two are different numbers and both are wanted. The cumulative figure is__
// __what the interest is measured against; the difference is what leaves the__
// __bank account.__
// தவணை_அட்டவணையை_ஆக்கு(மதிப்பிட்ட_வரித்_தொகை, அட்டவணை) — தவணை வாரியான செலுத்தல் அட்டவணை
செயல் தவணை_அட்டவணையை_ஆக்கு(மதிப்பிட்ட_வரித்_தொகை, அட்டவணை) {
    விடை = [];
    முந்தையது = 0;
    ஒவ்வொரு ஒரு_தவணை இல் அட்டவணை {
        திரட்டியது = வட்டமிடு(சதவீதம்(மதிப்பிட்ட_வரித்_தொகை,
                                        ஒரு_தவணை["விகிதம்"]), 2);
        விடை = இணை(விடை, {"தவணை_எண்": ஒரு_தவணை["தவணை_எண்"],
                            "விகிதம்": ஒரு_தவணை["விகிதம்"],
                            "திரட்டியது": திரட்டியது,
                            "இப்போது_செலுத்த": வட்டமிடு(திரட்டியது - முந்தையது, 2)});
        முந்தையது = திரட்டியது;
    }
    திரும்பு விடை;
}

// =========================================================================
// __வட்டிக்கான அடிப்படை — Rule 119A__
// =========================================================================
//
// வட்டிக்குரிய_அடிப்படை(தொகை_மதிப்பு)
//
// __Rule 119A: the amount interest is computed on is rounded off to a multiple__
// __of one hundred rupees and any fraction of a hundred is **ignored** — so it__
// __rounds down, always, and in the assessee's favour.__
//
// __It is worth at most ninety-nine rupees of base, and it is the difference__
// __between a computation that agrees with the department's and one that does__
// __not. Note that it rounds the *base*, not the interest: the interest itself__
// __is not rounded by this rule.__
// வட்டிக்குரிய_அடிப்படை(தொகை_மதிப்பு) — வட்டி கணக்கிட நூறின் மடங்காக வட்டமிடும்
செயல் வட்டிக்குரிய_அடிப்படை(தொகை_மதிப்பு) {
    (தொகை_மதிப்பு <= 0) எனில் { திரும்பு 0; }
    திரும்பு தரை(தொகை_மதிப்பு / 100) * 100;
}

// மாதங்களாக(நாட்களின்_எண்ணிக்கை)
//
// __Part of a month is a whole month. Same rule as in mUlavari.qmz, and the same__
// __caveat: a caller with real dates should count calendar months itself.__
// மாதங்களாக(நாட்களின்_எண்ணிக்கை) — நாட்களை மாதங்களாக்கும்
செயல் மாதங்களாக(நாட்களின்_எண்ணிக்கை) {
    திரும்பு வட்ட_மாதங்கள்(நாட்களின்_எண்ணிக்கை);
}

// =========================================================================
// __234C — paid late__
// =========================================================================
//
// தவணை_வட்டி(மதிப்பிட்ட_வரித்_தொகை, செலுத்தியவை, அட்டவணை, மாத_வீதம்)
//
// __செலுத்தியவை is the **cumulative** advance tax paid by each instalment date,__
// __in the schedule's order. Interest is charged instalment by instalment, on__
// __the shortfall against the cumulative requirement, for the months that__
// __instalment attracts.__
//
// __The relief band is what makes this bearable. Pay at least the relief__
// __percentage by the first two dates and nothing is charged, even though the__
// __required percentage was higher — the statute's acknowledgement that an__
// __estimate made in June is an estimate. Miss it by a rupee and the interest is__
// __on the whole shortfall against the *required* percentage, not against the__
// __relief band. The band decides whether interest applies; it never reduces it.__
//
// __Answers each instalment's working and the total, because 234C is the__
// __computation most often disputed and a bare total cannot be argued with.__
// தவணை_வட்டி(தேவை, செலுத்தியது, மாத_வீதம், மாதங்கள்) — ஒரு தவணை குறைந்ததற்கான வட்டி
செயல் தவணை_வட்டி(மதிப்பிட்ட_வரித்_தொகை, செலுத்தியவை, அட்டவணை, மாத_வீதம்) {
    வரிசைகள் = [];
    மொத்த_வட்டி = 0;
    இட_எண் = 0;

    ஒவ்வொரு ஒரு_தவணை இல் அட்டவணை {
        செலுத்தியது = 0;
        (இட_எண் < நீளம்(செலுத்தியவை)) எனில் {
            செலுத்தியது = செலுத்தியவை[இட_எண்];
        }

        தேவை = வட்டமிடு(சதவீதம்(மதிப்பிட்ட_வரித்_தொகை,
                                  ஒரு_தவணை["விகிதம்"]), 2);
        நிவாரண_எல்லை = வட்டமிடு(சதவீதம்(மதிப்பிட்ட_வரித்_தொகை,
                                           ஒரு_தவணை["நிவாரண_விகிதம்"]), 2);

        இந்த_வட்டி = 0;
        குறை = 0;
        // __The band is a gate, not a reduction: below it, the shortfall is__
        // __measured against the full requirement.__
        (செலுத்தியது < நிவாரண_எல்லை) எனில் {
            குறை = வட்டமிடு(தேவை - செலுத்தியது, 2);
            (குறை > 0) எனில் {
                அடிப்படை_மதிப்பு = வட்டிக்குரிய_அடிப்படை(குறை);
                இந்த_வட்டி = வட்டமிடு(சதவீதம்(அடிப்படை_மதிப்பு, மாத_வீதம்)
                                        * ஒரு_தவணை["மாதங்கள்"], 2);
            }
        }

        வரிசைகள் = இணை(வரிசைகள், {"தவணை_எண்": ஒரு_தவணை["தவணை_எண்"],
                                    "தேவை": தேவை,
                                    "செலுத்தியது": செலுத்தியது,
                                    "நிவாரண_எல்லை": நிவாரண_எல்லை,
                                    "குறை": குறை,
                                    "மாதங்கள்": ஒரு_தவணை["மாதங்கள்"],
                                    "வட்டி": இந்த_வட்டி});
        மொத்த_வட்டி = வட்டமிடு(மொத்த_வட்டி + இந்த_வட்டி, 2);
        இட_எண் = இட_எண் + 1;
    }

    திரும்பு {"வரிசைகள்": வரிசைகள், "மொத்த_வட்டி": மொத்த_வட்டி};
}

// =========================================================================
// __234B — not enough paid__
// =========================================================================
//
// குறைபாட்டு_வட்டி(மதிப்பிட்ட_வரித்_தொகை, செலுத்திய_முன்வரி,
//                    குறைந்த_விகிதம், மாத_வீதம், மாதங்கள்)
//
// __Where the advance tax paid is less than a stated percentage of the assessed__
// __tax, interest runs on the **whole** shortfall from the 1st of April__
// __following the year to the date of assessment.__
//
// __The percentage is a gate exactly like 234C's relief band, and it works the__
// __same counter-intuitive way: pay eighty-nine per cent and interest is charged__
// __on the full eleven per cent shortfall, not on the one per cent by which the__
// __gate was missed. Pay ninety and it is nothing. There is no proportioning__
// __anywhere in this section.__
// குறைபாட்டு_வட்டி(மதிப்பிட்ட_வரித்_தொகை, செலுத்திய_முன்வரி, மாத_வீதம், மாதங்கள்) — முன்வரிக் குறைபாட்டுக்கான வட்டி
செயல் குறைபாட்டு_வட்டி(மதிப்பிட்ட_வரித்_தொகை, செலுத்திய_முன்வரி,
                          குறைந்த_விகிதம், மாத_வீதம், மாதங்கள்) {
    எல்லை = சதவீதம்(மதிப்பிட்ட_வரித்_தொகை, குறைந்த_விகிதம்);
    (செலுத்திய_முன்வரி >= எல்லை) எனில் {
        திரும்பு {"பொருந்துமா": பொய், "குறை": 0, "அடிப்படை": 0, "வட்டி": 0};
    }

    குறை = வட்டமிடு(மதிப்பிட்ட_வரித்_தொகை - செலுத்திய_முன்வரி, 2);
    (குறை <= 0) எனில் {
        திரும்பு {"பொருந்துமா": பொய், "குறை": 0, "அடிப்படை": 0, "வட்டி": 0};
    }

    அடிப்படை_மதிப்பு = வட்டிக்குரிய_அடிப்படை(குறை);
    திரும்பு {"பொருந்துமா": மெய்,
              "குறை": குறை,
              "அடிப்படை": அடிப்படை_மதிப்பு,
              "வட்டி": வட்டமிடு(சதவீதம்(அடிப்படை_மதிப்பு, மாத_வீதம்)
                                  * மாதங்கள், 2)};
}

// =========================================================================
// __234A — filed late__
// =========================================================================
//
// தாமதத்_தாக்கல்_வட்டி(மொத்த_வரி, செலுத்தியவை, மாத_வீதம், மாதங்கள்)
//
// __Interest for filing the return after its due date, on the tax unpaid at that__
// __point. செலுத்தியவை is everything already credited — advance tax, tax__
// __deducted at source, self-assessment tax paid before filing.__
//
// __This is the one that surprises people who file late with nothing to pay: if__
// __the tax was already settled there is no interest here at all, because the__
// __section charges interest on an amount and not a penalty for a date. A late__
// __return with tax outstanding is expensive; a late return with tax paid costs__
// __nothing under this section.__
// தாமதத்_தாக்கல்_வட்டி(மொத்த_வரி, செலுத்தியவை, மாத_வீதம், மாதங்கள்) — தாமதமாகத் தாக்கல் செய்ததற்கான வட்டி
செயல் தாமதத்_தாக்கல்_வட்டி(மொத்த_வரி, செலுத்தியவை, மாத_வீதம், மாதங்கள்) {
    நிலுவைத்_தொகை = மொத்த_வரி - செலுத்தியவை;
    (நிலுவைத்_தொகை <= 0 அல்லது மாதங்கள் <= 0) எனில் {
        திரும்பு {"நிலுவை": 0, "அடிப்படை": 0, "வட்டி": 0};
    }
    அடிப்படை_மதிப்பு = வட்டிக்குரிய_அடிப்படை(நிலுவைத்_தொகை);
    திரும்பு {"நிலுவை": வட்டமிடு(நிலுவைத்_தொகை, 2),
              "அடிப்படை": அடிப்படை_மதிப்பு,
              "வட்டி": வட்டமிடு(சதவீதம்(அடிப்படை_மதிப்பு, மாத_வீதம்)
                                  * மாதங்கள், 2)};
}

// =========================================================================
// __இறுதிக் கணக்கு — what is actually owed__
// =========================================================================
//
// செலுத்த_வேண்டியது(மொத்த_வரி, மூலப்_பிடித்தம், செலுத்திய_முன்வரி,
//                     சுய_மதிப்பீட்டு_வரி, வட்டிகள்)
//
// __The bottom line of a return: tax, plus every interest charge, less__
// __everything already paid. A negative answer is a refund and is returned__
// __signed rather than as a separate field, because a computation that reports__
// __"amount payable: 0" for a refund of forty thousand rupees is worse than__
// __useless.__
// செலுத்த_வேண்டியது(மொத்த_வரி, மூலப்_பிடித்தம், செலுத்திய_முன்வரி, வட்டிகள்) — இறுதியில் செலுத்த வேண்டிய தொகை
செயல் செலுத்த_வேண்டியது(மொத்த_வரி, மூலப்_பிடித்தம், செலுத்திய_முன்வரி,
                           சுய_மதிப்பீட்டு_வரி, வட்டிகள்) {
    செலுத்தியவை = மூலப்_பிடித்தம் + செலுத்திய_முன்வரி + சுய_மதிப்பீட்டு_வரி;
    நிகரம் = வட்டமிடு(மொத்த_வரி + வட்டிகள் - செலுத்தியவை, 2);
    திரும்பு {"மொத்த_வரி": வட்டமிடு(மொத்த_வரி, 2),
              "வட்டிகள்": வட்டமிடு(வட்டிகள், 2),
              "செலுத்தியவை": வட்டமிடு(செலுத்தியவை, 2),
              "நிகரம்": நிகரம்,
              "திரும்பப்_பெறுவதா": நிகரம் < 0};
}

