// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/paNam/paNam.qmz — பணம் (money) formatting__
// பணத்தை வடிவமைத்துக் காட்டும் செயல்கள்
//
// __Indian digit grouping: the last three digits, then groups of two, so__
// __12345678.5 reads as 1,23,45,678.50 — not the 12,345,678.50 that a__
// __western formatter would give you.__

இறக்கு "../atippatY/col.qmz";
இறக்கு "../atippatY/kaNiqam.qmz";

// __குழுக்கள்(இலக்கங்கள்) — apply the 3-then-2s grouping to a digit string__
// குழுக்கள்(இலக்கங்கள்) — இலக்கங்களை மூன்று பின் இரண்டிரண்டாகப் பிரிக்கும் இந்திய முறை
செயல் குழுக்கள்(இலக்கங்கள்) {
    மொத்தம் = நீளம்(இலக்கங்கள்);
    (மொத்தம் <= 3) எனில் { திரும்பு இலக்கங்கள்; }

    விடை = துண்டு(இலக்கங்கள், மொத்தம் - 3, 3);
    மீதம் = துண்டு(இலக்கங்கள், 0, மொத்தம் - 3);

    (நீளம்(மீதம்) > 0) சுற்று {
        எஞ்சியது = நீளம்(மீதம்);
        (எஞ்சியது <= 2) எனில் {
            விடை = மீதம் & "," & விடை;
            மீதம் = "";
        }
        இன்றேல் {
            விடை = துண்டு(மீதம், எஞ்சியது - 2, 2) & "," & விடை;
            மீதம் = துண்டு(மீதம், 0, எஞ்சியது - 2);
        }
    }
    திரும்பு விடை;
}

// __காசு_வடிவம்(தொகை) — group and show exactly two decimal places__
// காசு_வடிவம்(தொகை) — குழுவாக்கி, சரியாக இரண்டு தசம இடங்களுடன் காட்டும்
செயல் காசு_வடிவம்(தொகை) {
    வட்டம் = வட்டமிடு(தொகை, 2);

    எதிர்மறை = பொய்;
    (வட்டம் < 0) எனில் {
        எதிர்மறை = மெய்;
        வட்டம் = 0 - வட்டம்;
    }

    முழு = தரை(வட்டம்);
    காசு = வட்டமிடு((வட்டம் - முழு) * 100, 0);

    விடை = குழுக்கள்(சொல்லாக்கு(முழு)) & "." & இடமிருந்து_நிரப்பு(சொல்லாக்கு(காசு), 2, "0");

    (எதிர்மறை) எனில் { திரும்பு "-" & விடை; }
    திரும்பு விடை;
}

// __ரூபாய்(தொகை) — format an amount as rupees, with the sign and Indian digit grouping__
// ரூபாய்(தொகை) — தொகையை ரூபாயாக, குறியுடனும் இந்திய இலக்கக் குழுவுடனும் காட்டும்
செயல் ரூபாய்(தொகை) {
    திரும்பு "₹" & காசு_வடிவம்(தொகை);
}

// __காசாக(தொகை) — round to the paisa, which is what a ledger stores__
// காசாக(தொகை) — பைசா வரை வட்டமிடும்; பேரேடு சேமிப்பது இதுவே
செயல் காசாக(தொகை) {
    திரும்பு வட்டமிடு(தொகை, 2);
}

// __லட்சம்(தொகை) / கோடி(தொகை) — express in lakhs or crores__
// லட்சம்(தொகை) — தொகையை லட்சத்தில் சொல்லும்
செயல் லட்சம்(தொகை) {
    திரும்பு வட்டமிடு(தொகை / 100000, 2);
}

// __கோடி(தொகை) — an amount expressed in crore__
// கோடி(தொகை) — தொகையைக் கோடியில் சொல்லும்
//
// __Ten million to the crore, rounded to two places. The unit Indian financial reporting actually uses: a balance sheet in crore is read at a glance and the same figure in millions is converted in the reader's head, badly.__
செயல் கோடி(தொகை) {
    திரும்பு வட்டமிடு(தொகை / 10000000, 2);
}

nUlakam/paNam/uqavi/camamAkap_piri.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __சமமாகப்_பிரி(மொத்த_பைசா, எத்தனை) — split an amount evenly, giving the odd paise to the first shares__
// தொகையைச் சமமாகப் பிரிக்கும்; மீதிப் பைசாக்கள் முதல் பங்குகளுக்கு

இறக்கு "../kAcu.qmz";
இறக்கு "../paNam.qmz";

// __A hundred rupees between three. The parts add back to exactly a hundred,__
// __which 33.33 three times over does not.__
// நூறு ரூபாய் மூவருக்கு; பங்குகள் கூடினால் சரியாக நூறே
பங்குகள் = சமமாகப்_பிரி(ரூபாயாக(100), 3);
ஒவ்வொரு ஒரு_பங்கு இல் பங்குகள் { அச்சு காசு_உரை(ஒரு_பங்கு); }
அச்சு காசு_உரை(காசு_கூட்டல்(பங்குகள்));

// __The odd paise go to the earliest shares rather than being dropped. Someone__
// __has to get the extra paisa, and it has to be decided rather than lost.__
// மீதிப் பைசா முதல் பங்குகளுக்கே; தொலைந்து போவதில்லை
அச்சு நீளம்(சமமாகப்_பிரி(ரூபாயாக(100), 3));

// __Splitting between nobody gives nothing rather than dividing by zero.__
// யாருக்கும் இல்லாமல் பிரித்தால் ஒன்றுமில்லை
அச்சு நீளம்(சமமாகப்_பிரி(ரூபாயாக(100), 0));

