// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __காசு_கழி(அ, ஆ) — subtract one amount from another__
// ஒரு தொகையிலிருந்து மற்றொன்றைக் கழிக்கும்

இறக்கு "../kAcu.qmz";
இறக்கு "../paNam.qmz";

அச்சு காசு_உரை(காசு_கழி(ரூபாயாக(1000), ரூபாயும்_பைசாவும்(249, 50)));

// __It goes below zero rather than stopping there. A balance that cannot be__
// __negative is a business rule for the caller to apply; a subtraction that__
// __silently floors at zero hides an overdraft.__
// பூஜ்ஜியத்திற்குக் கீழும் செல்லும்; அங்கே நிற்பது கணக்கியல் விதி, கழித்தலின் வேலை அல்ல
அச்சு காசு_உரை(காசு_கழி(ரூபாயாக(100), ரூபாயாக(250)));

nUlakam/paNam/uqavi/kAcu_matawku.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __காசு_மடங்கு(மொத்த_பைசா, எண்ணிக்கை) — an amount, so many times over__
// ஒரு தொகை, இத்தனை மடங்கு

இறக்கு "../kAcu.qmz";
இறக்கு "../paNam.qmz";

// __A unit price and a quantity. Whole paise times a whole count stays whole,__
// __so nothing needs rounding here and nothing is lost.__
// அலகு விலையும் எண்ணிக்கையும்; வட்டமிடல் தேவையில்லை
அச்சு காசு_உரை(காசு_மடங்கு(ரூபாயும்_பைசாவும்(12, 50), 8));

// __A count of nothing is nothing, not an error: an order line with no items__
// __is a line worth nothing.__
// எண்ணிக்கை பூஜ்ஜியம் என்றால் தொகையும் பூஜ்ஜியமே
அச்சு காசு_உரை(காசு_மடங்கு(ரூபாயாக(99), 0));

nUlakam/paNam/uqavi/kAcu_urY.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __காசு_உரை(மொத்த_பைசா) — paise written out as rupees and paise__
// பைசாவை ரூபாய்-பைசாவாக எழுதும்

இறக்கு "../kAcu.qmz";
இறக்கு "../paNam.qmz";

// __The only place paise turn back into a decimal point, and it is for reading,__
// __not for arithmetic.__
// பைசா தசமப் புள்ளியாக மாறும் ஒரே இடம் இதுவே; அதுவும் படிப்பதற்கே
அச்சு காசு_உரை(24950);
அச்சு காசு_உரை(100);

// __A single paisa keeps its leading zero, so 5 paise is 0.05 and not 0.5.__
// ஒரு பைசாவும் தன் முன் பூஜ்ஜியத்தைத் தக்கவைக்கும்
அச்சு காசு_உரை(5);

// __And a negative is written with the sign in front of the whole figure.__
// எதிர்மறைக் குறி முழுத் தொகைக்கும் முன்னே
அச்சு காசு_உரை(0 - 24950);

nUlakam/paNam/uqavi/kAcu_vativam.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __காசு_வடிவம்(தொகை) — a rupee figure grouped and given two decimals__
// குழுக்களுடனும் இரு தசம இடங்களுடனும் ரூபாய்த் தொகை

இறக்கு "../kAcu.qmz";
இறக்கு "../paNam.qmz";

// __This one takes rupees, not paise — it is the printing end of the module,__
// __where an amount has already been turned back into rupees for a reader.__
// இது ரூபாயையே ஏற்கிறது, பைசாவை அல்ல; இது படிப்பதற்கான முனை
அச்சு காசு_வடிவம்(1234567.5);
அச்சு காசு_வடிவம்(1000);

// __The paise are padded, so a column of figures lines up at the point.__
