// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __எடு(சாவி) — read a key; a missing key is absence, not failure__
// சாவியின் மதிப்பை எடுக்கும்; சாவி இல்லாதது தவறு அல்ல, இன்மை

இறக்கு "../retis.qmz";

முகவரி = சூழல்("ETAMIL_REDIS", "");
(முகவரி != "") எனில் { ரெடிஸ்_இணை(முகவரி); }

சேமி("மாதிரி:வாடிக்கையாளர்:1", "குமார்");
விளைவு = எடு("மாதிரி:வாடிக்கையாளர்:1");

// __A key that was never written comes back as nil inside a சரி, not as a__
// __தவறு. The distinction matters: a cache miss is the ordinary case and a__
// __broken connection is not, and code that treats them alike either retries__
// __every miss or ignores every outage.__
// எழுதப்படாத சாவி, இன்மையைச் சுமந்த சரி ஆகவே திரும்பும்; தவறாக அல்ல
இல்லாதது = எடு("மாதிரி:இல்லாத_சாவி");

(சரியா(விளைவு)) எனில் {
    அச்சு சொல்லாக்கு(மதிப்பு(விளைவு));
    அச்சு வகை(மதிப்பு(இல்லாதது));
}
இன்றேல் { அச்சு "இணைப்பு இல்லை — தவறாகத் திரும்பியது"; }

nUlakam/qaLam/uqavi/illYyeZil_iyalpu.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __இல்லையெனில்_இயல்பு(சாவி, மாற்று_மதிப்பு) — the key's value, or this instead__
// சாவி இல்லையெனில் மாற்று மதிப்பைத் தரும்

இறக்கு "../retis.qmz";

முகவரி = சூழல்("ETAMIL_REDIS", "");
(முகவரி != "") எனில் { ரெடிஸ்_இணை(முகவரி); }

சேமி("மாதிரி:மொழி", "தமிழ்");

// __This is the one function here that answers a plain value rather than a__
// __result, and it is deliberate: a cache miss, a missing key and an unreachable__
// __server all give the fallback. A cache that is down should slow a program,__
// __not stop it.__
// இது முடிவு அல்ல, நேரடி மதிப்பையே தரும்; இணைப்பு இல்லாவிட்டாலும் மாற்று மதிப்பே
அச்சு இல்லையெனில்_இயல்பு("மாதிரி:மொழி", "ஆங்கிலம்");
அச்சு இல்லையெனில்_இயல்பு("மாதிரி:இல்லாத_சாவி", "ஆங்கிலம்");

// __Which also means a wrong answer is indistinguishable from a default. Use__
// __எடு where the difference between "not cached" and "cache is down" matters.__
// எனவே தவறான விடைக்கும் இயல்பு மதிப்புக்கும் வேறுபாடு தெரியாது; தேவையெனில் எடு-வைப் பயன்படுத்துக

nUlakam/qaLam/uqavi/irukkiRaqA.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __இருக்கிறதா(சாவி) — is this key there?__
// இந்தச் சாவி இருக்கிறதா என்று பார்க்கும்

இறக்கு "../retis.qmz";

முகவரி = சூழல்("ETAMIL_REDIS", "");
(முகவரி != "") எனில் { ரெடிஸ்_இணை(முகவரி); }

சேமி("மாதிரி:உள்ளது", 1);

// __Redis answers EXISTS with a count; this turns it into மெய் or பொய், so a__
// __caller does not have to know that 0 and 1 were the real reply.__
// ரெடிஸ் எண்ணிக்கையைத் தரும்; இது மெய்/பொய் ஆக மாற்றுகிறது
உள்ளது = இருக்கிறதா("மாதிரி:உள்ளது");
இல்லாதது = இருக்கிறதா("மாதிரி:இல்லாத_சாவி");

(சரியா(உள்ளது)) எனில் {
    அச்சு மதிப்பு(உள்ளது);
    அச்சு மதிப்பு(இல்லாதது);
}
இன்றேல் { அச்சு "இணைப்பு இல்லை — தவறாகத் திரும்பியது"; }

nUlakam/qaLam/uqavi/kAlaqqutaZ_cEmi.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __காலத்துடன்_சேமி(சாவி, மதிப்புரு, வினாடிகள்) — store a value that expires by itself__
// சொன்ன வினாடிகளில் காலாவதியாகும்படிச் சேமிக்கும்

இறக்கு "../retis.qmz";

முகவரி = சூழல்("ETAMIL_REDIS", "");
(முகவரி != "") எனில் { ரெடிஸ்_இணை(முகவரி); }

// __The expiry is set in the same command as the write rather than in a second__
// __one. A key written now and given its expiry a moment later is a key that__
// __lives for ever if anything goes wrong in between.__
