// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>

இறக்கு "../atippatY/aNi.qmz";
// __nUlakam/qittam/curukkal.qmz — சுருக்கல் (crashing, the time-cost trade-off)__
// சுருக்கல்: காலத்தைப் பணத்தால் குறைத்தல்
//
// __Shortening a project costs money, and the question is which activity to buy__
// __time from. Two facts decide it.__
//
// __Only a **critical** activity is worth crashing. Shortening anything with__
// __float buys nothing at all, and it is the most expensive mistake available__
// __because it looks like progress.__
//
// __Among critical activities, buy from the **cheapest slope**: the cost of one__
// __unit of time. Crashing changes the critical path, so the choice has to be__
// __remade after every step — which is why this module gives the pieces and the__
// __caller loops, rather than pretending one call can do it.__
//
// __Where several paths are critical at once, one activity per path must be__
// __crashed, or the paths that were not touched hold the duration exactly where__
// __it was. An activity common to several paths is often cheaper than one on__
// __each, and கூட்டுச்_சரிவு exists to price that comparison.__
//
// __The optimum is the minimum of **total** cost, direct plus indirect, not of__
// __either alone: direct cost rises as the schedule shortens and indirect falls__
// __with it. Always compute one step past the apparent minimum, because a__
// __minimum you have not stepped over is only the last point you calculated.__

// செயல்_நேர_செலவு(செயல்_குறி, இயல்பு_காலம், இயல்பு_செலவு, சுருக்க_காலம்,
//                  சுருக்கச்_செலவு)
//
// __Normal time is the low-cost, efficient way of doing the work; crash time is__
// __a **threshold**, the shortest the activity can go however much is spent.__
// செயல்_நேர_செலவு(செயல்_குறி, இயல்பு_காலம், இயல்பு_செலவு, சுருக்க_காலம், சுருக்கச்_செலவு) — ஒரு செயலின் நேரமும் செலவும்
செயல் செயல்_நேர_செலவு(செயல்_குறி, இயல்பு_காலம், இயல்பு_செலவு,
                        சுருக்க_காலம், சுருக்கச்_செலவு) {
    திரும்பு {
        செயல்_குறி: செயல்_குறி,
        இயல்பு_காலம்: இயல்பு_காலம்,
        இயல்பு_செலவு: இயல்பு_செலவு,
        சுருக்க_காலம்: சுருக்க_காலம்,
        சுருக்கச்_செலவு: சுருக்கச்_செலவு
    };
}

// __அதிகபட்ச_சுருக்கம்(நேரத்_தரவு) — how many units of time are for sale__
// அதிகபட்ச_சுருக்கம்(நேரத்_தரவு) — விலைக்கு வாங்கக்கூடிய கால அலகுகள் எத்தனை
//
// __The parameter is compound because தரவு on its own is a keyword in this__
// __language; see celavu/README.md.__
செயல் அதிகபட்ச_சுருக்கம்(நேரத்_தரவு) {
    திரும்பு நேரத்_தரவு.இயல்பு_காலம் - நேரத்_தரவு.சுருக்க_காலம்;
}

// __செலவுச்_சரிவு(தரவு) — the cost of buying one unit of time__
// செலவுச்_சரிவு(தரவு) — ஒரு கால அலகை வாங்கும் செலவு
//
//     __(crash cost − normal cost) / (normal time − crash time)__
//
// __An activity that cannot be shortened has no slope rather than an infinite__
// __one, so it is a தவறு and can never be selected as cheapest by accident.__
செயல் செலவுச்_சரிவு(நேரத்_தரவு) {
    சுருக்கம் = அதிகபட்ச_சுருக்கம்(நேரத்_தரவு);
    (சுருக்கம் <= 0) எனில் {
        திரும்பு தவறு(நேரத்_தரவு.செயல்_குறி
                      & ": சுருக்க முடியாது, சரிவு இல்லை");
    }
    திரும்பு சரி((நேரத்_தரவு.சுருக்கச்_செலவு - நேரத்_தரவு.இயல்பு_செலவு)
                 / சுருக்கம்);
}

// மலிவான_வேட்பாளர்(தரவுகள், கடுமையான_குறிகள்)
//
// __The cheapest crashable activity that is also critical. Both conditions__
// __matter and the second is the one that gets forgotten.__
// மலிவான_வேட்பாளர்(தரவுகள், கடுமையான_குறிகள்) — சுருக்க மலிவான செயல்
செயல் மலிவான_வேட்பாளர்(தரவுகள், கடுமையான_குறிகள்) {
    சிறந்த_குறி = "";
    சிறந்த_சரிவு = 0;
    ஒவ்வொரு ஒரு_தரவு இல் தரவுகள் {
        (கடுமையானதா(கடுமையான_குறிகள், ஒரு_தரவு.செயல்_குறி)) எனில் {
            சரிவு = செலவுச்_சரிவு(ஒரு_தரவு);
            (சரியா(சரிவு)) எனில் {
                (சிறந்த_குறி == "") எனில் {
                    சிறந்த_குறி = ஒரு_தரவு.செயல்_குறி;
                    சிறந்த_சரிவு = மதிப்பு(சரிவு);
                } இன்றேல் {
                    (மதிப்பு(சரிவு) < சிறந்த_சரிவு) எனில் {
                        சிறந்த_குறி = ஒரு_தரவு.செயல்_குறி;
                        சிறந்த_சரிவு = மதிப்பு(சரிவு);
                    }
                }
            }
        }
    }
    (சிறந்த_குறி == "") எனில் {
        திரும்பு தவறு("சுருக்கக்கூடிய கடுமையான செயல் இல்லை");
    }
    திரும்பு சரி({ செயல்_குறி: சிறந்த_குறி, சரிவு: சிறந்த_சரிவு });
}

// __கடுமையானதா(கடுமையான_குறிகள், செயல்_குறி) — is this activity on the critical path?__
// கடுமையானதா(கடுமையான_குறிகள், செயல்_குறி) — இச்செயல் கடுமையான பாதையில் உள்ளதா
//
// __Only critical activities are worth crashing: spending money to shorten an activity with float buys nothing, because the project still finishes when the critical path does. This is the test that stops that money being spent.__
செயல் கடுமையானதா(கடுமையான_குறிகள், செயல்_குறி) {
    திரும்பு உள்ளதா(கடுமையான_குறிகள், செயல்_குறி);
}

// __கூட்டுச்_சரிவு(தரவுகள், குறிகள்) — the cost of crashing a whole set together__
// கூட்டுச்_சரிவு(தரவுகள், குறிகள்) — பல செயல்களை ஒன்றாகச் சுருக்கும் செலவு
//
// __When several paths are critical, compare the sum of one activity per path__
// __against a single shared activity that shortens all of them. The shared one__
// __frequently wins, and only this comparison shows it.__
செயல் கூட்டுச்_சரிவு(தரவுகள், குறிகள்) {
    ஓடும்_கூட்டல் = 0;
    ஒவ்வொரு ஒரு_குறி இல் குறிகள் {
        ஒவ்வொரு ஒரு_தரவு இல் தரவுகள் {
            (ஒரு_தரவு.செயல்_குறி == ஒரு_குறி) எனில் {
                சரிவு = செலவுச்_சரிவு(ஒரு_தரவு);
                (தவறா(சரிவு)) எனில் { திரும்பு சரிவு; }
                ஓடும்_கூட்டல் = ஓடும்_கூட்டல் + மதிப்பு(சரிவு);
            }
        }
    }
    திரும்பு சரி(ஓடும்_கூட்டல்);
}

// __--- Totals --------------------------------------------------------------__

// __இயல்பு_நேரடிச்_செலவு(தரவுகள்) — the project's direct cost with nothing crashed__
// இயல்பு_நேரடிச்_செலவு(தரவுகள்) — ஒன்றும் சுருக்காத நிலையில் திட்டத்தின் நேரடிச் செலவு
//
// __The baseline every crashing decision is measured against. Crashing raises direct cost and lowers indirect cost, and the optimum is where the two curves cross — which cannot be found without knowing where they started.__
செயல் இயல்பு_நேரடிச்_செலவு(தரவுகள்) {
    ஓடும்_கூட்டல் = 0;
    ஒவ்வொரு ஒரு_தரவு இல் தரவுகள் {
        ஓடும்_கூட்டல் = ஓடும்_கூட்டல் + ஒரு_தரவு.இயல்பு_செலவு;
    }
    திரும்பு ஓடும்_கூட்டல்;
}

// மொத்தச்_செலவு(நேரடிச்_செலவு, நாள்_மறைமுகச்_செலவு, காலம்)
//
// __Direct plus indirect. Indirect runs with the calendar, so shortening the__
// __project reduces it — which is why the optimum is not simply the cheapest__
// __direct cost.__
// மொத்தச்_செலவு(நேரடிச்_செலவு, நாள்_மறைமுகச்_செலவு, காலம்) — நேரடியும் மறைமுகமும் சேர்த்த செலவு
செயல் மொத்தச்_செலவு(நேரடிச்_செலவு, நாள்_மறைமுகச்_செலவு, காலம்) {
    திரும்பு நேரடிச்_செலவு + நாள்_மறைமுகச்_செலவு * காலம்;
}

// தாமதச்_செலவுடன்(நேரடிச்_செலவு, நாள்_மறைமுகச்_செலவு, நாள்_தாமதச்_செலவு, காலம்)
//
// __The honest total. Project overhead is rarely the real cost of a day: a__
// __delayed benefit, a penalty clause or a lost season usually dwarfs it, and__
// __including it moves the optimum substantially earlier. Whose money is being__
// __optimised is a decision to take consciously rather than by omission.__
// தாமதச்_செலவுடன்(நேரடிச்_செலவு, நாள்_மறைமுகச்_செலவு, நாள்_தாமதச்_செலவு, காலம்) — தாமத அபராதமும் சேர்த்த மொத்தச் செலவு
செயல் தாமதச்_செலவுடன்(நேரடிச்_செலவு, நாள்_மறைமுகச்_செலவு,
                        நாள்_தாமதச்_செலவு, காலம்) {
    திரும்பு நேரடிச்_செலவு
             + (நாள்_மறைமுகச்_செலவு + நாள்_தாமதச்_செலவு) * காலம்;
}

nUlakam/qittam/kattam.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/kattam.qmz — கட்டம் (lifecycle phases, and whether a document can be written yet)__
// வாழ்க்கைக் கட்டங்களும் ஆவணத் தயார்நிலையும்
//
// __A project moves through five phases — initiation, planning, execution,__
// __control, closure — and each phase has its documents: a charter to start, a__
// __schedule baseline to plan, status reports to execute. Whether a document can__
// __be generated is a question about data, not about the template: a charter__
// __with no sponsor is not ready, however good the template is.__
//
// __So a template declares its bindings — the paths into the project's data it__
// __reads, and which of them it cannot do without — and readiness is the share of__
// __required bindings that are satisfied. The missing ones come back by name,__
// __which is the to-do list for whoever wants the document.__
//
// __A path is dotted, "திட்டம்.அனுசரணையாளர்", and walks records. A value binding__
// __is satisfied by anything but "", இன்மை, or an empty list or record; a list__
// __binding only by a non-empty list. An empty collection is never ready: a__
// __charter that promises milestones and has none is not ready, whichever kind__
// __the binding was declared as.__

இறக்கு "../atippatY/aNi.qmz";

// __வாழ்க்கைக்_கட்டங்கள்() — the five phases, in order__
// வாழ்க்கைக்_கட்டங்கள்() — ஐந்து வாழ்க்கைக் கட்டங்கள்
செயல் வாழ்க்கைக்_கட்டங்கள்() {
    திரும்பு ["தொடக்கம்", "திட்டமிடல்", "செயலாக்கம்", "கட்டுப்பாடு", "நிறைவுறுத்தல்"];
}

// __அடுத்த_கட்டம்(ஒரு_கட்டம்) — the phase after this one__
// அடுத்த_கட்டம்(ஒரு_கட்டம்) — இதற்கு அடுத்த கட்டம்
//
// __"" after the last phase and for a name that is not a phase: there is nowhere__
// __to go, and a guess would move a project into a phase it never entered.__
செயல் அடுத்த_கட்டம்(ஒரு_கட்டம்) {
    கட்டங்கள் = வாழ்க்கைக்_கட்டங்கள்();
    இடம்_எண் = இடம்_காண்(கட்டங்கள், ஒரு_கட்டம்);
    (இடம்_எண் < 0 அல்லது இடம்_எண் >= நீளம்(கட்டங்கள்) - 1) எனில் { திரும்பு ""; }
    திரும்பு கட்டங்கள்[இடம்_எண் + 1];
}

// __பிணைப்பு_ஆக்கு(பிணைப்புப்_பாதை, கட்டாயமா, பிணைப்பு_வகை) — one field a template reads__
// பிணைப்பு_ஆக்கு(பிணைப்புப்_பாதை, கட்டாயமா, பிணைப்பு_வகை) — வார்ப்புரு படிக்கும் ஒரு புலம்
//
// __பிணைப்பு_வகை is "மதிப்பு" for a single value or "பட்டியல்" for a repeating__
// __block. An optional binding counts for nothing either way.__
செயல் பிணைப்பு_ஆக்கு(பிணைப்புப்_பாதை, கட்டாயமா, பிணைப்பு_வகை) {
    திரும்பு { பிணைப்புப்_பாதை: பிணைப்புப்_பாதை, கட்டாயமா: கட்டாயமா, பிணைப்பு_வகை: பிணைப்பு_வகை };
}

// __பாதையில்_மதிப்பு(சூழல், புள்ளிப்_பாதை) — the value at a dotted path__
// பாதையில்_மதிப்பு(சூழல், புள்ளிப்_பாதை) — புள்ளிப் பாதையிலுள்ள மதிப்பு
//
// __சரி with the value, or தவறு naming the first part of the path that is not__
// __there — "திட்டம்.அனுசரணையாளர்" on a project with no sponsor names__
// __அனுசரணையாளர், not the whole path, so the gap is obvious.__
செயல் பாதையில்_மதிப்பு(சூழல், புள்ளிப்_பாதை) {
    இப்போதைய_மதிப்பு = சூழல்;
    ஒவ்வொரு பகுதி இல் பிரி(புள்ளிப்_பாதை, ".") {
        (வகை(இப்போதைய_மதிப்பு) == "an array" அல்லது வகை(இப்போதைய_மதிப்பு) == "a string" அல்லது வகை(இப்போதைய_மதிப்பு) == "a number"
            அல்லது வகை(இப்போதைய_மதிப்பு) == "a boolean" அல்லது வகை(இப்போதைய_மதிப்பு) == "nil") எனில் {
            திரும்பு தவறு(புள்ளிப்_பாதை & " இல் " & பகுதி & " இல்லை  (" & பகுதி & " is missing from " & புள்ளிப்_பாதை & ")");
        }
        (இல்லை புலம்_உள்ளதா(இப்போதைய_மதிப்பு, பகுதி)) எனில் {
            திரும்பு தவறு(புள்ளிப்_பாதை & " இல் " & பகுதி & " இல்லை  (" & பகுதி & " is missing from " & புள்ளிப்_பாதை & ")");
        }
        இப்போதைய_மதிப்பு = இப்போதைய_மதிப்பு[பகுதி];
    }
    திரும்பு சரி(இப்போதைய_மதிப்பு);
}

// __வார்ப்புத்_தயார்நிலை(பிணைப்புகள், சூழல்) — how ready the data is for this template__
// வார்ப்புத்_தயார்நிலை(பிணைப்புகள், சூழல்) — இவ்வார்ப்புருவுக்குத் தரவு எவ்வளவு தயார்
//
// __{சதவீதம், இல்லாதவை}: the whole percentage of required bindings satisfied, and__
// __the paths of those that are not. A template with no required bindings is__
// __100% ready — it can always be written.__
செயல் வார்ப்புத்_தயார்நிலை(பிணைப்புகள், சூழல்) {
    தேவை = 0;
    நிறைந்தவை = 0;
    இல்லாதவை = [];
    ஒவ்வொரு பிணைப்பு இல் பிணைப்புகள் {
        (பிணைப்பு.கட்டாயமா) எனில் {
            தேவை = தேவை + 1;
            கிடைத்தது = பாதையில்_மதிப்பு(சூழல், பிணைப்பு.பிணைப்புப்_பாதை);
            சரியானது = பொய்;
            (சரியா(கிடைத்தது)) எனில் {
                மதிப்பு_தரவு = மதிப்பு(கிடைத்தது);
                (பிணைப்பு.பிணைப்பு_வகை == "பட்டியல்") எனில் {
                    சரியானது = வகை(மதிப்பு_தரவு) == "an array" மற்றும் நீளம்(மதிப்பு_தரவு) > 0;
                } இன்றேல் {
                    சரியானது = மதிப்பு_தரவு != "" மற்றும் மதிப்பு_தரவு != இன்மை;
                    (வகை(மதிப்பு_தரவு) == "an array" அல்லது வகை(மதிப்பு_தரவு) == "a record") எனில் {
                        சரியானது = நீளம்(மதிப்பு_தரவு) > 0;
                    }
                }
            }
            (சரியானது) எனில் { நிறைந்தவை = நிறைந்தவை + 1; }
            இன்றேல் { இல்லாதவை = இணை(இல்லாதவை, பிணைப்பு.பிணைப்புப்_பாதை); }
        }
    }
    சதவீதம் = 100;
    (தேவை > 0) எனில் { சதவீதம் = வட்டமிடு(நிறைந்தவை * 100 / தேவை, 0); }
    திரும்பு { சதவீதம்: சதவீதம், இல்லாதவை: இல்லாதவை };
}

nUlakam/qittam/kattuppAtu.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/kattuppAtu.qmz — கட்டுப்பாட்டுக் கணக்கு (control accounts,__
// கட்டுப்பாட்டுக் கணக்கும் நிதித் தொகுதியும்
// __the time-phased budget, and reserves)__
//
// __The control account is where project structure meets the ledger: a WBS node__
// __designated as the level at which scope, budget, actual cost and schedule are__
// __integrated and performance is measured. It has one owner, one code, and that__
// __code is a real account in the accounting system, so an invoice can be booked__
// __straight to it instead of to one undifferentiated "project" account.__
//
// __If that mapping is not designed before the first invoice arrives it gets__
// __improvised later, and the improvisation is always the same: a spreadsheet in__
// __which someone reconciles project codes to cost centres every month. That__
// __spreadsheet is where project cost control quietly dies.__
//
// __A budget is not a total. It is a total *distributed across periods*, because__
// __a project with the right total and the wrong phasing reports an alarming__
// __variance every month while being perfectly on track. Planned value — the PV__
// __of earned value analysis — is read off that distribution and nowhere else.__

இறக்கு "pakuppu.qmz";

// __--- The control account -------------------------------------------------__

// கட்டுப்பாட்டுக்_கணக்கு_ஆக்கு(கணக்குக்_குறி, கணு_குறி, உரிமையாளர்)
//
// __கணக்குக்_குறி is the code the ledger knows. கணு_குறி is the WBS node it sits__
// __on. Keeping them as separate fields rather than one identifier is what lets__
// __the accounting structure and the work structure be renamed independently,__
// __which they will be.__
// கட்டுப்பாட்டுக்_கணக்கு_ஆக்கு(கணக்குக்_குறி, கணு_குறி, உரிமையாளர்) — ஒரு கட்டுப்பாட்டுக் கணக்கை உருவாக்கும்
செயல் கட்டுப்பாட்டுக்_கணக்கு_ஆக்கு(கணக்குக்_குறி, கணு_குறி, உரிமையாளர்) {
    திரும்பு {
        கணக்குக்_குறி: கணக்குக்_குறி,
        கணு_குறி: கணு_குறி,
        உரிமையாளர்: உரிமையாளர்
    };
}

// ஒரே_கணக்கா(கணக்குகள், கணுக்கள், கணு_குறி)
//
// __Exactly one control account must lie on the path from a work package to the__
// __root. Two means the package's cost is counted twice; none means it is__
// __counted nowhere. Neither shows up in a tree view, and both show up in the__
// __totals, which is the worst possible combination.__
// ஒரே_கணக்கா(கணக்குகள், கணுக்கள், கணு_குறி) — இக்கணு ஒரே ஒரு கட்டுப்பாட்டுக் கணக்கின் கீழ் வருகிறதா
செயல் ஒரே_கணக்கா(கணக்குகள், கணுக்கள், கணு_குறி) {
    திரும்பு பாதையில்_கணக்குகள்(கணக்குகள், கணுக்கள், கணு_குறி) == 1;
}

// __பாதையில்_கணக்குகள்(கணக்குகள், கணுக்கள், கணு_குறி) — how many control accounts lie on the path to the root__
// பாதையில்_கணக்குகள்(கணக்குகள், கணுக்கள், கணு_குறி) — மூலம் வரையிலான பாதையில் எத்தனை கட்டுப்பாட்டுக் கணக்குகள்
//
// __Walks up the parent chain counting as it goes. More than one is the error worth finding: a WBS branch controlled at two levels has its cost counted twice in the roll-up, and the totals still look plausible because every individual number is right.__
செயல் பாதையில்_கணக்குகள்(கணக்குகள், கணுக்கள், கணு_குறி) {
    (கணு_குறி == "") எனில் { திரும்பு 0; }
    எண்ணிக்கை = 0;
    ஒவ்வொரு ஒரு_கணக்கு இல் கணக்குகள் {
        (ஒரு_கணக்கு.கணு_குறி == கணு_குறி) எனில் { எண்ணிக்கை = எண்ணிக்கை + 1; }
    }
    விடை = கணு_தேடு(கணுக்கள், கணு_குறி);
    (தவறா(விடை)) எனில் { திரும்பு எண்ணிக்கை; }
    திரும்பு எண்ணிக்கை
           + பாதையில்_கணக்குகள்(கணக்குகள், கணுக்கள்,
                                 மதிப்பு(விடை).பெற்றோர்_குறி);
}

// __கட்டமைப்பை_சரிபார்(கணக்குகள், கணுக்கள்) — every work package, checked__
// கட்டமைப்பை_சரிபார்(கணக்குகள், கணுக்கள்) — ஒவ்வொரு வேலைத் தொகுப்பையும் சரிபார்க்கும்
செயல் கட்டமைப்பை_சரிபார்(கணக்குகள், கணுக்கள்) {
    ஒவ்வொரு ஒரு_கணு இல் வேலைத்_தொகுப்புகள்(கணுக்கள்) {
        எத்தனை = பாதையில்_கணக்குகள்(கணக்குகள், கணுக்கள், ஒரு_கணு.கணு_குறி);
        (எத்தனை != 1) எனில் {
            திரும்பு தவறு(ஒரு_கணு.கணு_குறி & ": பாதையில் "
                          & எத்தனை & " கட்டுப்பாட்டுக் கணக்குகள், ஒன்று வேண்டும்");
        }
    }
    திரும்பு சரி(மெய்);
}

// __--- The time-phased budget ---------------------------------------------__

// __காலப்_பகிர்வு(காலம்_எண், காலத்_தொகை) — one period's slice of the budget__
// காலப்_பகிர்வு(காலம்_எண், காலத்_தொகை) — ஒரு காலத்துக்கான நிதிப் பங்கு
//
// __A time-phased budget is a list of these. Held as period number and amount rather than as dates, because the phasing is relative to the project and survives the start date moving.__
செயல் காலப்_பகிர்வு(காலம்_எண், காலத்_தொகை) {
    திரும்பு { காலம்_எண்: காலம்_எண், காலத்_தொகை: காலத்_தொகை };
}

// __திரட்டிய_நிதி(பகிர்வுகள், காலம்_வரை) — the S-curve read at one period__
// திரட்டிய_நிதி(பகிர்வுகள், காலம்_வரை) — சொன்ன காலம் வரை திரட்டிய நிதி
//
// __This is planned value. It is cumulative by definition: PV at period 10 is__
// __everything scheduled to be complete by then, not period 10's slice.__
செயல் திரட்டிய_நிதி(பகிர்வுகள், காலம்_வரை) {
    ஓடும்_கூட்டல் = 0;
    ஒவ்வொரு ஒரு_பகிர்வு இல் பகிர்வுகள் {
        (ஒரு_பகிர்வு.காலம்_எண் <= காலம்_வரை) எனில் {
            ஓடும்_கூட்டல் = ஓடும்_கூட்டல் + ஒரு_பகிர்வு.காலத்_தொகை;
        }
    }
    திரும்பு ஓடும்_கூட்டல்;
}

// __மொத்த_நிதி(பகிர்வுகள்) — the phased budget added back up__
// மொத்த_நிதி(பகிர்வுகள்) — காலவாரியாகப் பகிர்ந்த நிதியின் கூட்டுத்தொகை
//
// __Must equal the budget at completion. The check that phasing has not quietly changed the total: moving money between periods is replanning, and creating or losing some is an error.__
செயல் மொத்த_நிதி(பகிர்வுகள்) {
    ஓடும்_கூட்டல் = 0;
    ஒவ்வொரு ஒரு_பகிர்வு இல் பகிர்வுகள் {
        ஓடும்_கூட்டல் = ஓடும்_கூட்டல் + ஒரு_பகிர்வு.காலத்_தொகை;
    }
    திரும்பு ஓடும்_கூட்டல்;
}

// __--- Reserves ------------------------------------------------------------__

// நிதித்_தொகுதி_ஆக்கு(அடிப்படை_நிதி, தற்செயல்_இருப்பு, மேலாண்மை_இருப்பு)
//
// __Two reserves, and the distinction is not bureaucratic. Contingency reserve__
// __covers *identified* risks, sits inside the performance measurement baseline__
// __and is the project manager's to spend. Management reserve covers the__
// __unknown, sits outside the baseline and belongs to the sponsor.__
//
// __Performance is measured against the baseline. If management reserve were__
// __inside it, drawing on the reserve would improve reported performance, which__
// __is exactly backwards — and is how a project 30% over budget reports itself__
// __as on plan.__
// நிதித்_தொகுதி_ஆக்கு(அடிப்படை_நிதி, தற்செயல்_இருப்பு, மேலாண்மை_இருப்பு) — நிதித் தொகுதியை உருவாக்கும்
செயல் நிதித்_தொகுதி_ஆக்கு(அடிப்படை_நிதி, தற்செயல்_இருப்பு, மேலாண்மை_இருப்பு) {
    திரும்பு {
        அடிப்படை_நிதி: அடிப்படை_நிதி,
        தற்செயல்_இருப்பு: தற்செயல்_இருப்பு,
        மேலாண்மை_இருப்பு: மேலாண்மை_இருப்பு
    };
}

// __அளவீட்டு_அடிப்படை(தொகுதி) — the performance measurement baseline__
// அளவீட்டு_அடிப்படை(தொகுதி) — செயல்திறன் அளவீட்டுக்கான அடிப்படை
செயல் அளவீட்டு_அடிப்படை(தொகுதி) {
    திரும்பு தொகுதி.அடிப்படை_நிதி + தொகுதி.தற்செயல்_இருப்பு;
}

// __அனுமதித்த_நிதி(தொகுதி) — baseline plus management reserve__
// அனுமதித்த_நிதி(தொகுதி) — அடிப்படையுடன் மேலாண்மை இருப்பும் சேர்த்தது
செயல் அனுமதித்த_நிதி(தொகுதி) {
    திரும்பு அளவீட்டு_அடிப்படை(தொகுதி) + தொகுதி.மேலாண்மை_இருப்பு;
}

// இருப்பை_விடுவி(தொகுதி, விடுவிக்கும்_தொகை)
//
// __Releasing management reserve moves value into the baseline; it does not__
// __create any. The total authorised funding is unchanged by the transfer, which__
// __is the property the test asserts. A release larger than the reserve is a__
// __தவறு rather than a silent overdraft.__
// இருப்பை_விடுவி(தொகுதி, விடுவிக்கும்_தொகை) — மேலாண்மை இருப்பிலிருந்து ஒரு தொகையை விடுவிக்கும்
செயல் இருப்பை_விடுவி(தொகுதி, விடுவிக்கும்_தொகை) {
    (விடுவிக்கும்_தொகை <= 0) எனில் {
        திரும்பு தவறு("விடுவிப்புத் தொகை பூஜ்யம் அல்லது எதிர்மறை");
    }
    (விடுவிக்கும்_தொகை > தொகுதி.மேலாண்மை_இருப்பு) எனில் {
        திரும்பு தவறு("மேலாண்மை இருப்பு " & தொகுதி.மேலாண்மை_இருப்பு
                      & " மட்டுமே; " & விடுவிக்கும்_தொகை & " கேட்கப்பட்டது");
    }
    திரும்பு சரி({
        அடிப்படை_நிதி: தொகுதி.அடிப்படை_நிதி + விடுவிக்கும்_தொகை,
        தற்செயல்_இருப்பு: தொகுதி.தற்செயல்_இருப்பு,
        மேலாண்மை_இருப்பு: தொகுதி.மேலாண்மை_இருப்பு - விடுவிக்கும்_தொகை
    });
}

nUlakam/qittam/mARRak_kOrikkY.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/mARRak_kOrikkY.qmz — மாற்றக் கோரிக்கை (change control)__
// மாற்றக் கோரிக்கையும் நோக்க வாயிலும்
//
// __Once scope is signed, the plan changes only through a change request, and__
// __the request itself goes through four hands before it binds anyone:__
//
//   __கோரியது → மதிப்பாய்ந்தது → ஒப்புக்கொண்டது → ஏற்றது → (திரும்பப்பெற்றது)__
//
// __and at any step before approval it may be மறுத்தது (rejected) or__
// __கைவிட்டது (cancelled). Approval is not terminal: an approved change can be__
// __revoked, which is why ஏற்றது does not stamp a decision date and__
// __திரும்பப்பெற்றது does.__
//
// __The lifecycle is a nilYmARRam.qmz machine, so moving a request is__
// __நிலையை_நகர்த்து with the machine below, and the screen's buttons are__
// __அடுத்த_நிலைகள் of the same machine.__

இறக்கு "nilYmARRam.qmz";
இறக்கு "paNi.qmz";

// __மாற்றக்_கோரிக்கை_வரைவு() — the change-request lifecycle as a machine__
// மாற்றக்_கோரிக்கை_வரைவு() — மாற்றக் கோரிக்கையின் நிலை வரைவு
//
// __Each forward step records who took it: மதிப்பாய்ந்தவர், ஒப்புக்கொண்டவர்,__
// __ஏற்றவர். Rejection and cancellation are recorded by the audit event rather__
// __than a field, since they can happen at any of three steps.__
செயல் மாற்றக்_கோரிக்கை_வரைவு() {
    திரும்பு நிலை_வரைவு_ஆக்கு([
        நிலை_மாற்றம்_ஆக்கு("கோரியது", ["மதிப்பாய்ந்தது", "மறுத்தது", "கைவிட்டது"]),
        நிலை_மாற்றம்_ஆக்கு("மதிப்பாய்ந்தது", ["ஒப்புக்கொண்டது", "மறுத்தது", "கைவிட்டது"]),
        நிலை_மாற்றம்_ஆக்கு("ஒப்புக்கொண்டது", ["ஏற்றது", "மறுத்தது", "கைவிட்டது"]),
        நிலை_மாற்றம்_ஆக்கு("ஏற்றது", ["திரும்பப்பெற்றது"]),
        நிலை_மாற்றம்_ஆக்கு("மறுத்தது", []),
        நிலை_மாற்றம்_ஆக்கு("கைவிட்டது", []),
        நிலை_மாற்றம்_ஆக்கு("திரும்பப்பெற்றது", [])
    ], {
        "மதிப்பாய்ந்தது": "மதிப்பாய்ந்தவர்",
        "ஒப்புக்கொண்டது": "ஒப்புக்கொண்டவர்",
        "ஏற்றது": "ஏற்றவர்"
    });
}

// __புதிய_பணிக்கு_அனுமதியா(நோக்கம்_கையொப்பமா, பெற்றோர்_குறி, மாற்றக்_குறி) — may this task be added?__
// புதிய_பணிக்கு_அனுமதியா(நோக்கம்_கையொப்பமா, பெற்றோர்_குறி, மாற்றக்_குறி) — இப்புதிய பணியைச் சேர்க்கலாமா
//
// __The scope gate. Before scope is signed anything may be added. After, a new__
// __top-level task is new scope and needs the change request that approved it;__
// __a sub-task under an existing task is how the team breaks down work it__
// __already owns and is always allowed. சரி or தவறு with the reason.__
செயல் புதிய_பணிக்கு_அனுமதியா(நோக்கம்_கையொப்பமா, பெற்றோர்_குறி, மாற்றக்_குறி) {
    (இல்லை நோக்கம்_கையொப்பமா) எனில் { திரும்பு சரி(மெய்); }
    (பெற்றோர்_குறி != "") எனில் { திரும்பு சரி(மெய்); }
    (மாற்றக்_குறி != "") எனில் { திரும்பு சரி(மெய்); }
    திரும்பு தவறு("நோக்கம் கையொப்பமாகியுள்ளது; புதிய மேல்மட்டப் பணிக்கு மாற்றக் கோரிக்கை தேவை  "
                   & "(scope is signed; a new top-level task needs a change request)");
}

// __மாற்ற_உருப்படி_ஆக்கு(உருப்படிக்_குறி, பெற்றோர்_குறி, விவரம், மதிப்பீட்டு_மணி) — one piece of work a change request adds__
// மாற்ற_உருப்படி_ஆக்கு(உருப்படிக்_குறி, பெற்றோர்_குறி, விவரம், மதிப்பீட்டு_மணி) — மாற்றக் கோரிக்கை சேர்க்கும் ஒரு வேலை
//
// __பெற்றோர்_குறி may name another item of the same request or a task that__
// __already exists — a change often adds sub-tasks under work already planned —__
// __or "" for new top-level work.__
செயல் மாற்ற_உருப்படி_ஆக்கு(உருப்படிக்_குறி, பெற்றோர்_குறி, விவரம், மதிப்பீட்டு_மணி) {
    திரும்பு { உருப்படிக்_குறி: உருப்படிக்_குறி, பெற்றோர்_குறி: பெற்றோர்_குறி,
              விவரம்: விவரம், மதிப்பீட்டு_மணி: மதிப்பீட்டு_மணி };
}

// __மாற்றத்தைப்_பணிகளாக்கு(ஒரு_கோரிக்கை, உருப்படிகள்) — an approved request's items as tasks__
// மாற்றத்தைப்_பணிகளாக்கு(ஒரு_கோரிக்கை, உருப்படிகள்) — ஏற்ற கோரிக்கையின் உருப்படிகளைப் பணிகளாக்கும்
//
// __The step that makes a change binding: once approved, what it asked for__
// __becomes planned work. Each item comes back as a paNi.qmz task — to do, 0%,__
// __with its estimate and description — carrying மாற்றக்_குறி, the request's__
// __own code, so the scope gate in புதிய_பணிக்கு_அனுமதியா lets it in and anyone__
// __reading the plan can see which change added it. Parents come before their__
// __children, so a caller creating them one at a time never meets a child whose__
// __parent does not exist yet.__
//
// __Refused unless the request is in ஏற்றது: materialising a request that is__
// __only reviewed is how unapproved scope gets built. ஒரு_கோரிக்கை must carry its__
// __code in மாற்றக்_குறி and its state in நடப்பு_நிலை.__
செயல் மாற்றத்தைப்_பணிகளாக்கு(ஒரு_கோரிக்கை, உருப்படிகள்) {
    (ஒரு_கோரிக்கை.நடப்பு_நிலை != "ஏற்றது") எனில் {
        திரும்பு தவறு("கோரிக்கை ஏற்கப்படவில்லை (" & ஒரு_கோரிக்கை.நடப்பு_நிலை
                       & "); பணிகளாக்க முடியாது  (the request is not approved, so it cannot become tasks)");
    }
    பணிகள் = [];
    ஒவ்வொரு உருப்படி இல் உருப்படிகள் {
        புதியது = பணி_ஆக்கு(உருப்படி.உருப்படிக்_குறி, உருப்படி.பெற்றோர்_குறி, "செய்யவேண்டியது", 0,
                            உருப்படி.மதிப்பீட்டு_மணி, "");
        புதியது["விவரம்"] = உருப்படி.விவரம்;
        புதியது["மாற்றக்_குறி"] = ஒரு_கோரிக்கை.மாற்றக்_குறி;
        பணிகள் = இணை(பணிகள், புதியது);
    }
    திரும்பு பெற்றோர்_முன்_வரிசை(பணிகள், "பணி_குறி", "பெற்றோர்_குறி");
}

nUlakam/qittam/maRu_attavaNY.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/maRu_attavaNY.qmz — மறு அட்டவணை (rescheduling a project already under way)__
// நடப்பிலுள்ள திட்டத்தை மீண்டும் அட்டவணையிடுதல்
//
// __attavaNY.qmz lays out a plan that has not started. Nobody reschedules a plan__
// __that has not started. By the time the question is asked, some work is done,__
// __some is half done, and the rest is waiting — and each of the three has to be__
// __treated differently or the new schedule is fiction:__
//
//   __done          sits on its actual dates. It happened when it happened.__
//   __in progress   keeps its actual start, and only the work left is laid out,__
//                 __from today. Moving its start would rewrite history.__
//   __not started   starts no earlier than today, the project start, its own__
//                 __முந்தாத_நாள் and the working day after its last predecessor__
//                 __finishes — the latest of the four.__
//
// __Cancelled work is left out altogether, and constrains nothing after it.__
// __முந்தாத_நாள் ("not before") is how a phase floor is expressed: give every__
// __task in a phase the phase's earliest start.__
//
// __Dependencies are finish-to-start, and everything is in working days on the__
// __calendar given. A zero-day task is a milestone and falls on the day its last__
// __predecessor finishes. The backward pass gives each task its late finish and__
// __its float in working days. Float can be negative: when an actual date is later__
// __than the plan allowed, the tasks behind it are late already, and a negative__
// __float is how the schedule says so.__
//
// __Tasks are paNi.qmz records given a duration and predecessors by__
// __அட்டவணைக்கு_அமை, so the same records carry status, progress and schedule.__

இறக்கு "../atippatY/kaNiqam.qmz";
இறக்கு "../atippatY/aNi.qmz";
இறக்கு "../nAtkAtti/mAqam.qmz";
இறக்கு "../nAtkAtti/vElYnAL.qmz";
இறக்கு "paNi.qmz";
இறக்கு "attavaNY.qmz";

// __அட்டவணைக்கு_அமை(ஒரு_பணி, கால_அளவு, முன்னோடிகள்) — give a task what the scheduler needs__
// அட்டவணைக்கு_அமை(ஒரு_பணி, கால_அளவு, முன்னோடிகள்) — பணிக்குக் கால அளவும் முன்னோடிகளும் தரும்
//
// __கால_அளவு is working days (0 for a milestone); முன்னோடிகள் a list of task__
// __codes. The optional dates the scheduler reads are added empty if missing:__
// __உண்மைத்_தொடக்கம் (actual start), முடிந்த_நாள் (actual finish) and__
// __முந்தாத_நாள் (not before). Set them on the returned record as they become known.__
செயல் அட்டவணைக்கு_அமை(ஒரு_பணி, கால_அளவு, முன்னோடிகள்) {
    புதியது = ஒரு_பணி;
    புதியது["கால_அளவு"] = கால_அளவு;
    புதியது["முன்னோடிகள்"] = முன்னோடிகள்;
    ஒவ்வொரு புலப்_பெயர் இல் ["உண்மைத்_தொடக்கம்", "முடிந்த_நாள்", "முந்தாத_நாள்"] {
        (இல்லை புலம்_உள்ளதா(புதியது, புலப்_பெயர்)) எனில் { புதியது[புலப்_பெயர்] = ""; }
    }
    திரும்பு புதியது;
}

// __மறு_அட்டவணையிடு(பணிகள், திட்டத்_தொடக்கம், இன்றைய_நாள், ஒரு_நாட்காட்டி) — the schedule as of today__
// மறு_அட்டவணையிடு(பணிகள், திட்டத்_தொடக்கம், இன்றைய_நாள், ஒரு_நாட்காட்டி) — இன்றைய நிலையில் அட்டவணை
//
// __சரி({பணிகள், திட்டத்_தொடக்க_நாள், திட்ட_முடிவு_நாள்}). Each task comes back,__
// __in the order given, with தொடக்க_நாள், முடிவு_நாள், பிந்தைய_முடிவு_நாள் (late__
// __finish), மிதப்பு (float, working days), கடும்_பாதையா (float ≤ 0 and not done)__
// __and நங்கூரம் — what fixed it: "உண்மை" (actual dates), "நடப்பில்" (actual__
// __start, remaining work), "திட்டம்" (planned) or "கைவிட்டது" (left out, dates "").__
//
// __தவறு when a predecessor is not in the list, or the predecessors form a cycle:__
// __either would otherwise produce dates that look right and are not.__
//
// __A done task with no actual start is placed from its predecessors like planned__
// __work but without today's floor — it happened, and only when is unknown.__
செயல் மறு_அட்டவணையிடு(பணிகள், திட்டத்_தொடக்கம், இன்றைய_நாள், ஒரு_நாட்காட்டி) {
    குறியால் = {};
    ஒவ்வொரு ஒரு_பணி இல் பணிகள் { குறியால்[ஒரு_பணி.பணி_குறி] = ஒரு_பணி; }
    பின்வருபவை = {};
    ஒவ்வொரு ஒரு_பணி இல் பணிகள் { பின்வருபவை[ஒரு_பணி.பணி_குறி] = []; }
    ஒவ்வொரு ஒரு_பணி இல் பணிகள் {
        ஒவ்வொரு முன் இல் ஒரு_பணி.முன்னோடிகள் {
            (இல்லை புலம்_உள்ளதா(குறியால், முன்)) எனில் {
                திரும்பு தவறு(ஒரு_பணி.பணி_குறி & " இன் முன்னோடி " & முன் & " பட்டியலில் இல்லை  (predecessor "
                               & முன் & " of " & ஒரு_பணி.பணி_குறி & " is not in the list)");
            }
            பின்வருபவை[முன்] = இணை(பின்வருபவை[முன்], ஒரு_பணி.பணி_குறி);
        }
    }

    // __Predecessors first. Swept to a fixed point, like பெற்றோர்_முன்_வரிசை; what__
    // __is left unplaced is on a cycle.__
    இட்ட_வரிசை = [];
    வைத்தவை = {};
    முன்னேற்றம் = மெய்;
    (முன்னேற்றம்) சுற்று {
        முன்னேற்றம் = பொய்;
        ஒவ்வொரு ஒரு_பணி இல் பணிகள் {
            (இல்லை புலம்_உள்ளதா(வைத்தவை, ஒரு_பணி.பணி_குறி)) எனில் {
                தயார் = மெய்;
                ஒவ்வொரு முன் இல் ஒரு_பணி.முன்னோடிகள் {
                    (இல்லை புலம்_உள்ளதா(வைத்தவை, முன்)) எனில் { தயார் = பொய்; }
                }
                (தயார்) எனில் {
                    இட்ட_வரிசை = இணை(இட்ட_வரிசை, ஒரு_பணி);
                    வைத்தவை[ஒரு_பணி.பணி_குறி] = மெய்;
                    முன்னேற்றம் = மெய்;
                }
            }
        }
    }
    (நீளம்(இட்ட_வரிசை) < நீளம்(பணிகள்)) எனில் {
        திரும்பு தவறு("முன்னோடிகளில் சுழற்சி உள்ளது  (the predecessors form a cycle)");
    }

    தொடக்க_எல்லை = மதிப்பு(நகர்த்தி_வேலை_நாள்(திட்டத்_தொடக்கம், ஒரு_நாட்காட்டி));
    இன்று_வேலை = மதிப்பு(நகர்த்தி_வேலை_நாள்(இன்றைய_நாள், ஒரு_நாட்காட்டி));

    // __Forward: the earliest each task can be, given what has already happened.__
    தொடக்கங்கள் = {};
    முடிவுகள் = {};
    நங்கூரங்கள் = {};
    ஒவ்வொரு ஒரு_பணி இல் இட்ட_வரிசை {
        குறி = ஒரு_பணி.பணி_குறி;
        நாட்கள் = ஒரு_பணி.கால_அளவு;
        பணி_நிலை = ஒரு_பணி.நடப்பு_நிலை;
        உண்மை = புலம்_அல்லது(ஒரு_பணி, "உண்மைத்_தொடக்கம்", "");
        முன்_முடிவு = "";
        ஒவ்வொரு முன் இல் ஒரு_பணி.முன்னோடிகள் { முன்_முடிவு = பிந்தையது(முன்_முடிவு, முடிவுகள்[முன்]); }

        (பணி_நிலை == "கைவிட்டது") எனில் {
            தொடக்கங்கள்[குறி] = "";
            முடிவுகள்[குறி] = "";
            நங்கூரங்கள்[குறி] = "கைவிட்டது";
        } இன்றேல் {
            (பணி_முடிந்ததா(பணி_நிலை) மற்றும் உண்மை != "") எனில் {
                தொடக்கம் = உண்மை;
                முடிவு = புலம்_அல்லது(ஒரு_பணி, "முடிந்த_நாள்", "");
                (முடிவு == "") எனில் {
                    முடிவு = மதிப்பு(வேலை_நாட்களைக்_கூட்டு(தொடக்கம், பெரியது(0, நாட்கள் - 1), ஒரு_நாட்காட்டி));
                }
                நங்கூரங்கள்[குறி] = "உண்மை";
            } இன்றேல் {
                (பணி_நிலை == "நடப்பில்" மற்றும் உண்மை != "") எனில் {
                    தொடக்கம் = உண்மை;
                    மீதி_நாள்_எண் = மீதி_நாட்கள்(நாட்கள், ஒரு_பணி.நிறைவு);
                    அடி = பிந்தையது(தொடக்கம், இன்று_வேலை);
                    முடிவு = அடி;
                    (மீதி_நாள்_எண் > 0) எனில் {
                        முடிவு = மதிப்பு(வேலை_நாட்களைக்_கூட்டு(அடி, மீதி_நாள்_எண் - 1, ஒரு_நாட்காட்டி));
                    }
                    நங்கூரங்கள்[குறி] = "நடப்பில்";
                } இன்றேல் {
                    எல்லை = தொடக்க_எல்லை;
                    முந்தாதது = புலம்_அல்லது(ஒரு_பணி, "முந்தாத_நாள்", "");
                    (முந்தாதது != "") எனில் {
                        எல்லை = பிந்தையது(எல்லை, மதிப்பு(நகர்த்தி_வேலை_நாள்(முந்தாதது, ஒரு_நாட்காட்டி)));
                    }
                    (இல்லை பணி_முடிந்ததா(பணி_நிலை)) எனில் { எல்லை = பிந்தையது(எல்லை, இன்று_வேலை); }
                    (நாட்கள் == 0) எனில் {
                        தொடக்கம் = பிந்தையது(எல்லை, முன்_முடிவு);
                        முடிவு = தொடக்கம்;
                    } இன்றேல் {
                        (முன்_முடிவு != "") எனில் {
                            எல்லை = பிந்தையது(எல்லை, மதிப்பு(அடுத்த_வேலை_நாள்(முன்_முடிவு, ஒரு_நாட்காட்டி)));
                        }
                        தொடக்கம் = எல்லை;
                        முடிவு = மதிப்பு(வேலை_நாட்களைக்_கூட்டு(தொடக்கம், நாட்கள் - 1, ஒரு_நாட்காட்டி));
                    }
                    நங்கூரங்கள்[குறி] = "திட்டம்";
                }
            }
            தொடக்கங்கள்[குறி] = தொடக்கம்;
            முடிவுகள்[குறி] = முடிவு;
        }
    }

    திட்ட_முடிவு = "";
    ஒவ்வொரு ஒரு_பணி இல் பணிகள் { திட்ட_முடிவு = பிந்தையது(திட்ட_முடிவு, முடிவுகள்[ஒரு_பணி.பணி_குறி]); }

    // __Backward: the latest each task can finish without moving the project's end.__
    பிந்தைய_முடிவுகள் = {};
    பிந்தைய_தொடக்கங்கள் = {};
    ஒவ்வொரு ஒரு_பணி இல் தலைகீழ்(இட்ட_வரிசை) {
        குறி = ஒரு_பணி.பணி_குறி;
        (நங்கூரங்கள்[குறி] != "கைவிட்டது") எனில் {
            பிந்தியது = திட்ட_முடிவு;
            ஒவ்வொரு பின் இல் பின்வருபவை[குறி] {
                (நங்கூரங்கள்[பின்] != "கைவிட்டது") எனில் {
                    வேட்பு = பிந்தைய_தொடக்கங்கள்[பின்];
                    (குறியால்[பின்].கால_அளவு > 0) எனில் {
                        வேட்பு = மதிப்பு(வேலை_நாட்களைக்_கூட்டு(வேட்பு, 0 - 1, ஒரு_நாட்காட்டி));
                    }
                    (வேட்பு < பிந்தியது) எனில் { பிந்தியது = வேட்பு; }
                }
            }
            பிந்தைய_முடிவுகள்[குறி] = பிந்தியது;
            பிந்தைய_தொடக்கங்கள்[குறி] = பிந்தியது;
            (ஒரு_பணி.கால_அளவு > 0) எனில் {
                பிந்தைய_தொடக்கங்கள்[குறி] = மதிப்பு(வேலை_நாட்களைக்_கூட்டு(பிந்தியது,
                    0 - (ஒரு_பணி.கால_அளவு - 1), ஒரு_நாட்காட்டி));
            }
        }
    }

    விடை_பட்டி = [];
    ஒவ்வொரு ஒரு_பணி இல் பணிகள் {
        குறி = ஒரு_பணி.பணி_குறி;
        புதியது = ஒரு_பணி;
        புதியது["தொடக்க_நாள்"] = தொடக்கங்கள்[குறி];
        புதியது["முடிவு_நாள்"] = முடிவுகள்[குறி];
        புதியது["நங்கூரம்"] = நங்கூரங்கள்[குறி];
        (நங்கூரங்கள்[குறி] == "கைவிட்டது") எனில் {
            புதியது["பிந்தைய_முடிவு_நாள்"] = "";
            புதியது["மிதப்பு"] = 0;
            புதியது["கடும்_பாதையா"] = பொய்;
        } இன்றேல் {
            முடிவு = முடிவுகள்[குறி];
            பிந்தியது = பிந்தைய_முடிவுகள்[குறி];
            மிதப்பு = வேலை_நாட்களை_எண்ணு(முடிவு, பிந்தியது, ஒரு_நாட்காட்டி) - 1;
            (பிந்தியது < முடிவு) எனில் {
                மிதப்பு = 0 - (வேலை_நாட்களை_எண்ணு(பிந்தியது, முடிவு, ஒரு_நாட்காட்டி) - 1);
            }
            புதியது["பிந்தைய_முடிவு_நாள்"] = பிந்தியது;
            புதியது["மிதப்பு"] = மிதப்பு;
            புதியது["கடும்_பாதையா"] = மிதப்பு <= 0 மற்றும் நங்கூரங்கள்[குறி] != "உண்மை";
        }
        விடை_பட்டி = இணை(விடை_பட்டி, புதியது);
    }
    திரும்பு சரி({ பணிகள்: விடை_பட்டி, திட்டத்_தொடக்க_நாள்: தொடக்க_எல்லை,
                  திட்ட_முடிவு_நாள்: திட்ட_முடிவு });
}

// __துணைச்_சாளரங்கள்(தொடக்க_நாள், முடிவு_நாள், எண்ணிக்கை, ஒரு_நாட்காட்டி) — split a parent's window across its sub-tasks__
// துணைச்_சாளரங்கள்(தொடக்க_நாள், முடிவு_நாள், எண்ணிக்கை, ஒரு_நாட்காட்டி) — பெற்றோரின் காலத்தைத் துணைப் பணிகளுக்குப் பகிரும்
//
// __Sub-tasks with no dates of their own share their parent's window in order,__
// __each taking an equal run of working days; the last also takes whatever the__
// __division leaves over, so the windows end exactly when the parent does. A__
// __window shorter than the sub-tasks gives each one day, and the later ones sit__
// __on the parent's last day rather than past it. சரி with the list of__
// __{தொடக்கம், முடிவு}, or தவறு for a count below one.__
செயல் துணைச்_சாளரங்கள்(தொடக்க_நாள், முடிவு_நாள், எண்ணிக்கை, ஒரு_நாட்காட்டி) {
    (எண்ணிக்கை < 1) எனில் {
        திரும்பு தவறு("துணைப் பணிகள் ஒன்றாவது வேண்டும்  (there must be at least one sub-task)");
    }
    முதல் = மதிப்பு(நகர்த்தி_வேலை_நாள்(தொடக்க_நாள், ஒரு_நாட்காட்டி));
    சாளர_நாட்கள் = வேலை_நாட்களை_எண்ணு(முதல், முடிவு_நாள், ஒரு_நாட்காட்டி);
    ஒவ்வொன்றும் = பெரியது(1, தரை(சாளர_நாட்கள் / எண்ணிக்கை));
    கடைசி_நாள் = மதிப்பு(வேலை_நாட்களைக்_கூட்டு(முதல், பெரியது(0, சாளர_நாட்கள் - 1), ஒரு_நாட்காட்டி));
    விடை_பட்டி = [];
    வரிசை_இடம் = 0;
    (வரிசை_இடம் < எண்ணிக்கை) சுற்று {
        தொடக்கம் = மதிப்பு(வேலை_நாட்களைக்_கூட்டு(முதல், வரிசை_இடம் * ஒவ்வொன்றும், ஒரு_நாட்காட்டி));
        முடிவு = மதிப்பு(வேலை_நாட்களைக்_கூட்டு(முதல், (வரிசை_இடம் + 1) * ஒவ்வொன்றும் - 1, ஒரு_நாட்காட்டி));
        (வரிசை_இடம் == எண்ணிக்கை - 1) எனில் { முடிவு = கடைசி_நாள்; }
        (தொடக்கம் > கடைசி_நாள்) எனில் { தொடக்கம் = கடைசி_நாள்; }
        (முடிவு > கடைசி_நாள்) எனில் { முடிவு = கடைசி_நாள்; }
        விடை_பட்டி = இணை(விடை_பட்டி, { தொடக்கம்: தொடக்கம், முடிவு: முடிவு });
        வரிசை_இடம் = வரிசை_இடம் + 1;
    }
    திரும்பு சரி(விடை_பட்டி);
}

