// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/muZZERRa_muRY.qmz — முன்னேற்ற முறை: how much of a package counts as done__
// முன்னேற்ற முறை: ஒரு தொகுப்பில் எவ்வளவு முடிந்ததாகக் கணக்கு
//
// __The rule is chosen before the work starts, not after. 0/100 credits__
// __nothing until a package is finished, which is the honest choice when__
// __partial progress cannot be observed.__

// __முறை_0_100(முடிந்ததா) — nothing until complete, then everything__
// முறை_0_100(முடிந்ததா) — முடியும் வரை ஒன்றும் இல்லை, முடிந்ததும் முழுவதும்
//
// __Conservative, ungameable, and right for any package inside one or two__
// __reporting periods.__
செயல் முறை_0_100(முடிந்ததா) {
    (முடிந்ததா) எனில் { திரும்பு 1; }
    திரும்பு 0;
}

// __முறை_50_50(தொடங்கியதா, முடிந்ததா) — half on starting, half on finishing__
// முறை_50_50(தொடங்கியதா, முடிந்ததா) — தொடங்கும்போது பாதி, முடியும்போது மீதி
செயல் முறை_50_50(தொடங்கியதா, முடிந்ததா) {
    (முடிந்ததா) எனில் { திரும்பு 1; }
    (தொடங்கியதா) எனில் { திரும்பு 0.5; }
    திரும்பு 0;
}

// __முறை_மைல்கற்கள்(அடைந்த_எடைகள்) — weighted milestones__
// முறை_மைல்கற்கள்(அடைந்த_எடைகள்) — எடையிட்ட மைல்கற்களால் முன்னேற்றம்
//
// __For long packages. The weights are assigned *before* work starts and credit__
// __is taken only when a milestone is objectively achieved. Pass the list of__
// __weights actually reached.__
செயல் முறை_மைல்கற்கள்(அடைந்த_எடைகள்) {
    ஓடும்_கூட்டல் = 0;
    ஒவ்வொரு ஒரு_எடை இல் அடைந்த_எடைகள் {
        ஓடும்_கூட்டல் = ஓடும்_கூட்டல் + ஒரு_எடை;
    }
    திரும்பு ஓடும்_கூட்டல்;
}

// __ஈட்டிய_மதிப்பு(கணு_நிதி, நிறைவுப்_பங்கு) — EV for one package__
// ஈட்டிய_மதிப்பு(கணு_நிதி, நிறைவுப்_பங்கு) — ஒரு தொகுப்புக்கான ஈட்டிய மதிப்பு
//
// __The *budget* of finished work, never its cost. That distinction is the__
// __entire mechanism: valuing completed work at what it was supposed to cost is__
// __what makes EV comparable with both PV and AC.__
செயல் ஈட்டிய_மதிப்பு(கணு_நிதி, நிறைவுப்_பங்கு) {
    திரும்பு கணு_நிதி * நிறைவுப்_பங்கு;
}

// __--- Variances -----------------------------------------------------------__

// __நிறைவுப்_பங்கு_நிதியால்(ஈட்டியது, மொத்த_நிதி) — percent complete, by value__
// நிறைவுப்_பங்கு_நிதியால்(ஈட்டியது, மொத்த_நிதி) — மதிப்பால் அளக்கும் நிறைவுப் பங்கு
//
// __Earned value over the whole budget. Measures work, not money spent and not time elapsed — the three differ, and reporting spend as progress is how a project is 90% complete for half its duration.__
செயல் நிறைவுப்_பங்கு_நிதியால்(ஈட்டியது, மொத்த_நிதி) {
    (மொத்த_நிதி == 0) எனில் { திரும்பு தவறு("மொத்த நிதி பூஜ்யம்"); }
    திரும்பு சரி(ஈட்டியது / மொத்த_நிதி * 100);
}

nUlakam/qittam/muZZurYppu.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/muZZurYppu.qmz — முன்னுரைப்பு: what this will cost by the end__
// முன்னுரைப்பு: முடிவில் இது எவ்வளவாகும்
//
// __Three forecasts, because they disagree and the disagreement is the__
// __information: the rest goes to plan, the rest goes as badly as so far, or__
// __the schedule drags the cost with it.__
//
// __Three estimates at completion, answering three different questions. Which__
// __one to use is a governance decision, not a calculation preference, so the__
// __module makes the caller choose rather than defaulting silently — the spread__
// __between them is usually large enough to change what a steering committee__
// __does.__

// முடிவில்_மதிப்பீடு_மீதியால்(உண்மைச்_செலவு, மொத்த_நிதி, ஈட்டியது)
// __The overrun was a one-off; the rest goes to plan.__
// முடிவில்_மதிப்பீடு_மீதியால்(உண்மைச்_செலவு, மொத்த_நிதி, ஈட்டியது) — மீதி திட்டப்படியே போகும் என்ற அனுமானத்தில் முடிவு மதிப்பீடு
செயல் முடிவில்_மதிப்பீடு_மீதியால்(உண்மைச்_செலவு, மொத்த_நிதி, ஈட்டியது) {
    திரும்பு உண்மைச்_செலவு + (மொத்த_நிதி - ஈட்டியது);
}

// முடிவில்_மதிப்பீடு_திறனால்(மொத்த_நிதி, செலவுத்_திறன்)
// __Current cost efficiency persists. The default assumption, and usually right.__
// முடிவில்_மதிப்பீடு_திறனால்(மொத்த_நிதி, செலவுத்_திறன்) — இதுவரையான செயல்திறன் தொடரும் என்ற அனுமானத்தில்
செயல் முடிவில்_மதிப்பீடு_திறனால்(மொத்த_நிதி, செலவுத்_திறன்) {
    (செலவுத்_திறன் == 0) எனில் { திரும்பு தவறு("செயல்திறன் பூஜ்யம்"); }
    திரும்பு சரி(மொத்த_நிதி / செலவுத்_திறன்);
}

// முடிவில்_மதிப்பீடு_இரண்டாலும்(உண்மைச்_செலவு, மொத்த_நிதி, ஈட்டியது,
//                                செலவுத்_திறன், காலத்_திறன்)
// __Both cost and schedule pressure persist — appropriate when a fixed end date__
// __will force expediting.__
// முடிவில்_மதிப்பீடு_இரண்டாலும்(உண்மைச்_செலவு, மொத்த_நிதி, ஈட்டியது, செலவுத்_திறன், காலத்_திறன்) — செலவும் காலமும் சேர்ந்து பாதிக்கும் என்ற அனுமானத்தில்
செயல் முடிவில்_மதிப்பீடு_இரண்டாலும்(உண்மைச்_செலவு, மொத்த_நிதி, ஈட்டியது,
                                    செலவுத்_திறன், காலத்_திறன்) {
    கூட்டுத்_திறன் = செலவுத்_திறன் * காலத்_திறன்;
    (கூட்டுத்_திறன் == 0) எனில் { திரும்பு தவறு("கூட்டுச் செயல்திறன் பூஜ்யம்"); }
    திரும்பு சரி(உண்மைச்_செலவு + (மொத்த_நிதி - ஈட்டியது) / கூட்டுத்_திறன்);
}

// __முடிக்க_மீதி(முடிவில்_மதிப்பீடு, உண்மைச்_செலவு) — estimate to complete, ETC__
// முடிக்க_மீதி(முடிவில்_மதிப்பீடு, உண்மைச்_செலவு) — முடிக்க இன்னும் தேவைப்படும் மதிப்பீடு
//
// __What the rest is now expected to cost: the forecast at completion less what has already gone. Derived from the forecast rather than from the remaining budget, so it inherits whatever efficiency assumption that forecast was built on.__
செயல் முடிக்க_மீதி(முடிவில்_மதிப்பீடு, உண்மைச்_செலவு) {
    திரும்பு முடிவில்_மதிப்பீடு - உண்மைச்_செலவு;
}

// __முடிவில்_வேறுபாடு(மொத்த_நிதி, முடிவில்_மதிப்பீடு) — variance at completion, VAC__
// முடிவில்_வேறுபாடு(மொத்த_நிதி, முடிவில்_மதிப்பீடு) — முடிவில் எதிர்பார்க்கும் வேறுபாடு
//
// __The budget less the forecast: the overrun as it is expected to land, while there is still time to act on it. Negative is an overspend. This is the number a steering committee should be shown, because CV reports what has happened and VAC reports where it ends.__
செயல் முடிவில்_வேறுபாடு(மொத்த_நிதி, முடிவில்_மதிப்பீடு) {
    திரும்பு மொத்த_நிதி - முடிவில்_மதிப்பீடு;
}

// __முடிக்கத்_தேவையான_திறன்(மொத்த_நிதி, ஈட்டியது, உண்மைச்_செலவு) — TCPI__
// முடிக்கத்_தேவையான_திறன்(மொத்த_நிதி, ஈட்டியது, உண்மைச்_செலவு) — நிதிக்குள் முடிக்கத் தேவையான செயல்திறன்
//
// __The sharpest number on a status report: the efficiency now required to__
// __finish within budget. A project running at 0.91 that must run at 1.07 is__
// __being asked to improve by 18% immediately and hold it. Teams routinely__
// __promise this; it essentially never happens, and the gap between achieved and__
// __required is the quantitative form of that judgement.__
செயல் முடிக்கத்_தேவையான_திறன்(மொத்த_நிதி, ஈட்டியது, உண்மைச்_செலவு) {
    மீதி_நிதி = மொத்த_நிதி - உண்மைச்_செலவு;
    (மீதி_நிதி == 0) எனில் {
        திரும்பு தவறு("நிதி தீர்ந்தது: எந்தச் செயல்திறனும் போதாது");
    }
    திரும்பு சரி((மொத்த_நிதி - ஈட்டியது) / மீதி_நிதி);
}

nUlakam/qittam/nOkkam.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/nOkkam.qmz — நோக்கம் (scope: what is in, what is out, and what the features add)__
// நோக்கம்: உள்ளே, வெளியே, அம்சங்கள் சேர்ப்பவை
//
// __Before a plan has tasks it has scope: the WBS rows the statement of work__
// __offers, each marked as in (it becomes a task), excluded (it is written into__
// __the exclusions so nobody later assumes it was promised) or removed (it does__
// __not apply at all). On top of that, the features a customer chooses change the__
// __work — some add hours to a row that is already in, some add a row of their__
// __own.__
//
// __The answer is always recomputed from the three inputs rather than patched__
// __onto the last one. Choosing a feature, unchoosing it and choosing it again__
// __must give the plan it gave the first time, and a patching approach adds the__
// __hours twice. Here the same inputs always give the same tasks.__
//
// __A row's decision is one of "உள்ளே" (in scope), "விலக்கு" (excluded) and__
// __"நீக்கு" (removed). An impact is "மணி_கூட்டு" (add hours to a row) or__
// __"பணி_சேர்" (add a row, in scope, of its own).__

இறக்கு "paNi.qmz";

// __நோக்க_வரி_ஆக்கு(பகுப்புக்_குறி, விவரம், அடிப்படை_மணி, நோக்க_முடிவு) — one WBS row and the decision on it__
// நோக்க_வரி_ஆக்கு(பகுப்புக்_குறி, விவரம், அடிப்படை_மணி, நோக்க_முடிவு) — ஒரு பகுப்பு வரியும் அதன் முடிவும்
செயல் நோக்க_வரி_ஆக்கு(பகுப்புக்_குறி, விவரம், அடிப்படை_மணி, நோக்க_முடிவு) {
    திரும்பு { பகுப்புக்_குறி: பகுப்புக்_குறி, விவரம்: விவரம்,
              அடிப்படை_மணி: அடிப்படை_மணி, நோக்க_முடிவு: நோக்க_முடிவு };
}

// __அம்ச_விளைவு_ஆக்கு(அம்சக்_குறி, விளைவு_வகை, பகுப்புக்_குறி, கூடுதல்_மணி, விவரம்) — what one feature does to the plan__
// அம்ச_விளைவு_ஆக்கு(அம்சக்_குறி, விளைவு_வகை, பகுப்புக்_குறி, கூடுதல்_மணி, விவரம்) — ஓர் அம்சம் திட்டத்தில் செய்யும் மாற்றம்
//
// __For "மணி_கூட்டு", பகுப்புக்_குறி names the row the hours go on and விவரம் is__
// __ignored. For "பணி_சேர்", பகுப்புக்_குறி is the new row's code and விவரம் its__
// __description. A feature may have several impacts.__
செயல் அம்ச_விளைவு_ஆக்கு(அம்சக்_குறி, விளைவு_வகை, பகுப்புக்_குறி, கூடுதல்_மணி, விவரம்) {
    திரும்பு { அம்சக்_குறி: அம்சக்_குறி, விளைவு_வகை: விளைவு_வகை, பகுப்புக்_குறி: பகுப்புக்_குறி,
              கூடுதல்_மணி: கூடுதல்_மணி, விவரம்: விவரம் };
}

// __நோக்கத்தைப்_பயன்படுத்து(நோக்க_வரிகள், தேர்ந்த_அம்சங்கள், விளைவுகள்) — the tasks and exclusions the scope comes to__
// நோக்கத்தைப்_பயன்படுத்து(நோக்க_வரிகள், தேர்ந்த_அம்சங்கள், விளைவுகள்) — நோக்கம் தரும் பணிகளும் விலக்குகளும்
//
// __சரி({பணிகள், விலக்குகள்}). Each in-scope row becomes a to-do paNi.qmz task__
// __coded by its WBS code, with estimate = its base hours + every மணி_கூட்டு of a__
// __chosen feature on it; each chosen பணி_சேர் adds one more task, carrying__
// __அம்சக்_குறி so it can be traced to the feature that asked for it. Excluded rows__
// __come back as விலக்குகள். Impacts of features not in தேர்ந்த_அம்சங்கள் do__
// __nothing.__
//
// __தவறு when a chosen feature adds hours to a row that is not in scope — hours__
// __on work that is excluded or removed would vanish from the plan without a__
// __word, and the customer would be charged for a feature nobody builds. Also__
// __தவறு for a decision or an impact type that is not one of the words above: a__
// __misspelt "உள்ளது" would otherwise drop the row from both the tasks and the__
// __exclusions, and nobody would notice until the work was missed.__
செயல் நோக்கத்தைப்_பயன்படுத்து(நோக்க_வரிகள், தேர்ந்த_அம்சங்கள், விளைவுகள்) {
    ஒவ்வொரு வரி_ஒன்று இல் நோக்க_வரிகள் {
        முடிவு_சொல் = வரி_ஒன்று.நோக்க_முடிவு;
        (முடிவு_சொல் != "உள்ளே" மற்றும் முடிவு_சொல் != "விலக்கு" மற்றும் முடிவு_சொல் != "நீக்கு") எனில் {
            திரும்பு தவறு(வரி_ஒன்று.பகுப்புக்_குறி & " வரியின் முடிவு '" & முடிவு_சொல்
                           & "' உள்ளே, விலக்கு, நீக்கு இவற்றில் ஒன்றல்ல  (the decision on row "
                           & வரி_ஒன்று.பகுப்புக்_குறி & " is not உள்ளே, விலக்கு or நீக்கு)");
        }
    }
    ஒவ்வொரு விளைவு இல் விளைவுகள் {
        (விளைவு.விளைவு_வகை != "மணி_கூட்டு" மற்றும் விளைவு.விளைவு_வகை != "பணி_சேர்") எனில் {
            திரும்பு தவறு(விளைவு.அம்சக்_குறி & " அம்சத்தின் விளைவு வகை '" & விளைவு.விளைவு_வகை
                           & "' மணி_கூட்டு, பணி_சேர் இவற்றில் ஒன்றல்ல  (an impact of feature "
                           & விளைவு.அம்சக்_குறி & " is neither மணி_கூட்டு nor பணி_சேர்)");
        }
    }
    தேர்ந்தவை = {};
    ஒவ்வொரு அம்சம் இல் தேர்ந்த_அம்சங்கள் { தேர்ந்தவை[அம்சம்] = மெய்; }
    உள்ளவை = {};
    ஒவ்வொரு வரி_ஒன்று இல் நோக்க_வரிகள் {
        (வரி_ஒன்று.நோக்க_முடிவு == "உள்ளே") எனில் { உள்ளவை[வரி_ஒன்று.பகுப்புக்_குறி] = 0; }
    }

    சேர்ப்புகள் = [];
    ஒவ்வொரு விளைவு இல் விளைவுகள் {
        (புலம்_உள்ளதா(தேர்ந்தவை, விளைவு.அம்சக்_குறி)) எனில் {
            (விளைவு.விளைவு_வகை == "மணி_கூட்டு") எனில் {
                (இல்லை புலம்_உள்ளதா(உள்ளவை, விளைவு.பகுப்புக்_குறி)) எனில் {
                    திரும்பு தவறு(விளைவு.அம்சக்_குறி & " அம்சம் நோக்கத்தில் இல்லாத " & விளைவு.பகுப்புக்_குறி
                                   & " வரிக்கு மணி சேர்க்கிறது  (feature " & விளைவு.அம்சக்_குறி
                                   & " adds hours to " & விளைவு.பகுப்புக்_குறி & ", which is not in scope)");
                }
                உள்ளவை[விளைவு.பகுப்புக்_குறி] = உள்ளவை[விளைவு.பகுப்புக்_குறி] + விளைவு.கூடுதல்_மணி;
            }
            (விளைவு.விளைவு_வகை == "பணி_சேர்") எனில் { சேர்ப்புகள் = இணை(சேர்ப்புகள், விளைவு); }
        }
    }

    பணிகள் = [];
    விலக்குகள் = [];
    ஒவ்வொரு வரி_ஒன்று இல் நோக்க_வரிகள் {
        (வரி_ஒன்று.நோக்க_முடிவு == "உள்ளே") எனில் {
            புதியது = பணி_ஆக்கு(வரி_ஒன்று.பகுப்புக்_குறி, "", "செய்யவேண்டியது", 0,
                                வரி_ஒன்று.அடிப்படை_மணி + உள்ளவை[வரி_ஒன்று.பகுப்புக்_குறி], "");
            புதியது["விவரம்"] = வரி_ஒன்று.விவரம்;
            பணிகள் = இணை(பணிகள், புதியது);
        }
        (வரி_ஒன்று.நோக்க_முடிவு == "விலக்கு") எனில் { விலக்குகள் = இணை(விலக்குகள், வரி_ஒன்று); }
    }
    ஒவ்வொரு விளைவு இல் சேர்ப்புகள் {
        புதியது = பணி_ஆக்கு(விளைவு.பகுப்புக்_குறி, "", "செய்யவேண்டியது", 0, விளைவு.கூடுதல்_மணி, "");
        புதியது["விவரம்"] = விளைவு.விவரம்;
        புதியது["அம்சக்_குறி"] = விளைவு.அம்சக்_குறி;
        பணிகள் = இணை(பணிகள், புதியது);
    }
    திரும்பு சரி({ பணிகள்: பணிகள், விலக்குகள்: விலக்குகள் });
}

nUlakam/qittam/nalam.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/nalam.qmz — நலம் (project health: milestones and the RAG status)__
// திட்ட நலம்: மைல்கற்களும் நிறக் குறியும்
//
// __A portfolio screen shows one colour per project, and the colour is only__
// __useful if everyone derives it the same way. Typed by hand it drifts towards__
// __green; derived from the data it cannot. The rule here is the one a PMO uses:__
//
//   __மூடியது   the project is closed__
//   __சிவப்பு   a milestone is late, or the end date has passed with work left__
//   __மஞ்சள்   a milestone is at risk, a task is overdue, or progress trails__
//            __the calendar by more than பின்னடைவு_எல்லை() points__
//   __பச்சை    none of those__
//
// __The colour comes back with its reasons. A red square nobody can explain is__
// __argued about; a red square that says "M3 is late" is acted on.__
//
// __Milestone statuses are சரியாக (on track), இடரில் (at risk), தாமதம்__
// __(delayed) and எட்டியது (met), held in நடப்பு_நிலை like every other lifecycle.__

இறக்கு "../atippatY/kaNiqam.qmz";
இறக்கு "paNi.qmz";

// __மைல்கல்_ஆக்கு(மைல்கல்_குறி, அடிப்படை_நாள், முன்கணிப்பு_நாள், உண்மை_நாள், மைல்கல்_நிலை) — one milestone__
// மைல்கல்_ஆக்கு(மைல்கல்_குறி, அடிப்படை_நாள், முன்கணிப்பு_நாள், உண்மை_நாள், மைல்கல்_நிலை) — ஒரு மைல்கல்லை உருவாக்கும்
//
// __அடிப்படை_நாள் is the date promised at baseline and never moves. The forecast__
// __is today's best guess; the actual is "" until the milestone is met.__
செயல் மைல்கல்_ஆக்கு(மைல்கல்_குறி, அடிப்படை_நாள், முன்கணிப்பு_நாள், உண்மை_நாள், மைல்கல்_நிலை) {
    திரும்பு {
        மைல்கல்_குறி: மைல்கல்_குறி,
        அடிப்படை_நாள்: அடிப்படை_நாள்,
        முன்கணிப்பு_நாள்: முன்கணிப்பு_நாள்,
        உண்மை_நாள்: உண்மை_நாள்,
        நடப்பு_நிலை: மைல்கல்_நிலை
    };
}

// __மைல்கல்_வேறுபாடு(ஒரு_மைல்கல்) — days late (positive) or early (negative) against baseline__
// மைல்கல்_வேறுபாடு(ஒரு_மைல்கல்) — அடிப்படை நாளிலிருந்து தாமதமான நாட்கள்
//
// __Measured from the actual date once there is one, and from the forecast__
// __until then, so the figure is live while the milestone is open and frozen__
// __once it is met. Calendar days, not working days: a customer promised the__
// __first of the month counts the weekend too.__
செயல் மைல்கல்_வேறுபாடு(ஒரு_மைல்கல்) {
    ஒப்பிடும்_நாள் = ஒரு_மைல்கல்.முன்கணிப்பு_நாள்;
    (ஒரு_மைல்கல்.உண்மை_நாள் != "") எனில் { ஒப்பிடும்_நாள் = ஒரு_மைல்கல்.உண்மை_நாள்; }
    திரும்பு நாள்_வேறுபாடு(ஒரு_மைல்கல்.அடிப்படை_நாள், ஒப்பிடும்_நாள்);
}

// __கழிந்த_சதவீதம்(தொடக்க_நாள், முடிவு_நாள், இன்றைய_நாள்) — how much of the calendar has gone__
// கழிந்த_சதவீதம்(தொடக்க_நாள், முடிவு_நாள், இன்றைய_நாள்) — திட்டக் காலத்தில் கழிந்த பங்கு
//
// __A whole percentage held to 0–100: before the start it is 0, after the end__
// __100. A project whose end is not after its start has no span to divide, so it__
// __is 0 until the end date and 100 from it.__
செயல் கழிந்த_சதவீதம்(தொடக்க_நாள், முடிவு_நாள், இன்றைய_நாள்) {
    மொத்தம் = நாள்_வேறுபாடு(தொடக்க_நாள், முடிவு_நாள்);
    (மொத்தம் <= 0) எனில் {
        (இன்றைய_நாள் >= முடிவு_நாள்) எனில் { திரும்பு 100; }
        திரும்பு 0;
    }
    கழிந்தது = நாள்_வேறுபாடு(தொடக்க_நாள், இன்றைய_நாள்) * 100 / மொத்தம்;
    திரும்பு வட்டமிடு(பெரியது(0, சிறியது(100, கழிந்தது)), 0);
}

// __பின்னடைவு_எல்லை() — how far progress may trail the calendar before it is amber__
// பின்னடைவு_எல்லை() — மஞ்சள் ஆவதற்கு முன் அனுமதிக்கும் பின்னடைவு
//
// __Ten percentage points. Progress never tracks the calendar exactly — work is__
// __lumpy — and a threshold of zero would turn every project amber on the day__
// __after a big task starts.__
செயல் பின்னடைவு_எல்லை() { திரும்பு 10; }

// __திட்ட_நலம்(தொடக்க_நாள், முடிவு_நாள், மூடியதா, மைல்கற்கள், பணிகள், இன்றைய_நாள்) — the RAG status, with its reasons__
// திட்ட_நலம்(தொடக்க_நாள், முடிவு_நாள், மூடியதா, மைல்கற்கள், பணிகள், இன்றைய_நாள்) — திட்டத்தின் நிறக் குறியும் காரணங்களும்
//
// __Returns {நிறம், காரணங்கள், நிறைவு, கழிந்தது, நிலுவைப்_பணிகள்}. நிறைவு is the__
// __effort-weighted percentage over பணிகள், so pass the tasks the project__
// __reports on — usually the top-level ones. காரணங்கள் lists every condition__
// __that fired, red ones first, so an amber project with a red cause cannot__
// __happen and a red project shows all of what is wrong, not only the first.__
செயல் திட்ட_நலம்(தொடக்க_நாள், முடிவு_நாள், மூடியதா, மைல்கற்கள், பணிகள், இன்றைய_நாள்) {
    நிறைவு = எடையிட்ட_நிறைவு(பணிகள்);
    கழிந்தது = கழிந்த_சதவீதம்(தொடக்க_நாள், முடிவு_நாள், இன்றைய_நாள்);
    நிலுவை_எண்ணிக்கை = 0;
    ஒவ்வொரு ஒரு_பணி இல் பணிகள் {
        (பணி_நிலுவையா(ஒரு_பணி, இன்றைய_நாள்)) எனில் { நிலுவை_எண்ணிக்கை = நிலுவை_எண்ணிக்கை + 1; }
    }
    (மூடியதா) எனில் {
        திரும்பு { நிறம்: "மூடியது", காரணங்கள்: [], நிறைவு: நிறைவு,
                  கழிந்தது: கழிந்தது, நிலுவைப்_பணிகள்: நிலுவை_எண்ணிக்கை };
    }

    சிவப்புகள் = [];
    மஞ்சள்கள் = [];
    ஒவ்வொரு ஒரு_மைல்கல் இல் மைல்கற்கள் {
        (ஒரு_மைல்கல்.நடப்பு_நிலை == "தாமதம்") எனில் {
            சிவப்புகள் = இணை(சிவப்புகள், ஒரு_மைல்கல்.மைல்கல்_குறி & " மைல்கல் தாமதம்  (milestone delayed)");
        }
        (ஒரு_மைல்கல்.நடப்பு_நிலை == "இடரில்") எனில் {
            மஞ்சள்கள் = இணை(மஞ்சள்கள், ஒரு_மைல்கல்.மைல்கல்_குறி & " மைல்கல் இடரில்  (milestone at risk)");
        }
    }
    (முடிவு_நாள் < இன்றைய_நாள் மற்றும் நிறைவு < 100) எனில் {
        சிவப்புகள் = இணை(சிவப்புகள், "முடிவு நாள் கடந்தும் வேலை மீதியுள்ளது  (past the end date with work left)");
    }
    (நிலுவை_எண்ணிக்கை > 0) எனில் {
        மஞ்சள்கள் = இணை(மஞ்சள்கள், சொல்லாக்கு(நிலுவை_எண்ணிக்கை) & " பணிகள் காலம் கடந்தன  (tasks overdue)");
    }
    (நிறைவு < கழிந்தது - பின்னடைவு_எல்லை()) எனில் {
        மஞ்சள்கள் = இணை(மஞ்சள்கள், "நிறைவு " & சொல்லாக்கு(நிறைவு) & "%, காலம் "
                          & சொல்லாக்கு(கழிந்தது) & "%  (progress trails the calendar)");
    }

    நிறம் = "பச்சை";
    (நீளம்(மஞ்சள்கள்) > 0) எனில் { நிறம் = "மஞ்சள்"; }
    (நீளம்(சிவப்புகள்) > 0) எனில் { நிறம் = "சிவப்பு"; }
    காரணங்கள் = சிவப்புகள்;
    ஒவ்வொரு ஒன்று இல் மஞ்சள்கள் { காரணங்கள் = இணை(காரணங்கள், ஒன்று); }
    திரும்பு { நிறம்: நிறம், காரணங்கள்: காரணங்கள், நிறைவு: நிறைவு,
              கழிந்தது: கழிந்தது, நிலுவைப்_பணிகள்: நிலுவை_எண்ணிக்கை };
}

nUlakam/qittam/nilY_aRikkY.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/nilY_aRikkY.qmz — நிலை அறிக்கை (the weekly status report)__
// வார நிலை அறிக்கை: காலமும் வேட்பாளர்களும்
//
// __A status report has three lists — what was achieved, what is blocked, what__
// __comes next — and a project manager writing it from memory forgets half of__
// __each. The task data already knows all three. This file proposes them; the__
// __manager edits the proposal, which is a much smaller job than writing it.__
//
// __The period runs from the day after the previous report to today, so__
// __consecutive reports tile the calendar with no gap and no overlap. The first__
// __report covers the seven days ending today.__
//
// __Tasks are paNi.qmz records. The two optional fields used here are__
// __முடிந்த_நாள் (the actual finish) and தொடக்க_நாள் (the planned start).__

இறக்கு "paNi.qmz";

// __அடுத்தவைக்_காலம்() — how far ahead "next steps" looks, in days__
// அடுத்தவைக்_காலம்() — அடுத்த படிகளுக்குப் பார்க்கும் நாட்கள்
செயல் அடுத்தவைக்_காலம்() { திரும்பு 14; }

// __அறிக்கைக்_காலம்(முந்தைய_அறிக்கை_நாள், இன்றைய_நாள்) — the period this report covers__
// அறிக்கைக்_காலம்(முந்தைய_அறிக்கை_நாள், இன்றைய_நாள்) — இவ்வறிக்கை உள்ளடக்கும் காலம்
//
// __{தொடக்கம், முடிவு}, both inclusive. Pass "" as the previous date for the__
// __first report.__
செயல் அறிக்கைக்_காலம்(முந்தைய_அறிக்கை_நாள், இன்றைய_நாள்) {
    (முந்தைய_அறிக்கை_நாள் == "") எனில் {
        திரும்பு { தொடக்கம்: நாள்_கூட்டு(இன்றைய_நாள், 0 - 6), முடிவு: இன்றைய_நாள் };
    }
    திரும்பு { தொடக்கம்: நாள்_கூட்டு(முந்தைய_அறிக்கை_நாள், 1), முடிவு: இன்றைய_நாள் };
}

// __அறிக்கை_வேட்பாளர்கள்(பணிகள், காலம், இன்றைய_நாள்) — the proposed achievements, blockers and next steps__
// அறிக்கை_வேட்பாளர்கள்(பணிகள், காலம், இன்றைய_நாள்) — சாதனைகள், தடைகள், அடுத்த படிகள்
//
// __{சாதனைகள், தடைகள், அடுத்தவை}, each a list of tasks:__
//
//   __சாதனைகள்  done, with முடிந்த_நாள் inside the period__
//   __தடைகள்    in progress and past the due date__
//   __அடுத்தவை  not done, not cancelled, and either in progress already or__
//             __planned to start within அடுத்தவைக்_காலம்() days__
//
// __A task can be both a blocker and a next step, and is listed in both: it is__
// __late, and it is also what the team is doing next. Hiding it from one list to__
// __keep them disjoint would understate one or the other.__
செயல் அறிக்கை_வேட்பாளர்கள்(பணிகள், காலம், இன்றைய_நாள்) {
    எல்லை_நாள் = நாள்_கூட்டு(இன்றைய_நாள், அடுத்தவைக்_காலம்());
    சாதனைகள் = [];
    தடைகள் = [];
    அடுத்தவை = [];
    ஒவ்வொரு ஒரு_பணி இல் பணிகள் {
        பணி_நிலை = ஒரு_பணி.நடப்பு_நிலை;
        முடிந்த_நாள் = புலம்_அல்லது(ஒரு_பணி, "முடிந்த_நாள்", "");
        தொடக்க_நாள் = புலம்_அல்லது(ஒரு_பணி, "தொடக்க_நாள்", "");
        (பணி_முடிந்ததா(பணி_நிலை) மற்றும் முடிந்த_நாள் >= காலம்.தொடக்கம்
            மற்றும் முடிந்த_நாள் <= காலம்.முடிவு மற்றும் முடிந்த_நாள் != "") எனில் {
            சாதனைகள் = இணை(சாதனைகள், ஒரு_பணி);
        }
        (பணி_நிலை == "நடப்பில்" மற்றும் பணி_நிலுவையா(ஒரு_பணி, இன்றைய_நாள்)) எனில் {
            தடைகள் = இணை(தடைகள், ஒரு_பணி);
        }
        திறந்தது = (இல்லை பணி_முடிந்ததா(பணி_நிலை)) மற்றும் பணி_நிலை != "கைவிட்டது";
        விரைவில் = தொடக்க_நாள் != "" மற்றும் தொடக்க_நாள் <= எல்லை_நாள்;
        (திறந்தது மற்றும் (பணி_நிலை == "நடப்பில்" அல்லது விரைவில்)) எனில் {
            அடுத்தவை = இணை(அடுத்தவை, ஒரு_பணி);
        }
    }
    திரும்பு { சாதனைகள்: சாதனைகள், தடைகள்: தடைகள், அடுத்தவை: அடுத்தவை };
}

nUlakam/qittam/nilYmARRam.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/nilYmARRam.qmz — நிலை மாற்றம் (a state machine as data)__
// நிலை மாற்ற வரைவு
//
// __Every register a project keeps has a lifecycle: a change request is__
// __requested, reviewed, acknowledged and approved; a product request is__
// __captured, classified and sent to council; an outbox row is pending, sent or__
// __dead. Written by hand, each one is a ladder of if-statements that checks the__
// __current state, checks the new one, stamps who did it and appends an audit__
// __row, and each ladder gets one of those four steps subtly wrong.__
//
// __Here the lifecycle is data. A வரைவு (the machine) is a list of rows, each__
// __naming a state and the states it may move to, plus an optional record from__
// __state to the field that remembers who moved it there. One function then does__
// __the four steps for every lifecycle at once, and the list of allowed next__
// __states is the same data the screen uses to decide which buttons to draw.__
//
// __A state with no outgoing row, or with an empty one, is terminal. Moving into__
// __a terminal state also stamps முடிவு_நாள், because "when was this decided" is__
// __the question every register is asked and it should not need its own column__
// __logic per lifecycle.__
//
// __The record being moved keeps its state in நடப்பு_நிலை. The name is fixed so__
// __that the machine can read any record without being told where to look.__

// __நிலை_மாற்றம்_ஆக்கு(இருந்து, செல்லக்கூடியவை) — one row of a machine__
// நிலை_மாற்றம்_ஆக்கு(இருந்து, செல்லக்கூடியவை) — ஒரு நிலையும் அது செல்லக்கூடிய நிலைகளும்
//
// __An empty செல்லக்கூடியவை makes the state terminal and says so explicitly,__
// __which reads better than leaving the state out and relying on its absence.__
செயல் நிலை_மாற்றம்_ஆக்கு(இருந்து, செல்லக்கூடியவை) {
    திரும்பு { இருந்து: இருந்து, செல்லக்கூடியவை: செல்லக்கூடியவை };
}

// __நிலை_வரைவு_ஆக்கு(மாற்றங்கள், செய்தவர்_புலங்கள்) — a whole machine__
// நிலை_வரைவு_ஆக்கு(மாற்றங்கள், செய்தவர்_புலங்கள்) — முழு நிலை வரைவை உருவாக்கும்
//
// __செய்தவர்_புலங்கள் maps a state to the field that records who moved the__
// __record into it — {"மதிப்பாய்ந்தது": "மதிப்பாய்ந்தவர்"}. Pass {} when no state__
// __needs an actor stamp; the audit event still names the actor either way.__
செயல் நிலை_வரைவு_ஆக்கு(மாற்றங்கள், செய்தவர்_புலங்கள்) {
    திரும்பு { மாற்றங்கள்: மாற்றங்கள், செய்தவர்_புலங்கள்: செய்தவர்_புலங்கள் };
}

// __அடுத்த_நிலைகள்(வரைவு, இப்போதைய_நிலை) — where this state may go next__
// அடுத்த_நிலைகள்(வரைவு, இப்போதைய_நிலை) — இந்நிலையிலிருந்து செல்லக்கூடியவை
//
// __An unknown state has no next states rather than being an error. The screen__
// __that asks is drawing buttons, and no buttons is the right drawing for a__
// __record whose state the machine does not recognise.__
செயல் அடுத்த_நிலைகள்(வரைவு, இப்போதைய_நிலை) {
    ஒவ்வொரு ஒரு_மாற்றம் இல் வரைவு.மாற்றங்கள் {
        (ஒரு_மாற்றம்.இருந்து == இப்போதைய_நிலை) எனில் {
            திரும்பு ஒரு_மாற்றம்.செல்லக்கூடியவை;
        }
    }
    திரும்பு [];
}

// __மாற்றம்_அனுமதியா(வரைவு, இருந்து, புதிய_நிலை) — is this one move allowed?__
// மாற்றம்_அனுமதியா(வரைவு, இருந்து, புதிய_நிலை) — இந்த மாற்றம் அனுமதிக்கப்பட்டதா
செயல் மாற்றம்_அனுமதியா(வரைவு, இருந்து, புதிய_நிலை) {
    ஒவ்வொரு அடுத்தது இல் அடுத்த_நிலைகள்(வரைவு, இருந்து) {
        (அடுத்தது == புதிய_நிலை) எனில் { திரும்பு மெய்; }
    }
    திரும்பு பொய்;
}

// __இறுதி_நிலையா(வரைவு, ஒரு_நிலை) — has this state nowhere left to go?__
// இறுதி_நிலையா(வரைவு, ஒரு_நிலை) — இது இறுதி நிலையா
செயல் இறுதி_நிலையா(வரைவு, ஒரு_நிலை) {
    திரும்பு நீளம்(அடுத்த_நிலைகள்(வரைவு, ஒரு_நிலை)) == 0;
}

// __நிலையை_நகர்த்து(ஒரு_பதிவு, வரைவு, புதிய_நிலை, செய்தவர், நாள்) — make one move__
// நிலையை_நகர்த்து(ஒரு_பதிவு, வரைவு, புதிய_நிலை, செய்தவர், நாள்) — ஒரு நிலை மாற்றத்தைச் செய்யும்
//
// __சரி with {புதிய_பதிவு, நிகழ்வு}: the record in its new state, and the audit event__
// __{இருந்து, சென்றது, செய்தவர், நாள்} for the caller to append to its log. The__
// __record is returned rather than changed, like everything else in nUlakam, so__
// __a refused move leaves the caller holding exactly what it had.__
//
// __Refused with தவறு naming both states, because "not allowed" alone does not__
// __tell the person at the screen whether they or the record is in the wrong__
// __place.__
செயல் நிலையை_நகர்த்து(ஒரு_பதிவு, வரைவு, புதிய_நிலை, செய்தவர், நாள்) {
    இருந்து = ஒரு_பதிவு.நடப்பு_நிலை;
    (இல்லை மாற்றம்_அனுமதியா(வரைவு, இருந்து, புதிய_நிலை)) எனில் {
        திரும்பு தவறு(இருந்து & " நிலையிலிருந்து " & புதிய_நிலை
                       & " நிலைக்குச் செல்ல முடியாது  (cannot move from "
                       & இருந்து & " to " & புதிய_நிலை & ")");
    }
    புதிய_பதிவு = ஒரு_பதிவு;
    புதிய_பதிவு["நடப்பு_நிலை"] = புதிய_நிலை;
    (புலம்_உள்ளதா(வரைவு.செய்தவர்_புலங்கள், புதிய_நிலை)) எனில் {
        புதிய_பதிவு[வரைவு.செய்தவர்_புலங்கள்[புதிய_நிலை]] = செய்தவர்;
    }
    (இறுதி_நிலையா(வரைவு, புதிய_நிலை)) எனில் {
        புதிய_பதிவு["முடிவு_நாள்"] = நாள்;
    }
    திரும்பு சரி({
        புதிய_பதிவு: புதிய_பதிவு,
        நிகழ்வு: { இருந்து: இருந்து, சென்றது: புதிய_நிலை,
                   செய்தவர்: செய்தவர், நாள்: நாள் }
    });
}

nUlakam/qittam/nilavaram.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/nilavaram.qmz — நிலவரம்: the whole picture, as a report block__
// நிலவரம்: முழு நிலவரமும், அறிக்கையாக
//
// __One record carrying every figure above, and a printer for it. Separated__
// __so that the arithmetic can be used without the formatting.__

இறக்கு "Ittu_vERupAtu.qmz";
இறக்கு "muZZurYppu.qmz";

// நிலவரம்(திட்டமிட்டது, ஈட்டியது, உண்மைச்_செலவு, மொத்த_நிதி)
//
// __Everything a steering committee needs from one reading, computed rather than__
// __stored — nothing here is a field that could drift from its inputs.__
// நிலவரம்(திட்டமிட்டது, ஈட்டியது, உண்மைச்_செலவு, மொத்த_நிதி) — ஈட்டு மதிப்பின் முழு நிலவரம்
செயல் நிலவரம்(திட்டமிட்டது, ஈட்டியது, உண்மைச்_செலவு, மொத்த_நிதி) {
    செலவுத்_திறன் = செலவுச்_செயல்திறன்(ஈட்டியது, உண்மைச்_செலவு);
    காலத்_திறன் = காலச்_செயல்திறன்(ஈட்டியது, திட்டமிட்டது);
    (தவறா(செலவுத்_திறன்)) எனில் { திரும்பு செலவுத்_திறன்; }
    (தவறா(காலத்_திறன்)) எனில் { திரும்பு காலத்_திறன்; }

    மதிப்பீட்டு_விடை = முடிவில்_மதிப்பீடு_திறனால்(மொத்த_நிதி, மதிப்பு(செலவுத்_திறன்));
    (தவறா(மதிப்பீட்டு_விடை)) எனில் { திரும்பு மதிப்பீட்டு_விடை; }

    திரும்பு சரி({
        திட்டமிட்டது: திட்டமிட்டது,
        ஈட்டியது: ஈட்டியது,
        உண்மைச்_செலவு: உண்மைச்_செலவு,
        செலவு_வேறுபாடு: செலவு_வேறுபாடு(ஈட்டியது, உண்மைச்_செலவு),
        கால_வேறுபாடு: கால_வேறுபாடு(ஈட்டியது, திட்டமிட்டது),
        செலவுத்_திறன்: மதிப்பு(செலவுத்_திறன்),
        காலத்_திறன்: மதிப்பு(காலத்_திறன்),
        முடிவில்_மதிப்பீடு: மதிப்பு(மதிப்பீட்டு_விடை),
        முடிவில்_வேறுபாடு: முடிவில்_வேறுபாடு(மொத்த_நிதி, மதிப்பு(மதிப்பீட்டு_விடை)),
        முடிக்க_மீதி: முடிக்க_மீதி(மதிப்பு(மதிப்பீட்டு_விடை), உண்மைச்_செலவு)
    });
}

// __நிலவரத்தை_அச்சிடு(நிலவரப்_பதிவு) — print a status record as a report block__
// நிலவரத்தை_அச்சிடு(நிலவரப்_பதிவு) — நிலவரப் பதிவை அறிக்கையாக அச்சிடும்
//
// __Prints the English acronyms beside the Tamil names, because PV, EV, AC, CV, SV, CPI and SPI are what the literature and the audience use. The schedule variance line says in money, not in time, on the line itself — the one place that warning is certain to be read.__
செயல் நிலவரத்தை_அச்சிடு(நிலவரப்_பதிவு) {
    அச்சு "── ஈட்டு மதிப்பு நிலவரம் (earned value status) ──";
    அச்சு "  திட்டமிட்டது  (PV)  : " & நிலவரப்_பதிவு.திட்டமிட்டது;
    அச்சு "  ஈட்டியது      (EV)  : " & நிலவரப்_பதிவு.ஈட்டியது;
    அச்சு "  உண்மைச் செலவு (AC)  : " & நிலவரப்_பதிவு.உண்மைச்_செலவு;
    அச்சு "  செலவு வேறுபாடு (CV) : " & நிலவரப்_பதிவு.செலவு_வேறுபாடு;
    அச்சு "  கால வேறுபாடு   (SV) : " & நிலவரப்_பதிவு.கால_வேறுபாடு & "  (பணத்தில், நேரத்தில் அல்ல)";
    அச்சு "  செலவுத் திறன்  (CPI): " & நிலவரப்_பதிவு.செலவுத்_திறன்;
    அச்சு "  காலத் திறன்    (SPI): " & நிலவரப்_பதிவு.காலத்_திறன்;
    அச்சு "  முடிவில் மதிப்பீட்டு_விடை  : " & நிலவரப்_பதிவு.முடிவில்_மதிப்பீடு;
    அச்சு "  முடிவில் வேறுபாடு   : " & நிலவரப்_பதிவு.முடிவில்_வேறுபாடு;
    திரும்பு நிலவரப்_பதிவு;
}

nUlakam/qittam/oppanqa_vakY.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/oppanqa_vakY.qmz — ஒப்பந்த வகை, and who carries the cost risk__
// ஒப்பந்த வகையும், செலவு இடரை யார் சுமப்பது என்பதும்
//
// __Everything else in this directory costs a project as though the money simply__
// __arrives. What arrives depends on the **shape of the contract**, and the__
// __shapes differ in one respect that decides everything else: who is worse off__
// __when the work costs more than expected.__
//
//   __**Firm fixed price** — the seller. Every rupee of overrun comes out of the__
//     __seller's fee, and past a point out of the seller's own pocket.__
//   __**Fixed price incentive fee** — the seller, but shared up to a ceiling,__
//     __and then wholly the seller's again. The point where that switch happens__
//     __is the point of total assumption, and it is the most useful number in__
//     __this file.__
//   __**Cost plus** — the buyer. The seller recovers cost whatever it is, so the__
//     __seller's risk is to its fee and not to its capital.__
//   __**Time and materials** — the buyer, unless a not-to-exceed ceiling is__
//     __written in, which quietly turns it into a fixed price at the top end.__
//
// __A cost overrun is the same event in all four and the money moves in__
// __different directions. A project manager who does not know which contract__
// __they are on does not know what an overrun costs them, and the commonest__
// __version of that confusion is treating a not-to-exceed time-and-materials__
// __contract as though the ceiling were a target.__

இறக்கு "../atippatY/kaNiqam.qmz";
இறக்கு "../atippatY/poruL.qmz";

// =========================================================================
// __வகைகள் — who carries the risk__
// =========================================================================
//
// விற்பவர்_இடர்(ஒப்பந்த_வகை)
//
// __How much of a cost overrun falls on the seller, as a word. It is the one__
// __question that distinguishes the types, and a table of it is more use than__
// __the names.__
//
// __"முழு" — the seller absorbs all of it.__
// __"பகிர்வு" — shared to a ceiling, then all the seller's.__
// __"கட்டணம்_மட்டும்" — the seller's fee is at risk, the cost is not.__
// __"இல்லை" — the seller recovers whatever it spends.__
// விற்பவர்_இடர்(ஒப்பந்த_வகை) — இவ்வகை ஒப்பந்தத்தில் விற்பவர் சுமக்கும் இடர்
செயல் விற்பவர்_இடர்(ஒப்பந்த_வகை) {
    (ஒப்பந்த_வகை == "உறுதி_நிலை_விலை") எனில் { திரும்பு "முழு"; }
    (ஒப்பந்த_வகை == "நிலை_விலை_ஊக்கம்") எனில் { திரும்பு "பகிர்வு"; }
    (ஒப்பந்த_வகை == "செலவுடன்_ஊக்கம்") எனில் { திரும்பு "கட்டணம்_மட்டும்"; }
    (ஒப்பந்த_வகை == "செலவுடன்_நிலைக்_கட்டணம்") எனில் { திரும்பு "இல்லை"; }
    (ஒப்பந்த_வகை == "நேரமும்_பொருளும்") எனில் { திரும்பு "இல்லை"; }
    திரும்பு "";
}

// =========================================================================
// __உறுதி நிலை விலை — firm fixed price__
// =========================================================================
//
// உறுதி_நிலை_லாபம்(ஒப்பந்த_மதிப்பு, உண்மைச்_செலவு)
//
// __The price is the price. Every rupee saved is the seller's and every rupee__
// __overspent is the seller's, and the answer goes negative without comment__
// __because that is exactly what happens.__
//
// __The buyer's cost is known on the day of signature, which is what the type is__
// __for, and is paid for in the margin the seller prices in for bearing the__
// __whole risk. A buyer who believes a fixed price contains no contingency has__
// __not thought about who else would carry it.__
// உறுதி_நிலை_லாபம்(ஒப்பந்த_மதிப்பு, உண்மைச்_செலவு) — உறுதி விலை ஒப்பந்தத்தில் லாபம்
செயல் உறுதி_நிலை_லாபம்(ஒப்பந்த_மதிப்பு, உண்மைச்_செலவு) {
    திரும்பு வட்டக்_கழி(ஒப்பந்த_மதிப்பு, உண்மைச்_செலவு);
}

// =========================================================================
// __ஊக்கக் கட்டணம் — the incentive__
// =========================================================================
//
// ஊக்கக்_கட்டணம்(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உண்மைச்_செலவு,
//                 விற்பவர்_பகிர்வு)
//
// __The fee moves against the cost: an underrun raises it, an overrun lowers it,__
// __in the agreed proportion.__
//
//     __fee = target fee + (target cost − actual cost) × seller's share__
//
// __விற்பவர்_பகிர்வு is the seller's share as a fraction — 0.4 for a 60/40__
// __arrangement, where the buyer takes 60. It is a fraction and not a percentage__
// __because the two halves must sum to one, and that is easier to see and to__
// __check in this form.__
//
// __The sign works itself out. An underrun makes the bracket positive and the__
// __fee rises; an overrun makes it negative and the fee falls, which is the__
// __whole mechanism.__
// ஊக்கக்_கட்டணம்(இலக்குச்_செலவு, உண்மைச்_செலவு, இலக்குக்_கட்டணம், பகிர்வு_விகிதம்) — சேமிப்பையோ மிகையையோ பகிர்ந்த பின் கட்டணம்
செயல் ஊக்கக்_கட்டணம்(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உண்மைச்_செலவு,
                      விற்பவர்_பகிர்வு) {
    திரும்பு வட்டமிடு(இலக்குக்_கட்டணம்
                       + (இலக்குச்_செலவு - உண்மைச்_செலவு) * விற்பவர்_பகிர்வு, 2);
}

// கட்டணத்தை_வரம்பிடு(கட்டணத்_தொகை, குறைந்த_கட்டணம், உச்சக்_கட்டணம்)
//
// __Cost-plus-incentive-fee arrangements bound the fee at both ends: the seller__
// __cannot lose its whole fee however badly the work goes, and cannot earn__
// __without limit however well.__
//
// __Pass 0 as the maximum for no upper bound. The minimum is taken as given,__
// __including zero — a floor of zero is a real term and means the fee can be__
// __wiped out but not go negative.__
// கட்டணத்தை_வரம்பிடு(கட்டணத்_தொகை, குறைந்த_கட்டணம், உச்சக்_கட்டணம்) — கட்டணத்தை இரு எல்லைகளுக்குள் வைக்கும்
செயல் கட்டணத்தை_வரம்பிடு(கட்டணத்_தொகை, குறைந்த_கட்டணம், உச்சக்_கட்டணம்) {
    விடை = கட்டணத்_தொகை;
    (விடை < குறைந்த_கட்டணம்) எனில் { விடை = குறைந்த_கட்டணம்; }
    (உச்சக்_கட்டணம் > 0 மற்றும் விடை > உச்சக்_கட்டணம்) எனில் {
        விடை = உச்சக்_கட்டணம்;
    }
    திரும்பு வட்டமிடு(விடை, 2);
}

// =========================================================================
// __முழுப் பொறுப்புப் புள்ளி — the point of total assumption__
// =========================================================================
//
// முழுப்_பொறுப்புப்_புள்ளி(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உச்ச_விலை,
//                           வாங்குபவர்_பகிர்வு)
//
// __On a fixed price incentive contract the buyer shares an overrun **only until__
// __the price reaches the ceiling**. Past that the buyer pays no more, so every__
// __further rupee of cost is the seller's alone.__
//
//     __PTA = target cost + (ceiling price − target price) ÷ buyer's share__
//
// __where target price is target cost plus target fee.__
//
// __It is the most important number in such a contract and it appears in none of__
// __its schedules. Below it an overrun costs the seller its share; above it an__
// __overrun costs the seller everything, and the seller's marginal loss rate__
// __jumps — in the tests — from 25 paise in the rupee to 100. A seller tracking__
// __cost against the target, which is the natural thing to do, sees nothing__
// __happen at the point where its exposure quadruples.__
//
// __A buyer share of nothing is a தவறு rather than an infinity: with no sharing__
// __there is no incentive arrangement and the contract is a fixed price one,__
// __which has no such point.__
// முழுப்_பொறுப்புப்_புள்ளி(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உச்ச_விலை, பகிர்வு_விகிதம்) — இதற்கு மேல் மிகையை விற்பவரே முழுவதும் சுமப்பார்
செயல் முழுப்_பொறுப்புப்_புள்ளி(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உச்ச_விலை,
                                வாங்குபவர்_பகிர்வு) {
    (வாங்குபவர்_பகிர்வு <= 0) எனில் {
        திரும்பு தவறு("வாங்குபவர் பகிர்வு இல்லை  "
                       & "(with no buyer share there is no incentive "
                       & "arrangement and no point of total assumption)");
    }
    இலக்கு_விலை = இலக்குச்_செலவு + இலக்குக்_கட்டணம்;
    (உச்ச_விலை < இலக்கு_விலை) எனில் {
        திரும்பு தவறு("உச்ச விலை இலக்கு விலைக்குக் கீழே உள்ளது  "
                       & "(the ceiling price is below the target price, so the "
                       & "seller is past total assumption before it starts)");
    }
    திரும்பு சரி(வட்டமிடு(இலக்குச்_செலவு
                           + (உச்ச_விலை - இலக்கு_விலை) / வாங்குபவர்_பகிர்வு, 2));
}

// புள்ளியைத்_தாண்டியதா(உண்மைச்_செலவு, புள்ளி)
// __புள்ளியைத்_தாண்டியதா(உண்மைச்_செலவு, புள்ளி) — has cost passed the point of total assumption?__
// புள்ளியைத்_தாண்டியதா(உண்மைச்_செலவு, புள்ளி) — செலவு முழுப் பொறுப்புப் புள்ளியைத் தாண்டிவிட்டதா
//
// __Beyond it the contractor bears every further rupee, so the incentive stops working: there is nothing left to share and the only remaining question is who absorbs the overrun. The point where a cost-plus-incentive contract turns into a fixed price in all but name.__
செயல் புள்ளியைத்_தாண்டியதா(உண்மைச்_செலவு, புள்ளி) {
    திரும்பு உண்மைச்_செலவு > புள்ளி;
}

// நிலை_விலை_ஊக்கம்(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உச்ச_விலை,
//                   விற்பவர்_பகிர்வு, உண்மைச்_செலவு)
//
// __The whole settlement for a fixed price incentive contract: the fee, the__
// __final price, and whether the ceiling bit.__
//
// __The ceiling applies to the **price**, not to the fee. Once it bites, the fee__
// __is whatever is left of the ceiling after the cost — which is why it can go__
// __negative, and why a seller far past the point of total assumption is paying__
// __to finish the work. Capping the fee at zero instead would hide that, and a__
// __contract that can produce it should say so.__
// நிலை_விலை_ஊக்கம்(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உச்ச_விலை, பகிர்வு_விகிதம், உண்மைச்_செலவு) — நிலை விலை ஊக்க ஒப்பந்தத்தின் முடிவு
செயல் நிலை_விலை_ஊக்கம்(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உச்ச_விலை,
                        விற்பவர்_பகிர்வு, உண்மைச்_செலவு) {
    கச்சாக்_கட்டணம் = ஊக்கக்_கட்டணம்(இலக்குச்_செலவு, இலக்குக்_கட்டணம்,
                                      உண்மைச்_செலவு, விற்பவர்_பகிர்வு);
    கச்சா_விலை = உண்மைச்_செலவு + கச்சாக்_கட்டணம்;

    உச்சம்_தொட்டதா = கச்சா_விலை > உச்ச_விலை;
    இறுதி_விலை = கச்சா_விலை;
    (உச்சம்_தொட்டதா) எனில் { இறுதி_விலை = உச்ச_விலை; }

    திரும்பு {"கட்டணம்": வட்டமிடு(இறுதி_விலை - உண்மைச்_செலவு, 2),
              "கட்டணம்_வரம்பின்றி": கச்சாக்_கட்டணம்,
              "இறுதி_விலை": வட்டமிடு(இறுதி_விலை, 2),
              "உச்சம்_தொட்டதா": உச்சம்_தொட்டதா,
              "விற்பவர்_லாபம்": வட்டமிடு(இறுதி_விலை - உண்மைச்_செலவு, 2)};
}

// =========================================================================
// __செலவுக் கூடு — cost plus__
// =========================================================================
//
// செலவுடன்_நிலைக்_கட்டணம்(உண்மைச்_செலவு, நிலையான_கட்டணம்)
//
// __The fee is fixed in rupees at the outset and does not move with the cost.__
// __The seller therefore has **no financial reason to control cost at all** —__
// __which is not a criticism of the type but the reason it exists: it is for__
// __work whose scope cannot be defined well enough to price, and the control has__
// __to come from somewhere other than the contract.__
//
// __The fee not moving is the point. A fee fixed as a *percentage* of cost would__
// __rise with the overrun, which is why that arrangement is prohibited in public__
// __procurement almost everywhere.__
// செலவுடன்_நிலைக்_கட்டணம்(உண்மைச்_செலவு, நிலையான_கட்டணம்) — செலவுடன் நிலையான கட்டணம்
செயல் செலவுடன்_நிலைக்_கட்டணம்(உண்மைச்_செலவு, நிலையான_கட்டணம்) {
    திரும்பு {"விற்பவர்_கட்டணம்": வட்டமிடு(நிலையான_கட்டணம், 2),
              "வாங்குபவர்_செலவு": வட்டமிடு(உண்மைச்_செலவு + நிலையான_கட்டணம், 2)};
}

// செலவுடன்_ஊக்கம்(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உண்மைச்_செலவு,
//                  விற்பவர்_பகிர்வு, குறைந்த_கட்டணம், உச்சக்_கட்டணம்)
//
// __Cost plus incentive fee: the same sharing formula, bounded at both ends, and__
// __with the cost itself reimbursed whatever it turns out to be.__
//
// __There is no ceiling price and therefore no point of total assumption. The__
// __seller's exposure is bounded by the fee floor, which is the structural__
// __difference from the fixed price incentive form and the reason a buyer pays__
// __more for this one.__
// செலவுடன்_ஊக்கம்(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உண்மைச்_செலவு, பகிர்வு_விகிதம்) — செலவுடன் ஊக்கக் கட்டணம்
செயல் செலவுடன்_ஊக்கம்(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உண்மைச்_செலவு,
                       விற்பவர்_பகிர்வு, குறைந்த_கட்டணம், உச்சக்_கட்டணம்) {
    கச்சாக்_கட்டணம் = ஊக்கக்_கட்டணம்(இலக்குச்_செலவு, இலக்குக்_கட்டணம்,
                                      உண்மைச்_செலவு, விற்பவர்_பகிர்வு);
    கட்டணத்_தொகை = கட்டணத்தை_வரம்பிடு(கச்சாக்_கட்டணம், குறைந்த_கட்டணம்,
                                  உச்சக்_கட்டணம்);
    திரும்பு {"விற்பவர்_கட்டணம்": கட்டணத்_தொகை,
              "கட்டணம்_வரம்பின்றி": கச்சாக்_கட்டணம்,
              "வாங்குபவர்_செலவு": வட்டமிடு(உண்மைச்_செலவு + கட்டணத்_தொகை, 2)};
}

// =========================================================================
// __நேரமும் பொருளும் — time and materials__
// =========================================================================
//
// நேரமும்_பொருளும்(மணிகள், மணி_விகிதம், பொருள்_செலவு, மீற_இயலா_எல்லை)
//
// __Hours at a rate, plus materials. The rate already contains the seller's__
// __profit, so there is no separate fee.__
//
// __மீற_இயலா_எல்லை is a not-to-exceed ceiling; pass 0 for none. **A ceiling__
// __turns the top of the contract into a fixed price**, and that is the term__
// __most often misread: the buyer treats it as a budget and the seller treats it__
// __as an estimate, and both are wrong. Past the ceiling the seller works for__
// __nothing, exactly as under a firm fixed price, and the switch is invisible__
// __until it happens.__
//
// __The record says whether the ceiling bit and how many hours went unpaid,__
// __because that is the number a dispute is actually about.__
// நேரமும்_பொருளும்(மணிகள், மணி_விகிதம், பொருள்_செலவு) — நேரமும் பொருளும் அடிப்படையிலான ஒப்பந்தம்
செயல் நேரமும்_பொருளும்(மணிகள், மணி_விகிதம், பொருள்_செலவு, மீற_இயலா_எல்லை) {
    ஈட்டியது = வட்டமிடு(மணிகள் * மணி_விகிதம் + பொருள்_செலவு, 2);

    (மீற_இயலா_எல்லை <= 0 அல்லது ஈட்டியது <= மீற_இயலா_எல்லை) எனில் {
        திரும்பு {"வசூலிப்பது": ஈட்டியது,
                  "ஈட்டியது": ஈட்டியது,
                  "எல்லை_தொட்டதா": பொய்,
                  "வசூலிக்க_இயலாதது": 0};
    }

    திரும்பு {"வசூலிப்பது": வட்டமிடு(மீற_இயலா_எல்லை, 2),
              "ஈட்டியது": ஈட்டியது,
              "எல்லை_தொட்டதா": மெய்,
              "வசூலிக்க_இயலாதது": வட்டமிடு(ஈட்டியது - மீற_இயலா_எல்லை, 2)};
}

// =========================================================================
// __ஒப்பீடு — the same overrun, four ways__
// =========================================================================
//
// மிகைச்_செலவின்_விளைவு(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உச்ச_விலை,
//                        விற்பவர்_பகிர்வு, உண்மைச்_செலவு)
//
// __What one overrun does to the seller's profit under each type, side by side.__
//
// __The point is how differently the same event lands. The seller's profit is__
// __identical at target cost under all of them and diverges immediately, and a__
// __project manager reporting a cost variance without saying which contract it__
// __arises under has reported half a fact.__
// மிகைச்_செலவின்_விளைவு(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உச்ச_விலை, பகிர்வு_விகிதம், மிகைச்_செலவு) — மிகைச் செலவு யாரைப் பாதிக்கிறது என்பதைக் காட்டும்
செயல் மிகைச்_செலவின்_விளைவு(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உச்ச_விலை,
                             விற்பவர்_பகிர்வு, உண்மைச்_செலவு) {
    இலக்கு_விலை = இலக்குச்_செலவு + இலக்குக்_கட்டணம்;
    ஊக்கம் = நிலை_விலை_ஊக்கம்(இலக்குச்_செலவு, இலக்குக்_கட்டணம், உச்ச_விலை,
                               விற்பவர்_பகிர்வு, உண்மைச்_செலவு);
    செலவுக்கூடு = செலவுடன்_நிலைக்_கட்டணம்(உண்மைச்_செலவு, இலக்குக்_கட்டணம்);

    திரும்பு {"உறுதி_நிலை_விலை": உறுதி_நிலை_லாபம்(இலக்கு_விலை, உண்மைச்_செலவு),
              "நிலை_விலை_ஊக்கம்": ஊக்கம்["விற்பவர்_லாபம்"],
              "செலவுடன்_நிலைக்_கட்டணம்": செலவுக்கூடு["விற்பவர்_கட்டணம்"],
              "உண்மைச்_செலவு": வட்டமிடு(உண்மைச்_செலவு, 2)};
}

