// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/pAqY.qmz — கடுமையான பாதை (the critical path method)__
// கடுமையான பாதை முறை
//
// __The WBS says what must be produced. The network says in what order, and from__
// __that one fact everything schedulers care about falls out: the earliest each__
// __activity can happen, the latest it can happen without delaying the project,__
// __how much slack that leaves, and which chain has none.__
//
// __Two passes over a directed acyclic graph:__
//
//   __forward   ES = max(EF of predecessors)        EF = ES + duration__
//   __backward  LF = min(LS of successors)          LS = LF − duration__
//   __float     LS − ES, equivalently LF − EF__
//
// __The critical path is the zero-float chain, and it is also necessarily the__
// __longest path through the network. Its length is the project duration.__
//
// __**Implementation note.** The passes are iterated to a fixed point rather__
// __than run over a topological sort. The textbook algorithm needs the sort;__
// __this does not, and for the sizes a human builds by hand the cost is__
// __irrelevant. The benefit is that a cycle cannot produce a stack overflow or a__
// __wrong answer — it produces a தவறு from சுழற்சி_உள்ளதா, which is checked__
// __first. A cycle is the commonest structural error in a hand-built network and__
// __it must fail loudly.__
//
// __Lags and the four dependency types are not modelled. Finish-to-start only,__
// __which is what CPM proper is; start-to-start with a lag belongs to a richer__
// __scheduler and would change every signature here.__

// செயல்_ஆக்கு(செயல்_குறி, செயல்_காலம், முன்னோடிகள்)
//
// __முன்னோடிகள் is a list of activity codes. An empty list starts the network.__
// செயல்_ஆக்கு(செயல்_குறி, செயல்_காலம், முன்னோடிகள்) — வலையில் ஒரு செயலை உருவாக்கும்
செயல் செயல்_ஆக்கு(செயல்_குறி, செயல்_காலம், முன்னோடிகள்) {
    திரும்பு {
        செயல்_குறி: செயல்_குறி,
        செயல்_காலம்: செயல்_காலம்,
        முன்னோடிகள்: முன்னோடிகள்
    };
}

// __செயலைத்_தேடு(செயல்கள், செயல்_குறி) — find one activity by its code__
// செயலைத்_தேடு(செயல்கள், செயல்_குறி) — குறியைக் கொண்டு ஒரு செயலைத் தேடும்
//
// __சரி with the activity, or தவறு naming the code. A dependency pointing at an activity that is not in the network would otherwise impose no constraint, and the schedule comes out shorter than reality rather than wrong in a visible way.__
செயல் செயலைத்_தேடு(செயல்கள், செயல்_குறி) {
    ஒவ்வொரு ஒரு_செயல் இல் செயல்கள் {
        (ஒரு_செயல்.செயல்_குறி == செயல்_குறி) எனில் { திரும்பு சரி(ஒரு_செயல்); }
    }
    திரும்பு தவறு("செயல் காணவில்லை: " & செயல்_குறி);
}

// __வழித்தோன்றல்கள்(செயல்கள், செயல்_குறி) — the successors of an activity__
// வழித்தோன்றல்கள்(செயல்கள், செயல்_குறி) — ஒரு செயலைத் தொடரும் செயல்கள்
செயல் வழித்தோன்றல்கள்(செயல்கள், செயல்_குறி) {
    விடை_பட்டி = [];
    ஒவ்வொரு ஒரு_செயல் இல் செயல்கள் {
        ஒவ்வொரு ஒரு_முன்னோடி இல் ஒரு_செயல்.முன்னோடிகள் {
            (ஒரு_முன்னோடி == செயல்_குறி) எனில் {
                விடை_பட்டி = இணை(விடை_பட்டி, ஒரு_செயல்);
            }
        }
    }
    திரும்பு விடை_பட்டி;
}

// __--- Structural checks --------------------------------------------------__

// __முன்னோடிகள்_உள்ளனவா(செயல்கள்) — every named predecessor must exist__
// முன்னோடிகள்_உள்ளனவா(செயல்கள்) — பெயரிடப்பட்ட ஒவ்வொரு முன்னோடியும் உண்மையில் உள்ளதா
செயல் முன்னோடிகள்_உள்ளனவா(செயல்கள்) {
    ஒவ்வொரு ஒரு_செயல் இல் செயல்கள் {
        ஒவ்வொரு ஒரு_முன்னோடி இல் ஒரு_செயல்.முன்னோடிகள் {
            (தவறா(செயலைத்_தேடு(செயல்கள், ஒரு_முன்னோடி))) எனில் {
                திரும்பு தவறு(ஒரு_செயல்.செயல்_குறி & " குறிக்கும் முன்னோடி "
                              & ஒரு_முன்னோடி & " இல்லை");
            }
        }
    }
    திரும்பு சரி(மெய்);
}

// __சுழற்சி_உள்ளதா(செயல்கள்) — is there a cycle?__
// சுழற்சி_உள்ளதா(செயல்கள்) — வலையில் சுழற்சி உள்ளதா
//
// __Repeatedly strip activities all of whose predecessors have already been__
// __stripped. What cannot be stripped is in, or downstream of, a cycle. This is__
// __Kahn's algorithm used only for its emptiness test.__
செயல் சுழற்சி_உள்ளதா(செயல்கள்) {
    தீர்ந்தவை = [];
    மாற்றம்_உண்டு = மெய்;
    (மாற்றம்_உண்டு) சுற்று {
        மாற்றம்_உண்டு = பொய்;
        ஒவ்வொரு ஒரு_செயல் இல் செயல்கள் {
            (இல்லை குறி_உள்ளதா(தீர்ந்தவை, ஒரு_செயல்.செயல்_குறி)) எனில் {
                அனைத்தும்_தீர்ந்தன = மெய்;
                ஒவ்வொரு ஒரு_முன்னோடி இல் ஒரு_செயல்.முன்னோடிகள் {
                    (இல்லை குறி_உள்ளதா(தீர்ந்தவை, ஒரு_முன்னோடி)) எனில் {
                        அனைத்தும்_தீர்ந்தன = பொய்;
                    }
                }
                (அனைத்தும்_தீர்ந்தன) எனில் {
                    தீர்ந்தவை = இணை(தீர்ந்தவை, ஒரு_செயல்.செயல்_குறி);
                    மாற்றம்_உண்டு = மெய்;
                }
            }
        }
    }
    திரும்பு நீளம்(தீர்ந்தவை) != நீளம்(செயல்கள்);
}

// __--- The two passes ------------------------------------------------------__

// வலையைக்_கணக்கிடு(செயல்கள்)
//
// __One call does both passes and returns the activities enriched with__
// __முந்தைய_தொடக்கம் (ES), முந்தைய_முடிவு (EF), பிந்தைய_தொடக்கம் (LS),__
// __பிந்தைய_முடிவு (LF) and மிதப்பு (float).__
// வலையைக்_கணக்கிடு(செயல்கள்) — முன்னோக்கி, பின்னோக்கி இரு கடப்புகளையும் செய்யும்
செயல் வலையைக்_கணக்கிடு(செயல்கள்) {
    சரிபார்ப்பு = முன்னோடிகள்_உள்ளனவா(செயல்கள்);
    (தவறா(சரிபார்ப்பு)) எனில் { திரும்பு சரிபார்ப்பு; }
    (சுழற்சி_உள்ளதா(செயல்கள்)) எனில் {
        திரும்பு தவறு("வலையில் சுழற்சி உள்ளது: முன்னோக்கு கணக்கிட முடியாது");
    }

    // __Forward pass, iterated to a fixed point.__
    முந்தைய = [];
    ஒவ்வொரு ஒரு_செயல் இல் செயல்கள் {
        முந்தைய = இணை(முந்தைய, { செயல்_குறி: ஒரு_செயல்.செயல்_குறி,
                                  தொடக்கம்: 0,
                                  முடிவு: ஒரு_செயல்.செயல்_காலம் });
    }
    மாற்றம்_உண்டு = மெய்;
    (மாற்றம்_உண்டு) சுற்று {
        மாற்றம்_உண்டு = பொய்;
        ஒவ்வொரு ஒரு_செயல் இல் செயல்கள் {
            புதிய_தொடக்கம் = 0;
            ஒவ்வொரு ஒரு_முன்னோடி இல் ஒரு_செயல்.முன்னோடிகள் {
                முடிவு_மதிப்பு = பதிவைத்_தேடு(முந்தைய, ஒரு_முன்னோடி, "முடிவு");
                (முடிவு_மதிப்பு > புதிய_தொடக்கம்) எனில் {
                    புதிய_தொடக்கம் = முடிவு_மதிப்பு;
                }
            }
            பழைய_தொடக்கம் = பதிவைத்_தேடு(முந்தைய, ஒரு_செயல்.செயல்_குறி,
                                           "தொடக்கம்");
            (புதிய_தொடக்கம் != பழைய_தொடக்கம்) எனில் {
                முந்தைய = பதிவை_மாற்று(முந்தைய, ஒரு_செயல்.செயல்_குறி,
                                        புதிய_தொடக்கம்,
                                        புதிய_தொடக்கம் + ஒரு_செயல்.செயல்_காலம்);
                மாற்றம்_உண்டு = மெய்;
            }
        }
    }

    திட்ட_காலம் = 0;
    ஒவ்வொரு ஒரு_பதிவு இல் முந்தைய {
        (ஒரு_பதிவு.முடிவு > திட்ட_காலம்) எனில் { திட்ட_காலம் = ஒரு_பதிவு.முடிவு; }
    }

    // __Backward pass, likewise. Every activity starts at the project duration__
    // __and is pulled earlier by its successors.__
    பிந்தைய = [];
    ஒவ்வொரு ஒரு_செயல் இல் செயல்கள் {
        பிந்தைய = இணை(பிந்தைய, { செயல்_குறி: ஒரு_செயல்.செயல்_குறி,
                                  தொடக்கம்: திட்ட_காலம் - ஒரு_செயல்.செயல்_காலம்,
                                  முடிவு: திட்ட_காலம் });
    }
    மாற்றம்_உண்டு = மெய்;
    (மாற்றம்_உண்டு) சுற்று {
        மாற்றம்_உண்டு = பொய்;
        ஒவ்வொரு ஒரு_செயல் இல் செயல்கள் {
            புதிய_முடிவு = திட்ட_காலம்;
            ஒவ்வொரு ஒரு_பின் இல் வழித்தோன்றல்கள்(செயல்கள்,
                                                  ஒரு_செயல்.செயல்_குறி) {
                தொடக்க_மதிப்பு = பதிவைத்_தேடு(பிந்தைய, ஒரு_பின்.செயல்_குறி,
                                                "தொடக்கம்");
                (தொடக்க_மதிப்பு < புதிய_முடிவு) எனில் {
                    புதிய_முடிவு = தொடக்க_மதிப்பு;
                }
            }
            பழைய_முடிவு = பதிவைத்_தேடு(பிந்தைய, ஒரு_செயல்.செயல்_குறி, "முடிவு");
            (புதிய_முடிவு != பழைய_முடிவு) எனில் {
                பிந்தைய = பதிவை_மாற்று(பிந்தைய, ஒரு_செயல்.செயல்_குறி,
                                        புதிய_முடிவு - ஒரு_செயல்.செயல்_காலம்,
                                        புதிய_முடிவு);
                மாற்றம்_உண்டு = மெய்;
            }
        }
    }

    விடை_பட்டி = [];
    ஒவ்வொரு ஒரு_செயல் இல் செயல்கள் {
        முன்_தொ = பதிவைத்_தேடு(முந்தைய, ஒரு_செயல்.செயல்_குறி, "தொடக்கம்");
        முன்_மு = பதிவைத்_தேடு(முந்தைய, ஒரு_செயல்.செயல்_குறி, "முடிவு");
        பின்_தொ = பதிவைத்_தேடு(பிந்தைய, ஒரு_செயல்.செயல்_குறி, "தொடக்கம்");
        பின்_மு = பதிவைத்_தேடு(பிந்தைய, ஒரு_செயல்.செயல்_குறி, "முடிவு");
        விடை_பட்டி = இணை(விடை_பட்டி, {
            செயல்_குறி: ஒரு_செயல்.செயல்_குறி,
            செயல்_காலம்: ஒரு_செயல்.செயல்_காலம்,
            முந்தைய_தொடக்கம்: முன்_தொ,
            முந்தைய_முடிவு: முன்_மு,
            பிந்தைய_தொடக்கம்: பின்_தொ,
            பிந்தைய_முடிவு: பின்_மு,
            மிதப்பு: பின்_தொ - முன்_தொ
        });
    }
    திரும்பு சரி({ செயல்கள்: விடை_பட்டி, திட்ட_காலம்: திட்ட_காலம் });
}

// __--- Reading the answer --------------------------------------------------__

// __கடுமையானவை(கணக்கிட்டவை) — the zero-float activities__
// கடுமையானவை(கணக்கிட்டவை) — இளைப்பே இல்லாத செயல்கள்
//
// __Float belongs to the project, not to the activity's owner. Where it is__
// __treated as a private buffer it is consumed first and unavailable when__
// __genuinely needed, which is a governance point rather than a technical one.__
செயல் கடுமையானவை(கணக்கிட்டவை) {
    விடை_பட்டி = [];
    ஒவ்வொரு ஒரு_செயல் இல் கணக்கிட்டவை.செயல்கள் {
        (ஒரு_செயல்.மிதப்பு == 0) எனில் {
            விடை_பட்டி = இணை(விடை_பட்டி, ஒரு_செயல்);
        }
    }
    திரும்பு விடை_பட்டி;
}

// __உணர்திறன்_வலையா(கணக்கிட்டவை) — is the network sensitive?__
// உணர்திறன்_வலையா(கணக்கிட்டவை) — இவ்வலை உணர்திறன் மிக்கதா
//
// __A network where most activities are critical absorbs no disturbance: a small__
// __slip anywhere makes a new path critical. One with a single critical chain__
// __and generous float elsewhere is insensitive. Half is the conventional line__
// __and it is a judgement, not a law.__
செயல் உணர்திறன்_வலையா(கணக்கிட்டவை) {
    மொத்தம் = நீளம்(கணக்கிட்டவை.செயல்கள்);
    (மொத்தம் == 0) எனில் { திரும்பு பொய்; }
    திரும்பு நீளம்(கடுமையானவை(கணக்கிட்டவை)) * 2 >= மொத்தம்;
}

// பெறு_புலம்(கணக்கிட்ட_செயல்கள், செயல்_குறி, புலப்_பெயர்)
//
// __One computed field of one activity, by name. Exists because the result of__
// __வலையைக்_கணக்கிடு is a list and the caller almost always wants a single__
// __figure out of it — "what is D's float?" — rather than the whole table.__
// __Valid field names are முந்தைய_தொடக்கம், முந்தைய_முடிவு,__
// __பிந்தைய_தொடக்கம், பிந்தைய_முடிவு, மிதப்பு and செயல்_காலம்.__
// பெறு_புலம்(கணக்கிட்ட_செயல்கள், செயல்_குறி, புலப்_பெயர்) — கணக்கிட்ட செயலின் ஒரு புலத்தைப் படிக்கும்
செயல் பெறு_புலம்(கணக்கிட்ட_செயல்கள், செயல்_குறி, புலப்_பெயர்) {
    ஒவ்வொரு ஒரு_செயல் இல் கணக்கிட்ட_செயல்கள் {
        (ஒரு_செயல்.செயல்_குறி == செயல்_குறி) எனில் {
            (புலப்_பெயர் == "முந்தைய_தொடக்கம்") எனில் {
                திரும்பு ஒரு_செயல்.முந்தைய_தொடக்கம்;
            }
            (புலப்_பெயர் == "முந்தைய_முடிவு") எனில் {
                திரும்பு ஒரு_செயல்.முந்தைய_முடிவு;
            }
            (புலப்_பெயர் == "பிந்தைய_தொடக்கம்") எனில் {
                திரும்பு ஒரு_செயல்.பிந்தைய_தொடக்கம்;
            }
            (புலப்_பெயர் == "பிந்தைய_முடிவு") எனில் {
                திரும்பு ஒரு_செயல்.பிந்தைய_முடிவு;
            }
            (புலப்_பெயர் == "செயல்_காலம்") எனில் {
                திரும்பு ஒரு_செயல்.செயல்_காலம்;
            }
            திரும்பு ஒரு_செயல்.மிதப்பு;
        }
    }
    திரும்பு 0;
}

// __--- Small helpers the passes need --------------------------------------__

// __குறி_உள்ளதா(பட்டியல், தேடும்_குறி) — is this code in the list?__
// குறி_உள்ளதா(பட்டியல், தேடும்_குறி) — இக்குறி பட்டியலில் உள்ளதா
//
// __Used on predecessor lists, which are short. Kept local so the scheduler carries no dependency on the collection helpers in col.qmz.__
செயல் குறி_உள்ளதா(பட்டியல், தேடும்_குறி) {
    ஒவ்வொரு ஒன்று இல் பட்டியல் {
        (ஒன்று == தேடும்_குறி) எனில் { திரும்பு மெய்; }
    }
    திரும்பு பொய்;
}

// __பதிவைத்_தேடு(பதிவுகள், செயல்_குறி, புலப்_பெயர்) — read a start or finish from a pass__
// பதிவைத்_தேடு(பதிவுகள், செயல்_குறி, புலப்_பெயர்) — ஒரு கடப்பிலிருந்து தொடக்கம் அல்லது முடிவைப் படிக்கும்
//
// __Answers 0 for an activity that has not been reached, which is what the forward pass needs: an unreached predecessor imposes no lower bound. Anything that should report a missing activity must use செயலைத்_தேடு instead.__
செயல் பதிவைத்_தேடு(பதிவுகள், செயல்_குறி, புலப்_பெயர்) {
    ஒவ்வொரு ஒரு_பதிவு இல் பதிவுகள் {
        (ஒரு_பதிவு.செயல்_குறி == செயல்_குறி) எனில் {
            (புலப்_பெயர் == "தொடக்கம்") எனில் { திரும்பு ஒரு_பதிவு.தொடக்கம்; }
            திரும்பு ஒரு_பதிவு.முடிவு;
        }
    }
    திரும்பு 0;
}

// __பதிவை_மாற்று(பதிவுகள், செயல்_குறி, புது_தொடக்கம், புது_முடிவு) — rewrite one activity's dates in a pass__
// பதிவை_மாற்று(பதிவுகள், செயல்_குறி, புது_தொடக்கம், புது_முடிவு) — ஒரு கடப்பில் ஒரு செயலின் நாள்களை மாற்றும்
//
// __Rebuilds the list rather than changing an entry in place, so each pass of the scheduler is a value the tests can hold and compare. Both dates are written together, because a start without its matching finish is a record that cannot be true.__
செயல் பதிவை_மாற்று(பதிவுகள், செயல்_குறி, புது_தொடக்கம், புது_முடிவு) {
    விடை_பட்டி = [];
    ஒவ்வொரு ஒரு_பதிவு இல் பதிவுகள் {
        (ஒரு_பதிவு.செயல்_குறி == செயல்_குறி) எனில் {
            விடை_பட்டி = இணை(விடை_பட்டி, { செயல்_குறி: செயல்_குறி,
                                            தொடக்கம்: புது_தொடக்கம்,
                                            முடிவு: புது_முடிவு });
        } இன்றேல் {
            விடை_பட்டி = இணை(விடை_பட்டி, ஒரு_பதிவு);
        }
    }
    திரும்பு விடை_பட்டி;
}

nUlakam/qittam/paNi.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/qittam/paNi.qmz — பணி (tasks: status, priority, baseline lock, roll-up)__
// பணி: நிலை, முன்னுரிமை, பூட்டு, திரட்டல்
//
// __The WBS in pakuppu.qmz is what the plan is made of; a பணி is what people__
// __actually work on, and it carries the four facts every task screen, report__
// __and integration asks about: where it stands, how urgent it is, how much of__
// __it is done, and whether the baseline still lets anyone move it.__
//
// __Five statuses, and two of them count as done:__
//
//   __செய்யவேண்டியது   to do__
//   __நடப்பில்          in progress__
//   __தீர்ந்தது         resolved — done, awaiting confirmation__
//   __மூடியது          closed — done__
//   __கைவிட்டது        cancelled — finished with, but not done__
//
// __Cancelled is the one that catches people out. It is terminal, so it is not__
// __overdue and it is not next week's work; but it is not done either, so it__
// __must not raise a project's percentage complete. Code that tests "not open"__
// __where it meant "done" credits the project with work nobody did.__
//
// __The status lives in நடப்பு_நிலை, the field nilYmARRam.qmz reads, so a__
// __task's own lifecycle can be run through the same machine as a change__
// __request's when a team wants its transitions enforced.__
//
// __Tasks are flat, like WBS nodes: each names its parent, and a top-level task__
// __has the empty string.__

இறக்கு "../atippatY/kaNiqam.qmz";

// __பணி_ஆக்கு(பணி_குறி, பெற்றோர்_குறி, பணி_நிலை, நிறைவு, மதிப்பீட்டு_மணி, இறுதி_நாள்) — one task__
// பணி_ஆக்கு(பணி_குறி, பெற்றோர்_குறி, பணி_நிலை, நிறைவு, மதிப்பீட்டு_மணி, இறுதி_நாள்) — ஒரு பணியை உருவாக்கும்
//
// __நிறைவு is a percentage, 0 to 100. இறுதி_நாள் is an ISO date or "" for a task__
// __with no due date. Other fields — தொடக்க_நாள், முடிந்த_நாள், பூட்டியதா — are__
// __read with புலம்_அல்லது where they matter, so a caller adds them only when__
// __it has them.__
செயல் பணி_ஆக்கு(பணி_குறி, பெற்றோர்_குறி, பணி_நிலை, நிறைவு, மதிப்பீட்டு_மணி, இறுதி_நாள்) {
    திரும்பு {
        பணி_குறி: பணி_குறி,
        பெற்றோர்_குறி: பெற்றோர்_குறி,
        நடப்பு_நிலை: பணி_நிலை,
        நிறைவு: நிறைவு,
        மதிப்பீட்டு_மணி: மதிப்பீட்டு_மணி,
        இறுதி_நாள்: இறுதி_நாள்
    };
}

// __பணி_நிலைகள்() — the five statuses, in working order__
// பணி_நிலைகள்() — ஐந்து பணி நிலைகள்
செயல் பணி_நிலைகள்() {
    திரும்பு ["செய்யவேண்டியது", "நடப்பில்", "தீர்ந்தது", "மூடியது", "கைவிட்டது"];
}

// __பணி_முடிந்ததா(பணி_நிலை) — does this status count as done?__
// பணி_முடிந்ததா(பணி_நிலை) — இந்நிலை முடிந்ததாகக் கணக்கிடப்படுமா
//
// __Resolved and closed. Not cancelled — see the note at the top of the file.__
செயல் பணி_முடிந்ததா(பணி_நிலை) {
    திரும்பு பணி_நிலை == "தீர்ந்தது" அல்லது பணி_நிலை == "மூடியது";
}

// __பணி_நிலுவையா(ஒரு_பணி, இன்றைய_நாள்) — is this task overdue?__
// பணி_நிலுவையா(ஒரு_பணி, இன்றைய_நாள்) — இப்பணி காலம் கடந்ததா
//
// __Past its due date, not done and not cancelled. A task with no due date is__
// __never overdue: it has not been promised for any day, and counting it would__
// __turn every unscheduled idea on the backlog into a red flag.__
செயல் பணி_நிலுவையா(ஒரு_பணி, இன்றைய_நாள்) {
    (ஒரு_பணி.இறுதி_நாள் == "") எனில் { திரும்பு பொய்; }
    (பணி_முடிந்ததா(ஒரு_பணி.நடப்பு_நிலை)) எனில் { திரும்பு பொய்; }
    (ஒரு_பணி.நடப்பு_நிலை == "கைவிட்டது") எனில் { திரும்பு பொய்; }
    திரும்பு ஒரு_பணி.இறுதி_நாள் < இன்றைய_நாள்;
}

// __முன்னுரிமை_தரம்(முன்னுரிமை) — a priority as a sortable rank__
// முன்னுரிமை_தரம்(முன்னுரிமை) — முன்னுரிமையை வரிசைப்படுத்தும் எண்ணாக்கும்
//
// __மிக_உயர் 0, உயர் 1, நடுத்தர 2, குறைவு 3, and anything else 9. The unknown__
// __case sorts last rather than failing: a priority nobody set is the least__
// __urgent thing on the list, not a reason to refuse to show the list.__
செயல் முன்னுரிமை_தரம்(முன்னுரிமை) {
    (முன்னுரிமை == "மிக_உயர்") எனில் { திரும்பு 0; }
    (முன்னுரிமை == "உயர்") எனில் { திரும்பு 1; }
    (முன்னுரிமை == "நடுத்தர") எனில் { திரும்பு 2; }
    (முன்னுரிமை == "குறைவு") எனில் { திரும்பு 3; }
    திரும்பு 9;
}

// __நிலைக்கான_நிறைவு(புதிய_நிலை, இப்போதைய_நிறைவு) — the percentage a status change implies__
// நிலைக்கான_நிறைவு(புதிய_நிலை, இப்போதைய_நிறைவு) — நிலை மாறும்போது நிறைவு சதவீதம்
//
// __Moving to do resets to 0; resolving or closing sets 100. In progress and__
// __cancelled keep whatever was there, because only the person doing the work__
// __knows how far through it they are, and a cancelled task's progress is a__
// __record of what was done before it was stopped.__
செயல் நிலைக்கான_நிறைவு(புதிய_நிலை, இப்போதைய_நிறைவு) {
    (புதிய_நிலை == "செய்யவேண்டியது") எனில் { திரும்பு 0; }
    (பணி_முடிந்ததா(புதிய_நிலை)) எனில் { திரும்பு 100; }
    திரும்பு இப்போதைய_நிறைவு;
}

// __பூட்டிலும்_மாறுபவை() — the fields a baselined task still accepts__
// பூட்டிலும்_மாறுபவை() — பூட்டிய பணியிலும் மாற்றக்கூடிய புலங்கள்
//
// __Once the schedule is baselined, the plan is frozen and only progress moves:__
// __status, percentage, actuals — the actual start and finish among them —__
// __priority and which milestone it rolls into.__
// __Changing a planned date or estimate after that is a change request, which is__
// __the whole point of having a baseline.__
செயல் பூட்டிலும்_மாறுபவை() {
    திரும்பு ["நடப்பு_நிலை", "நிறைவு", "உண்மைத்_தொடக்கம்", "முடிந்த_நாள்", "உண்மை_நாட்கள்",
              "உண்மை_மணி", "முன்னுரிமை", "மைல்கல்_குறி"];
}

// __பூட்டிய_மாற்றம்_சரியா(மாற்றங்கள்) — may these changes touch a baselined task?__
// பூட்டிய_மாற்றம்_சரியா(மாற்றங்கள்) — பூட்டிய பணியில் இம்மாற்றங்கள் அனுமதியா
//
// __மாற்றங்கள் is a record of field → new value. சரி(மாற்றங்கள்) when every field__
// __is one பூட்டிலும்_மாறுபவை allows; otherwise தவறு naming the first field that__
// __is not, so the screen can tell the person which edit needs a change request.__
செயல் பூட்டிய_மாற்றம்_சரியா(மாற்றங்கள்) {
    அனுமதித்தவை = பூட்டிலும்_மாறுபவை();
    ஒவ்வொரு புலப்_பெயர் இல் மாற்றங்கள் {
        உண்டு = பொய்;
        ஒவ்வொரு ஒன்று இல் அனுமதித்தவை {
            (ஒன்று == புலப்_பெயர்) எனில் { உண்டு = மெய்; }
        }
        (இல்லை உண்டு) எனில் {
            திரும்பு தவறு("அடிப்படைத் திட்டம் பூட்டியுள்ளது; " & புலப்_பெயர்
                           & " மாற்ற மாற்றக் கோரிக்கை தேவை  (the baseline is locked; changing "
                           & புலப்_பெயர் & " needs a change request)");
        }
    }
    திரும்பு சரி(மாற்றங்கள்);
}

// __திரட்டிய_நிறைவு(பணிகள், பணி_குறி) — a task's percentage, rolled up from its sub-tasks__
// திரட்டிய_நிறைவு(பணிகள், பணி_குறி) — துணைப் பணிகளிலிருந்து திரட்டிய நிறைவு
//
// __A leaf reports its own நிறைவு. A parent reports the rounded mean of its__
// __children's rolled-up figures, all the way down, so a parent's number is__
// __never one somebody typed. An unweighted mean on purpose: a parent's children__
// __are its steps, and the effort-weighted view belongs to the project as a__
// __whole — see எடையிட்ட_நிறைவு. A code that is not in the list gives 0.__
செயல் திரட்டிய_நிறைவு(பணிகள், பணி_குறி) {
    கூட்டல் = 0;
    எண்ணிக்கை = 0;
    ஒவ்வொரு ஒரு_பணி இல் பணிகள் {
        (ஒரு_பணி.பெற்றோர்_குறி == பணி_குறி) எனில் {
            கூட்டல் = கூட்டல் + திரட்டிய_நிறைவு(பணிகள், ஒரு_பணி.பணி_குறி);
            எண்ணிக்கை = எண்ணிக்கை + 1;
        }
    }
    (எண்ணிக்கை > 0) எனில் { திரும்பு வட்டமிடு(கூட்டல் / எண்ணிக்கை, 0); }
    ஒவ்வொரு ஒரு_பணி இல் பணிகள் {
        (ஒரு_பணி.பணி_குறி == பணி_குறி) எனில் { திரும்பு ஒரு_பணி.நிறைவு; }
    }
    திரும்பு 0;
}

// __எடையிட்ட_நிறைவு(பணிகள்) — percentage complete, weighted by estimated effort__
// எடையிட்ட_நிறைவு(பணிகள்) — மதிப்பீட்டு மணியால் எடையிட்ட நிறைவு
//
// __Σ(hours × percentage) ÷ Σ hours, so a finished forty-hour task moves the__
// __project more than a finished one-hour one. When no task carries an estimate__
// __the weights are all zero and the formula divides by nothing, so it falls__
// __back to the plain mean rather than reporting a project as 0% done. Cancelled__
// __tasks are left out of both sums — see the note at the top of the file — so__
// __abandoning half-done work neither raises nor lowers the figure. Rounded to a__
// __whole percentage; a list with nothing but cancelled tasks, or none, is 0.__
செயல் எடையிட்ட_நிறைவு(பணிகள்) {
    எடைக்_கூட்டல் = 0;
    மணிக்_கூட்டல் = 0;
    வெறுங்_கூட்டல் = 0;
    எண்ணிக்கை = 0;
    ஒவ்வொரு ஒரு_பணி இல் பணிகள் {
        (ஒரு_பணி.நடப்பு_நிலை != "கைவிட்டது") எனில் {
            எடைக்_கூட்டல் = எடைக்_கூட்டல் + ஒரு_பணி.மதிப்பீட்டு_மணி * ஒரு_பணி.நிறைவு;
            மணிக்_கூட்டல் = மணிக்_கூட்டல் + ஒரு_பணி.மதிப்பீட்டு_மணி;
            வெறுங்_கூட்டல் = வெறுங்_கூட்டல் + ஒரு_பணி.நிறைவு;
            எண்ணிக்கை = எண்ணிக்கை + 1;
        }
    }
    (மணிக்_கூட்டல் > 0) எனில் { திரும்பு வட்டமிடு(எடைக்_கூட்டல் / மணிக்_கூட்டல், 0); }
    (எண்ணிக்கை == 0) எனில் { திரும்பு 0; }
    திரும்பு வட்டமிடு(வெறுங்_கூட்டல் / எண்ணிக்கை, 0);
}

// __பெற்றோர்_முன்_வரிசை(பதிவுகள், குறிப்_புலம், பெற்றோர்_புலம்) — order a flat tree parents first__
// பெற்றோர்_முன்_வரிசை(பதிவுகள், குறிப்_புலம், பெற்றோர்_புலம்) — பெற்றோரை முதலில் வைத்து வரிசைப்படுத்தும்
//
// __Anything that creates a tree somewhere else — tasks from an approved change__
// __request, work items in Azure DevOps — must create a parent before its__
// __children, because the child's link needs the parent's new id. This orders__
// __any flat list of records by that rule, with the two field names given so it__
// __serves tasks, WBS nodes and work items alike.__
//
// __A record whose parent is not in the list counts as a root: its parent__
// __already exists elsewhere. The list is swept repeatedly, and each sweep takes,__
// __in input order, every record whose parent is already placed — so a child__
// __listed after its parent can follow it in the same sweep, while one listed__
// __before it waits for the next. Parents always come first; the order among__
// __unrelated records is the sweep order, not the input order. A cycle__
// __has no parents-first order, so it is தவறு.__
செயல் பெற்றோர்_முன்_வரிசை(பதிவுகள், குறிப்_புலம், பெற்றோர்_புலம்) {
    எல்லாக்_குறிகள் = [];
    ஒவ்வொரு ஒரு_பதிவு இல் பதிவுகள் {
        எல்லாக்_குறிகள் = இணை(எல்லாக்_குறிகள், ஒரு_பதிவு[குறிப்_புலம்]);
    }
    வைத்தவை = [];
    வைத்த_குறிகள் = [];
    முன்னேற்றம் = மெய்;
    (முன்னேற்றம்) சுற்று {
        முன்னேற்றம் = பொய்;
        ஒவ்வொரு ஒரு_பதிவு இல் பதிவுகள் {
            குறி = ஒரு_பதிவு[குறிப்_புலம்];
            பெற்றோர் = ஒரு_பதிவு[பெற்றோர்_புலம்];
