// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __சுழற்சி_உள்ளதா(செயல்கள்) — is there a cycle in the network?__
// வலையில் சுழற்சி உள்ளதா

இறக்கு "../pakuppu.qmz";
இறக்கு "../pAqY.qmz";
இறக்கு "../qotarpu.qmz";
இறக்கு "../curukkal.qmz";
இறக்கு "../kattuppAtu.qmz";
இறக்கு "../Ittu_maqippu.qmz";
இறக்கு "../oppanqa_vakY.qmz";

நல்லது = [செயல்_ஆக்கு("A", 3, []), செயல்_ஆக்கு("B", 4, ["A"])];
அச்சு சுழற்சி_உள்ளதா(நல்லது);

// __Two activities each waiting for the other. The forward pass would never__
// __settle, so this is asked before it is attempted rather than discovered as__
// __a loop that does not end.__
// ஒன்றுக்கொன்று காத்திருக்கும் இரு செயல்கள்; முன்னோக்கு ஒருபோதும் நிலைக்காது
சுழற்சி = [செயல்_ஆக்கு("A", 3, ["B"]), செயல்_ஆக்கு("B", 4, ["A"])];
அச்சு சுழற்சி_உள்ளதா(சுழற்சி);

nUlakam/qittam/uqavi/eqirpArkkum_kAlam.q:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __எதிர்பார்க்கும்_காலம்(அசல்_காலம், காலத்_திறன்) — how long the project will take at this rate__
// இந்த வேகம் குறிக்கும் கால அளவு

இறக்கு "../pakuppu.qmz";
இறக்கு "../pAqY.qmz";
இறக்கு "../qotarpu.qmz";
இறக்கு "../curukkal.qmz";
இறக்கு "../kattuppAtu.qmz";
இறக்கு "../Ittu_maqippu.qmz";
இறக்கு "../oppanqa_vakY.qmz";

// __Twenty-four months of plan at five-sixths of the rate is twenty-eight and a__
// __bit. A crude forecast and a useful one, because it is arithmetic nobody can__
// __argue with.__
// கச்சாவான ஆனால் பயனுள்ள கணிப்பு; வாதிட முடியாத கணக்கு
அச்சு வட்டமிடு(மதிப்பு(எதிர்பார்க்கும்_காலம்(24, 0.8333)), 2);
அச்சு மதிப்பு(எதிர்பார்க்கும்_காலம்(24, 1));

// __At a rate of nothing the project never finishes, which is a தவறு rather__
// __than a very large number.__
// வேகமே இல்லையெனில் திட்டம் முடியாது; அது தவறே
அச்சு தவறா(எதிர்பார்க்கும்_காலம்(24, 0));

nUlakam/qittam/uqavi/etYyitta_niRYvu.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __எடையிட்ட_நிறைவு(பணிகள்) — percentage complete, weighted by estimated effort__
// மதிப்பீட்டு மணியால் எடையிட்ட நிறைவு

இறக்கு "../paNi.qmz";

// __A finished forty-hour integration outweighs an untouched one-hour config__
// __change: 4000 over 41 hours, not the plain mean of 50.__
// முடிந்த நாற்பது மணிப் பணி ஒரு மணிப் பணியை விட அதிகம் எடையுடையது
அச்சு எடையிட்ட_நிறைவு([பணி_ஆக்கு("T-1", "", "மூடியது", 100, 40, ""),
                      பணி_ஆக்கு("T-2", "", "செய்யவேண்டியது", 0, 1, "")]);

// __With no estimates anywhere, it falls back to the plain mean rather than 0.__
// மதிப்பீடே இல்லையெனில் வெறும் சராசரி
அச்சு எடையிட்ட_நிறைவு([பணி_ஆக்கு("T-1", "", "மூடியது", 100, 0, ""),
                      பணி_ஆக்கு("T-2", "", "செய்யவேண்டியது", 0, 0, "")]);

// __But one estimate is enough to switch to weights, and then every task with__
// __no estimate weighs nothing: the untouched T-2 no longer drags it down.__
// ஒரு மதிப்பீடு இருந்தாலே எடைமுறை; மதிப்பீடற்ற பணிகள் எடையற்றுப் போகும்
அச்சு எடையிட்ட_நிறைவு([பணி_ஆக்கு("T-1", "", "மூடியது", 100, 8, ""),
                      பணி_ஆக்கு("T-2", "", "செய்யவேண்டியது", 0, 0, "")]);

// __A cancelled task is left out entirely: its 80% was work that will never be__
// __delivered, so the project stands at the 0% of the one task still in play.__
// கைவிட்ட பணி முழுதும் விலக்கப்படும்; அதன் 80% திட்டத்தை உயர்த்தாது
அச்சு எடையிட்ட_நிறைவு([பணி_ஆக்கு("T-1", "", "கைவிட்டது", 80, 10, ""),
                      பணி_ஆக்கு("T-2", "", "செய்யவேண்டியது", 0, 10, "")]);
அச்சு எடையிட்ட_நிறைவு([]);

nUlakam/qittam/uqavi/iRuqi_nilYyA.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __இறுதி_நிலையா(வரைவு, ஒரு_நிலை) — has this state nowhere left to go?__
// இது இறுதி நிலையா

இறக்கு "../nilYmARRam.qmz";
இறக்கு "../mARRak_kOrikkY.qmz";

வரைவு = மாற்றக்_கோரிக்கை_வரைவு();

// __Rejected and revoked are the end of a change request.__
// மறுத்ததும் திரும்பப்பெற்றதும் இறுதி நிலைகள்
அச்சு இறுதி_நிலையா(வரைவு, "மறுத்தது");
அச்சு இறுதி_நிலையா(வரைவு, "திரும்பப்பெற்றது");

// __Approved is not, because it can still be revoked. A register that closes__
// __approved changes as final loses the ability to take one back.__
// ஏற்றது இறுதியல்ல; அதைத் திரும்பப்பெறலாம்
அச்சு இறுதி_நிலையா(வரைவு, "ஏற்றது");

// __A state the machine does not know has no next states, so it reads as__
// __terminal. Check a state is known before trusting this answer.__
// அறியாத நிலைக்கு அடுத்த நிலைகள் இல்லை; ஆகவே அது இறுதியாகத் தோன்றும்
அச்சு இறுதி_நிலையா(வரைவு, "ஏற்றத்து");

