// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __ஒரே_கணக்கா(கணக்குகள், கணுக்கள், கணு_குறி) — does this node fall under exactly one control account?__
// இக்கணு ஒரே ஒரு கட்டுப்பாட்டுக் கணக்கின் கீழ் வருகிறதா

இறக்கு "../pakuppu.qmz";
இறக்கு "../pAqY.qmz";
இறக்கு "../qotarpu.qmz";
இறக்கு "../curukkal.qmz";
இறக்கு "../kattuppAtu.qmz";
இறக்கு "../Ittu_maqippu.qmz";
இறக்கு "../oppanqa_vakY.qmz";

கணுக்கள் = [கணு_ஆக்கு("1", "", "திட்டம்", 1000000),
             கணு_ஆக்கு("1.1", "1", "வடிவமைப்பு", 400000),
             கணு_ஆக்கு("1.1.1", "1.1", "வரைபடம்", 400000)];
கணக்குகள் = [கட்டுப்பாட்டுக்_கணக்கு_ஆக்கு("CA-1", "1.1", "பாலமுரளி")];

// __Exactly one. Two control accounts on one path means one work package is__
// __reported to two managers, and its cost appears twice in the roll-up.__
// ஒரே ஒன்று; இரண்டு என்றால் அதே செலவு இருமுறை அறிவிக்கப்படும்
அச்சு ஒரே_கணக்கா(கணக்குகள், கணுக்கள், "1.1.1");

// __And none at all means a work package nobody is accountable for.__
// ஒன்றுமில்லையெனில், யாரும் பொறுப்பேற்காத வேலைத் தொகுப்பு
அச்சு ஒரே_கணக்கா([], கணுக்கள், "1.1.1");

// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __பாதையில்_கணக்குகள்(கணக்குகள், கணுக்கள், கணு_குறி) — how many control accounts sit above this node__
// மூலம் வரையிலான பாதையில் எத்தனை கட்டுப்பாட்டுக் கணக்குகள்

இறக்கு "../pakuppu.qmz";
இறக்கு "../pAqY.qmz";
இறக்கு "../qotarpu.qmz";
இறக்கு "../curukkal.qmz";
இறக்கு "../kattuppAtu.qmz";
இறக்கு "../Ittu_maqippu.qmz";
இறக்கு "../oppanqa_vakY.qmz";

கணுக்கள் = [கணு_ஆக்கு("1", "", "திட்டம்", 1000000),
             கணு_ஆக்கு("1.1", "1", "வடிவமைப்பு", 400000),
             கணு_ஆக்கு("1.1.1", "1.1", "வரைபடம்", 400000)];

// __One is right. Zero and two are both faults, and counting is how they are__
// __told apart.__
// ஒன்றே சரி; பூஜ்ஜியமும் இரண்டும் இரு வேறு குறைகள்
அச்சு பாதையில்_கணக்குகள்(
    [கட்டுப்பாட்டுக்_கணக்கு_ஆக்கு("CA-1", "1.1", "பா")], கணுக்கள், "1.1.1");
அச்சு பாதையில்_கணக்குகள்(
    [கட்டுப்பாட்டுக்_கணக்கு_ஆக்கு("CA-1", "1.1", "பா"),
     கட்டுப்பாட்டுக்_கணக்கு_ஆக்கு("CA-2", "1", "நி")], கணுக்கள், "1.1.1");

nUlakam/qittam/uqavi/pAqYyil_maqippu.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __பாதையில்_மதிப்பு(சூழல், புள்ளிப்_பாதை) — the value at a dotted path__
// புள்ளிப் பாதையிலுள்ள மதிப்பு

இறக்கு "../kattam.qmz";

சூழல் = {"திட்டம்": {"பெயர்": "Billing portal", "நிதி": {"தொகை": 48000}, "அனுசரணையாளர்": ""},
         "மைல்கற்கள்": ["M1", "M2"]};

// __Each dotted part walks one record deeper; a single part reads the top level.__
// ஒவ்வொரு புள்ளியும் ஒரு பதிவு ஆழம்
அச்சு மதிப்பு(பாதையில்_மதிப்பு(சூழல், "திட்டம்.பெயர்"));
அச்சு மதிப்பு(பாதையில்_மதிப்பு(சூழல், "திட்டம்.நிதி.தொகை"));
அச்சு நீளம்(மதிப்பு(பாதையில்_மதிப்பு(சூழல், "மைல்கற்கள்")));

// __A missing field is a தவறு naming the part that is missing, not the whole path.__
// இல்லாத புலம் அந்தப் பகுதியையே பெயரிடும்
அச்சு தவறு_மதிப்பு(பாதையில்_மதிப்பு(சூழல், "திட்டம்.மேலாளர்.பெயர்"));

// __A sponsor recorded as "" is there, so this is சரி with "". Whether an empty value__
// __is good enough is வார்ப்புத்_தயார்நிலை's question, not this one's.__
// வெற்று மதிப்பு இருக்கிறது; ஆகவே சரியே
விடை = பாதையில்_மதிப்பு(சூழல், "திட்டம்.அனுசரணையாளர்");
அச்சு சொல்லாக்கு(சரியா(விடை)) & " [" & மதிப்பு(விடை) & "]";

// __Paths do not index lists: "மைல்கற்கள்.0" is refused, because a list has no fields.__
// பாதை பட்டியலுக்குள் செல்லாது
அச்சு தவறா(பாதையில்_மதிப்பு(சூழல், "மைல்கற்கள்.0"));

nUlakam/qittam/uqavi/pUttilum_mARupavY.q:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __பூட்டிலும்_மாறுபவை() — the fields a baselined task still accepts__
// பூட்டிய பணியிலும் மாற்றக்கூடிய புலங்கள்

இறக்கு "../paNi.qmz";

// __Progress fields only: status, percentage, actuals, priority, milestone.__
// முன்னேற்றப் புலங்கள் மட்டும்
ஒவ்வொரு ஒன்று இல் பூட்டிலும்_மாறுபவை() {
    அச்சு ஒன்று;
}

// __The due date and the estimate are not on the list. Moving either after the__
// __baseline is exactly what a change request is for.__
// இறுதி நாளும் மதிப்பீடும் பட்டியலில் இல்லை; அவற்றுக்கு மாற்றக் கோரிக்கை தேவை
உண்டு = பொய்;
ஒவ்வொரு ஒன்று இல் பூட்டிலும்_மாறுபவை() {
    (ஒன்று == "இறுதி_நாள்" அல்லது ஒன்று == "மதிப்பீட்டு_மணி") எனில் { உண்டு = மெய்; }
}
அச்சு உண்டு;

nUlakam/qittam/uqavi/pUttiya_mARRam_cari:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __பூட்டிய_மாற்றம்_சரியா(மாற்றங்கள்) — may these edits touch a baselined task?__
// பூட்டிய பணியில் இம்மாற்றங்கள் அனுமதியா

இறக்கு "../paNi.qmz";

// __Logging progress on a baselined task is fine, and the edits come back as given.__
// பூட்டிய பணியில் முன்னேற்றத்தைப் பதிவது சரி
சரியானவை = பூட்டிய_மாற்றம்_சரியா({நடப்பு_நிலை: "நடப்பில்", நிறைவு: 60, உண்மை_மணி: 14});
அச்சு தவறா(சரியானவை);
அச்சு மதிப்பு(சரியானவை).நிறைவு;

// __Moving the due date is not. The message names the field, so the screen can__
// __point the person at the change request form.__
// இறுதி நாளை மாற்றுவது மறுக்கப்படும்; செய்தி அப்புலத்தைக் குறிக்கும்
மறுப்பு = பூட்டிய_மாற்றம்_சரியா({நிறைவு: 60, இறுதி_நாள்: "2026-11-01"});
அச்சு தவறா(மறுப்பு);
அச்சு தவறு_மதிப்பு(மறுப்பு);

// __One bad field refuses the whole set; the good progress edit riding with it__
// __is not saved on its own.__
// ஒரு தவறான புலம் முழுத் தொகுதியையும் மறுக்கும்
அச்சு தவறா(பூட்டிய_மாற்றம்_சரியா({நிறைவு: 80, மதிப்பீட்டு_மணி: 40}));

// __No edits at all is allowed.__
// மாற்றமே இல்லையெனில் அனுமதி
அச்சு தவறா(பூட்டிய_மாற்றம்_சரியா({}));

