இறக்கு "../pAqY.qmz";
இறக்கு "../qotarpu.qmz";
இறக்கு "../curukkal.qmz";
இறக்கு "../kattuppAtu.qmz";
இறக்கு "../Ittu_maqippu.qmz";
இறக்கு "../oppanqa_vakY.qmz";

பகிர்வுகள் = [காலப்_பகிர்வு(1, 100000),
              காலப்_பகிர்வு(2, 250000),
              காலப்_பகிர்வு(3, 400000)];

// __The S-curve, read at a point. This is the planned value that earned-value__
// __reporting compares against, and it has to be cumulative rather than the__
// __period's own figure.__
// இது திரட்டியதாக இருக்க வேண்டும்; அந்தக் காலத்தின் தொகை மட்டும் அல்ல
அச்சு திரட்டிய_நிதி(பகிர்வுகள், 1);
அச்சு திரட்டிய_நிதி(பகிர்வுகள், 2);
அச்சு திரட்டிய_நிதி(பகிர்வுகள், 3);
அச்சு திரட்டிய_நிதி(பகிர்வுகள், 0);

nUlakam/qittam/uqavi/qitta_nalam.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __திட்ட_நலம்(தொடக்க_நாள், முடிவு_நாள், மூடியதா, மைல்கற்கள், பணிகள், இன்றைய_நாள்) — the RAG status, with its reasons__
// திட்டத்தின் நிறக் குறியும் காரணங்களும்

இறக்கு "../paNi.qmz";
இறக்கு "../nalam.qmz";

இன்று = "2026-10-16";
மைல்கற்கள் = [மைல்கல்_ஆக்கு("M1", "2026-10-05", "2026-10-05", "2026-10-05", "எட்டியது"),
              மைல்கல்_ஆக்கு("M2", "2026-10-20", "2026-10-27", "", "தாமதம்"),
              மைல்கல்_ஆக்கு("M3", "2026-10-30", "2026-10-30", "", "இடரில்")];
பணிகள் = [பணி_ஆக்கு("T-1", "", "மூடியது", 100, 30, "2026-10-05"),
          பணி_ஆக்கு("T-2", "", "நடப்பில்", 50, 30, "2026-10-12")];

// __A delayed milestone makes it red. The reasons list every cause, red first,__
// __so the amber ones are not hidden behind it.__
// தாமதமான மைல்கல் சிவப்பாக்கும்; எல்லாக் காரணங்களும் சிவப்பு முதலில்
விடை = திட்ட_நலம்("2026-10-01", "2026-10-31", பொய், மைல்கற்கள், பணிகள், இன்று);
அச்சு விடை.நிறம்;
ஒவ்வொரு காரணம் இல் விடை.காரணங்கள் {
    அச்சு காரணம்;
}
அச்சு சொல்லாக்கு(விடை.நிறைவு) & " / " & சொல்லாக்கு(விடை.கழிந்தது);

// __With only the milestone that was met, the same tasks are amber: T-2 is overdue.__
// எட்டிய மைல்கல் மட்டும் இருந்தால் மஞ்சள்; இரண்டாம் பணி காலம் கடந்தது
அச்சு திட்ட_நலம்("2026-10-01", "2026-10-31", பொய், [மைல்கற்கள்[0]], பணிகள், இன்று).நிறம்;

// __Closed overrides everything, and carries no reasons.__
// மூடிய திட்டம் எல்லாவற்றையும் மீறும்; காரணங்கள் இல்லை
மூடியது = திட்ட_நலம்("2026-10-01", "2026-10-31", மெய், மைல்கற்கள், பணிகள், இன்று);
அச்சு மூடியது.நிறம் & " " & சொல்லாக்கு(நீளம்(மூடியது.காரணங்கள்));

nUlakam/qittam/uqavi/qittac_curukkam.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __திட்டச்_சுருக்கம்(திட்டக்_குறி, வாடிக்கையாளர், நலம்_விடை, பணிகள்) — one project, reduced to its portfolio line__
// ஒரு திட்டத்தின் தொகுப்பு வரி

இறக்கு "../paNi.qmz";
இறக்கு "../nalam.qmz";
இறக்கு "../pala_qittam.qmz";

// __ACME's billing portal on Monday 28 September: the API is half built and three__
// __days late, the UI has not started, and a 100-hour mainframe bridge was cancelled.__
// பாதி முடிந்த பணி தாமதம்; ஒன்று தொடங்கவில்லை; ஒன்று கைவிட்டது
இன்று = "2026-09-28";
பணிகள் = [பணி_ஆக்கு("API", "", "நடப்பில்", 50, 40, "2026-09-25"),
          பணி_ஆக்கு("UI", "", "செய்யவேண்டியது", 0, 24, "2026-10-16"),
          பணி_ஆக்கு("MFB", "", "கைவிட்டது", 0, 100, "2026-10-30")];
நலம்_விடை = திட்ட_நலம்("2026-09-01", "2026-10-31", பொய், [], பணிகள், இன்று);

// __The health is computed once, then passed in with the same tasks.__
// நலம் ஒருமுறை கணிக்கப்பட்டு அதே பணிகளுடன் தரப்படும்
வரி_ஒன்று = திட்டச்_சுருக்கம்("BK-ACM-0001", "ACME", நலம்_விடை, பணிகள்);
அச்சு வரி_ஒன்று.திட்டக்_குறி & " " & வரி_ஒன்று.வாடிக்கையாளர் & " " & வரி_ஒன்று.நிறம்;
அச்சு சொல்லாக்கு(வரி_ஒன்று.நிறைவு) & "% நிறைவு, " & சொல்லாக்கு(வரி_ஒன்று.நிலுவைப்_பணிகள்) & " நிலுவை";

// __The cancelled bridge's 100 hours weigh nothing: the project is 64 hours, not 164.__
// கைவிட்ட பணியின் மணிகள் கணக்கில் இல்லை
அச்சு சொல்லாக்கு(வரி_ஒன்று.மொத்த_மணி);

// __The line does not keep the reasons; read those from the health itself.__
// காரணங்கள் சுருக்கத்தில் இல்லை; நலத்திலிருந்தே படிக்க வேண்டும்
அச்சு புலம்_உள்ளதா(வரி_ஒன்று, "காரணங்கள்");
அச்சு நலம்_விடை.காரணங்கள்[0];

nUlakam/qittam/uqavi/qotarpu_Akku.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __தொடர்பு_ஆக்கு(முன்னோடிக்_குறி, பின்தொடர்க்_குறி, தொடர்பு_வகை, தாமதம்) — a dependency, with its type and its lag__
// இரு முனைகளுக்கு இடையே ஒரு சார்பு

இறக்கு "../pakuppu.qmz";
இறக்கு "../pAqY.qmz";
இறக்கு "../qotarpu.qmz";
இறக்கு "../curukkal.qmz";
இறக்கு "../kattuppAtu.qmz";
இறக்கு "../Ittu_maqippu.qmz";
இறக்கு "../oppanqa_vakY.qmz";

// __Finish-to-start with no lag is the ordinary one, and the only one most__
// __tools draw well.__
// தாமதமில்லா முடிவு-தொடக்கம் என்பதே வழக்கமானது
வழக்கமானது = தொடர்பு_ஆக்கு("P", "Q", "முடிவு_தொடக்கம்", 0);
அச்சு வழக்கமானது["வகை"];

// __A lag is waiting time that is not work: concrete curing, a permit in the__
// __post. Modelling it as an activity would give somebody a task to do.__
// தாமதம் என்பது வேலையல்லாத காத்திருப்பு; செயலாக்கினால் யாரோ ஒருவர் வேலை செய்ய வேண்டியிருக்கும்
காத்திருப்பு = தொடர்பு_ஆக்கு("P", "Q", "முடிவு_தொடக்கம்", 7);
அச்சு காத்திருப்பு["தாமதம்"];

// __And a negative lag is a lead: the follower may start before the__
// __predecessor has finished.__
// எதிர்மறைத் தாமதம் என்பது முன்னோட்டம்
அச்சு தொடர்பு_ஆக்கு("P", "Q", "முடிவு_தொடக்கம்", 0 - 2)["தாமதம்"];

// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __தொடர்பு_சுற்று_எல்லை() — how many passes the dependency solver will make__
// வலையைக் கணக்கிடும்போது எத்தனை சுற்று வரை

இறக்கு "../pakuppu.qmz";
இறக்கு "../pAqY.qmz";
இறக்கு "../qotarpu.qmz";
இறக்கு "../curukkal.qmz";
இறக்கு "../kattuppAtu.qmz";
இறக்கு "../Ittu_maqippu.qmz";
இறக்கு "../oppanqa_vakY.qmz";

// __A bound rather than a loop that runs until nothing changes. Start-to-finish__
// __links with leads can be written so that they never settle, and a planning__
// __tool that hangs on a bad network is worse than one that refuses it.__
// நிலைக்காத வலைகள் உண்டு; தொங்குவதைவிட மறுப்பதே மேல்
அச்சு தொடர்பு_சுற்று_எல்லை();

nUlakam/qittam/uqavi/qotarpu_katumYyAZav:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __தொடர்பு_கடுமையானவை(வலை_விடை) — the critical nodes of a precedence network__
// இளைப்பே இல்லாத முனைக் குறிகள்

இறக்கு "../pakuppu.qmz";
இறக்கு "../pAqY.qmz";
இறக்கு "../qotarpu.qmz";
இறக்கு "../curukkal.qmz";
இறக்கு "../kattuppAtu.qmz";
இறக்கு "../Ittu_maqippu.qmz";
இறக்கு "../oppanqa_vakY.qmz";

முனைகள் = [முனை_ஆக்கு("P", "தளம் தயார்", 4),
            முனை_ஆக்கு("Q", "அடித்தளம்", 6),
            முனை_ஆக்கு("R", "ஆய்வு", 1)];
தொடர்புகள் = [தொடர்பு_ஆக்கு("P", "Q", "முடிவு_தொடக்கம்", 0),
               தொடர்பு_ஆக்கு("P", "R", "முடிவு_தொடக்கம்", 0)];

// __Codes rather than whole records, because this is usually asked in order to__
// __test membership.__
// முழுப் பதிவேடுகள் அல்ல, குறிகளே
விடை = மதிப்பு(தொடர்பு_வலையைக்_கணக்கிடு(முனைகள், தொடர்புகள்));
ஒவ்வொரு ஒரு_குறி இல் தொடர்பு_கடுமையானவை(விடை) { அச்சு ஒரு_குறி; }

nUlakam/qittam/uqavi/qotarpu_muZYyiZ_pul:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __தொடர்பு_முனையின்_புலம்(வலை_விடை, முனைக்_குறி, புலப்_பெயர்) — one field of one solved node__
