// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/vaZporuL/pOli.qmz — போலி: driving the simulated board, for tests__
// போலி: போலிப் பலகையை இயக்குதல், சோதனைக்காக
//
// __These set what an input reads, move simulated time forward, and feed and__
// __read a simulated serial port — so hardware logic can be tested with__
// __etamil --vm before anything is uploaded to a board.__
//
// __What a test uses to play the outside world: a switch pressed, a sensor__
// __reading, time passing, a line arriving on a port. On any other board these__
// __are refused by the host.__

// __போலி_முனை(முனை, இயக்கம்) — set what an input pin reads__
// போலி_முனை(முனை, இயக்கம்) — உள்ளீட்டு முனை என்ன படிக்க வேண்டும் என்று அமைக்கும்
செயல் போலி_முனை(முனை, இயக்கம்) {
    மட்டம் = 0;
    (இயக்கம்) எனில் { மட்டம் = 1; }
    மதிப்பு(_simSetPin(முனை, மட்டம்));
}

// __போலி_ஒப்புமை(முனை, அளவீடு) — set what an analog pin reads, 0 to 1023__
// போலி_ஒப்புமை(முனை, அளவீடு) — ஒப்புமை முனை என்ன படிக்க வேண்டும் என்று அமைக்கும்
செயல் போலி_ஒப்புமை(முனை, அளவீடு) {
    மதிப்பு(_simSetAnalog(முனை, அளவீடு));
}

// __போலி_நேரம்(மில்லி) — move simulated time forward__
// போலி_நேரம்(மில்லி) — போலி நேரத்தை முன்னே நகர்த்தும்
செயல் போலி_நேரம்(மில்லி) {
    மதிப்பு(_simAdvanceMs(மில்லி));
}

// __போலி_தொடர்_ஊட்டு(சாதனம், வரி) — make a line arrive on a simulated port__
// போலி_தொடர்_ஊட்டு(சாதனம், வரி) — போலித் துறையில் ஒரு வரி வந்ததாக்கும்
செயல் போலி_தொடர்_ஊட்டு(சாதனம், வரி) {
    மதிப்பு(_simFeedSerial(சாதனம், வரி));
}

// __போலி_தொடர்_வெளியீடு(சாதனம்) — the lines the program wrote to a simulated port since the last call__
// போலி_தொடர்_வெளியீடு(சாதனம்) — கடைசி அழைப்புக்குப் பின் நிரல் எழுதிய வரிகள்
செயல் போலி_தொடர்_வெளியீடு(சாதனம்) {
    திரும்பு _simSerialOutput(சாதனம்);
}

nUlakam/vaZporuL/qotarqquRY.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/vaZporuL/qotarqquRY.qmz — தொடர்த்துறை: serial ports__
// தொடர்த்துறை: தொடர் இணைப்புகள்
//
// __தொடர்_வரி_படி answers சரி("") when nothing has arrived yet and தவறு only__
// __when something is wrong. A device that has not spoken is not a fault, and a__
// __caller that cannot tell the two apart will retry the wrong one.__
//
// __A port is named the host's way: "/dev/ttyACM0" on a Pi, "COM5" on Windows,__
// __"sim:<name>" on the simulated board. Under artino, 0 is the USB port and__
// __1, 2, 3 are the hardware ports.__

// __தொடர்_திற(சாதனம், வேகம்) — open a serial port at a baud rate: சரி(port) or தவறு(why)__
// தொடர்_திற(சாதனம், வேகம்) — சொன்ன வேகத்தில் தொடர்த் துறையைத் திறக்கும்
செயல் தொடர்_திற(சாதனம், வேகம்) {
    திரும்பு _serialOpen(சாதனம், வேகம்);
}

// __தொடர்_வரி_படி(துறை, காலம்) — the next whole line, waiting up to காலம் ms: சரி(line), சரி("") if none has arrived yet, or தவறு(why)__
// தொடர்_வரி_படி(துறை, காலம்) — அடுத்த முழு வரி; சொன்ன காலம் வரை காத்திருக்கும்
//
// __காலம் 0 does not wait at all, which is what a firmware loop wants. "No line__
// __yet" is empty text rather than இன்மை because a board has no இன்மை, and one__
// __answer on every board is what lets one program run on all of them.__
செயல் தொடர்_வரி_படி(துறை, காலம்) {
    விடை = _serialReadLine(துறை, காலம்);
    ((சரியா(விடை)) மற்றும் (மதிப்பு(விடை) == இன்மை)) எனில் { திரும்பு சரி(""); }
    திரும்பு விடை;
}

// __தொடர்_எழுது(துறை, செய்தி) — send text as it is__
// தொடர்_எழுது(துறை, செய்தி) — உரையை அப்படியே அனுப்பும்
செயல் தொடர்_எழுது(துறை, செய்தி) {
    திரும்பு _serialWrite(துறை, செய்தி);
}

// __தொடர்_வரி_எழுது(துறை, செய்தி) — send text and end the line__
// தொடர்_வரி_எழுது(துறை, செய்தி) — உரையை அனுப்பி வரியை முடிக்கும்
செயல் தொடர்_வரி_எழுது(துறை, செய்தி) {
    திரும்பு _serialWrite(துறை, செய்தி & "\n");
}

// __தொடர்_மூடு(துறை) — close a port__
// தொடர்_மூடு(துறை) — துறையை மூடும்
செயல் தொடர்_மூடு(துறை) {
    திரும்பு _serialClose(துறை);
}

nUlakam/vaZporuL/rAspY.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/vaZporuL/rAspY.qmz — ராஸ்பை: the Raspberry Pi's pins, and the hardware API__
// ராஸ்பை: ராஸ்பெரி பை பலகையின் முனைகளும் வன்பொருள் இடைமுகமும்
//
//   __இறக்கு "nUlakam/vaZporuL/rAspY.qmz";__
//   __etamil --vm prog.qmz__
//
// __For a Raspberry Pi 3, 4 or 5 running the eTamil VM. It is not an artino__
// __board: a Pi runs eTamil itself. Pin numbers are BCM GPIO numbers;__
// __தலைப்பு_முனை turns a physical pin on the 40-pin header into one, since that__
// __is how wiring diagrams number them.__
//
// __3.3 V, and the pins are not 5 V tolerant. There are no analog inputs:__
// __ஒப்புமை_படி is refused, naming an external ADC such as the MCP3008.__

இறக்கு "vaZporuL.qmz";

// __The boards this file describes. artino checks it against --board.__
நிலை சொல் பலகைக்_கோப்பு = "pi";

// __Serial: the header's UART, and an Arduino plugged in by USB__
நிலை சொல் தொடர்_சாதனம் = "/dev/serial0";      // __turn the serial port on, and the login shell on it off, in raspi-config__
நிலை எண் தொடர்_அனுப்பு_முனை = 14;              // __GPIO14, TXD: header pin 8__
நிலை எண் தொடர்_பெறு_முனை = 15;                 // __GPIO15, RXD: header pin 10__
நிலை சொல் USB_தொடர்_சாதனம் = "/dev/ttyACM0";  // __an Uno, Mega or Pico by USB; a Nano clone is often /dev/ttyUSB0__

// __I2C and SPI pins, for modules wired to them__
நிலை எண் I2C_SDA_முனை = 2;       // __header pin 3__
நிலை எண் I2C_SCL_முனை = 3;       // __header pin 5__
நிலை எண் SPI_MOSI_முனை = 10;     // __header pin 19__
நிலை எண் SPI_MISO_முனை = 9;      // __header pin 21__
நிலை எண் SPI_SCLK_முனை = 11;     // __header pin 23__
நிலை எண் SPI_CE0_முனை = 8;       // __header pin 24__
நிலை எண் SPI_CE1_முனை = 7;       // __header pin 26__

// __The BCM number of each header pin, 1 to 40; -1 for power and ground__
நிலை தலைப்பு_முனைகள் = [
    0 - 1, 0 - 1, 2, 0 - 1, 3, 0 - 1, 4, 14, 0 - 1, 15,
    17, 18, 27, 0 - 1, 22, 23, 0 - 1, 24, 10, 0 - 1,
    9, 25, 11, 8, 0 - 1, 7, 0, 1, 5, 0 - 1,
    6, 12, 13, 0 - 1, 19, 16, 26, 20, 0 - 1, 21
];

// __தலைப்பு_முனை(எண்ணிக்கை) — the BCM GPIO number of header pin 1–40, or -1 for a power or ground pin__
// தலைப்பு_முனை(எண்ணிக்கை) — தலைப்பு முனையின் உள்முனை எண்; மின்சார அல்லது நில முனையெனில் ஒன்று குறை
செயல் தலைப்பு_முனை(எண்ணிக்கை) {
    ((எண்ணிக்கை < 1) அல்லது (எண்ணிக்கை > 40)) எனில் { திரும்பு 0 - 1; }
    திரும்பு தலைப்பு_முனைகள்[எண்ணிக்கை - 1];
}

nUlakam/vaZporuL/uqavi/kAqqiru.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __காத்திரு(மில்லி) — pause for this many milliseconds__
// இத்தனை மில்லி நொடிகள் நிற்கும்

இறக்கு "../vaZporuL.qmz";
இறக்கு "../rAspY.qmz";

தொடக்கம் = மில்லி_நொடி();

// __On the simulated board a pause advances simulated time instead of actually__
// __waiting, so a program that blinks once a second can be tested in full__
// __without taking a second per blink.__
// போலிப் பலகையில் இது காத்திருப்பதில்லை; நேரத்தை நகர்த்துகிறது
காத்திரு(1000);
அச்சு மில்லி_நொடி() - தொடக்கம்;

// __On a real board it stops the program. Anything that has to keep responding__
// __while it waits should compare மில்லி_நொடி readings instead.__
// உண்மையான பலகையில் இது நிரலையே நிறுத்தும்

nUlakam/vaZporuL/uqavi/kAval_puquppi.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __காவல்_புதுப்பி() — tell the watchdog the program is still alive__
// நிரல் இன்னும் உயிரோடு இருப்பதைக் காவலிடம் சொல்லும்

இறக்கு "../vaZporuL.qmz";
இறக்கு "../rAspY.qmz";

காவல்_தொடங்கு(8000);

// __Called once per pass of the main loop, at the top. Not inside a helper and__
// __not from a timer: a watchdog fed by something other than the work it is__
// __watching will happily keep a stuck program running.__
// முதன்மை வளையத்தின் தொடக்கத்தில், ஒரு முறை
எண்ணி = 0;
(எண்ணி < 3) சுற்று {
    காவல்_புதுப்பி();
    காத்திரு(1000);
    எண்ணி = எண்ணி + 1;
}
