// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __nUlakam/vaZporuL/vaZporuL.qmz — வன்பொருள் (hardware): pins, time, serial__
// வன்பொருள்: முனைகள், நேரம், தொடர்த் துறை
//
// __One hardware vocabulary for every board eTamil runs on, so the same program__
// __drives a Raspberry Pi and an Arduino:__
//
//   __etamil --vm prog.qmz                   Raspberry Pi: real GPIO and serial ports__
//   __ETAMIL_BOARD=sim etamil --vm prog.qmz  any machine: a simulated board, for tests__
//   __etamil --artino --board uno prog.qmz   Arduino: compiled (docs/artino.md)__
//
// __Beside this file, one per board, are its pin names: yUnO.qmz (Uno), nAnO.qmz__
// __(Nano), mekA.qmz (Mega), pIkO.qmz (Pico and Pico 2), rAspY.qmz (Raspberry Pi).__
// __Each imports this file, so a program imports its board's file and nothing__
// __else, and names விளக்கு_முனை or ஒப்புமை_0 rather than 13 or 14.__
//
// __On the VM each function is a thin layer over a host builtin, called by its__
// ___english alias. Board state — pin levels, simulated time, serial buffers —__
// __lives in the host, because an eTamil function cannot change a module's__
// __variables. Under artino the compiler maps these same names to the board's__
// __own calls and does not run this file's bodies.__
//
// __Two rules shape the surface:__
// __- Pin and time calls return plain values. A pin that cannot be driven is a__
// __  wiring or permission mistake, found the first time the program runs, so it__
// __  stops the program with the host's message rather than becoming a result__
// __  every caller must check.__
// __- A serial port can be absent or unplugged at any time, so opening one gives__
// __  a result (சரி or தவறு) that the program is expected to handle.__
//
// __The VM's side is src/vm/board.rs: the simulated board anywhere, a Raspberry__
// __Pi's pins through the Linux GPIO device, and serial ports by device path on__
// __Linux and macOS.__

// __--- the board --------------------------------------------------------------__

// __Split into the files below. This one keeps the name so that every__
// __`இறக்கு` of it still reaches every function it used to.__

இறக்கு "muZY.qmz";
இறக்கு "nEram.qmz";
இறக்கு "qotarqquRY.qmz";
இறக்கு "pOli.qmz";

nUlakam/vaZporuL/vaZporuL_cOqaZY.qmz:
// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 Mohammed Maruff (Esan Maruff) <esan@etamil.in>
// __வன்பொருள் சோதனை — pins, time and serial on the simulated board__
// போலிப் பலகையில் முனை, நேரம், தொடர்த் துறைக்கான சோதனைகள்
//
//   __ETAMIL_BOARD=sim etamil --vm nUlakam/vaZporuL/vaZporuL_cOqaZY.qmz__
//
// __Runs on any machine: nothing here touches real hardware. It needs the host__
// __builtins that vaZporuL.qmz is written over; until they land it stops at the__
// __first call.__

இறக்கு "../cOqaZY/cOqaZY.qmz";
இறக்கு "vaZporuL.qmz";

ஓட்டம் = சோதனை_தொடக்கம்("வன்பொருள் (pins, time, serial)");

ஓட்டம் = சமம்(ஓட்டம், பலகை(), "sim", "ETAMIL_BOARD=sim selects the simulated board");

// __--- pins -------------------------------------------------------------------__
முனை_வெளியீடு(13);
முனை_எழுது(13, மெய்);
ஓட்டம் = சமம்(ஓட்டம், முனை_படி(13), மெய், "an output reads back what was written");
முனை_மாற்று(13);
ஓட்டம் = சமம்(ஓட்டம், முனை_படி(13), பொய், "toggling a high output makes it low");
முனை_மாற்று(13);
ஓட்டம் = சமம்(ஓட்டம், முனை_படி(13), மெய், "and toggling again makes it high");

முனை_மேலிழு_உள்ளீடு(3);
ஓட்டம் = சமம்(ஓட்டம், முனை_படி(3), மெய், "a pulled-up input with nothing pressed reads high");
போலி_முனை(3, பொய்);
ஓட்டம் = சமம்(ஓட்டம், முனை_படி(3), பொய், "a switch to ground pressed reads low");

போலி_ஒப்புமை(14, 612);
ஓட்டம் = சமம்(ஓட்டம், ஒப்புமை_படி(14), 612, "an analog pin reads the value the test set");

// __--- time -------------------------------------------------------------------__
தொடக்கம் = மில்லி_நொடி();
போலி_நேரம்(250);
ஓட்டம் = சமம்(ஓட்டம், மில்லி_நொடி() - தொடக்கம், 250, "simulated time moves only when told");
காத்திரு(100);
ஓட்டம் = சமம்(ஓட்டம், மில்லி_நொடி() - தொடக்கம், 350, "a pause advances simulated time instead of waiting");

// __--- serial -----------------------------------------------------------------__
திறப்பு = தொடர்_திற("sim:bus", 19200);
ஓட்டம் = உறுதிசெய்(ஓட்டம், சரியா(திறப்பு), "a simulated port opens");
துறை = மதிப்பு(திறப்பு);

ஓட்டம் = சமம்(ஓட்டம், மதிப்பு(தொடர்_வரி_படி(துறை, 0)), "",
              "with nothing arrived, a zero-wait read gives empty text");
போலி_தொடர்_ஊட்டு("sim:bus", ">01,P*2F");
ஓட்டம் = சமம்(ஓட்டம், மதிப்பு(தொடர்_வரி_படி(துறை, 0)), ">01,P*2F",
              "a line that arrived is read whole, without its newline");

தொடர்_வரி_எழுது(துறை, "<01,1:N:182*3A");
தொடர்_எழுது(துறை, "புகை ");
தொடர்_வரி_எழுது(துறை, "இயல்பு");
ஓட்டம் = சமம்(ஓட்டம், போலி_தொடர்_வெளியீடு("sim:bus"), ["<01,1:N:182*3A", "புகை இயல்பு"],
              "written lines come out whole, and Tamil survives the port");
ஓட்டம் = சமம்(ஓட்டம், போலி_தொடர்_வெளியீடு("sim:bus"), [], "and each line is handed over once");

தொடர்_மூடு(துறை);
ஓட்டம் = உறுதிசெய்(ஓட்டம், தவறா(தொடர்_திற("/dev/இல்லாத_துறை", 9600)),
                   "a port that does not exist is a தவறு, not a crash");

சோதனை_முடிவு(ஓட்டம்);

